import 'models.dart';

final List<Song> allSongs = [
  Song(id: 1, number: 1,
    title: "All Hail The Power of Jesus Name",
    author: "Edward Perronet",
    parts: [
      Verse(1, "All hail the power of Jesus’ name!\nLet angels prostrate fall (2)\nBring forth the royal diadem\nAnd crown Him Lord of all!"),
      Verse(2, "Ye saints redeemed of Adam’s race,\nYe ransomed from the fall (2)\nHail Him who saves you by His grace,\nAnd crown him Lord of all!"),
      Verse(3, "Sinners, whose love can ne’er forget\nThe wormwood and the gall (2)\nGo spread your trophies at His feet,\nAnd crown Him Lord of all!"),
      Verse(4, "Let every kindred, every tribe\nOn this terrestrial ball (2)\nTo Him all majesty ascribe,\nAnd crown Him Lord of all!"),
      Verse(5, "Crown Him, ye martyrs of your God,\nWho from His alter call (2)\nExtol the Stem of Jesse’s Rod,\nAnd crown Him Lord of all!"),
      Verse(6, "O that with yonder sacred throng\nWe at His feet may fall (2)\nJoin in the everylasting song,\nAnd crown Him Lord of all!"),
    ],
  ),
  Song(id: 2, number: 2,
    title: "To God be The Glory",
    author: "Fanny Crosby",
    parts: [
      Verse(1, "To God be the glory, great things He hath done,\nSo loved He the world that He gave us His Son,\nWho yielded His life an atonement for sin,\nAnd opened the life-gate that all may go in."),
      Chorus("Praise the Lord, praise the Lord,\nLet the earth hear His voice!\nPraise the Lord, praise the Lord,\nLet the people rejoice!\nO come to the Father, through Jesus the Son,\nAnd give Him the glory, great things He has done."),
      Verse(2, "O perfect redemption, the purchase of blood,\nTo every believer the promise of God;\nThe vilest offender who truly believes,\nThat moment from Jesus a pardon receives."),
      Verse(3, "Great things He has taught us, great things He has done,\nAnd great our rejoicing through Jesus the Son;\nBut purer, and higher, and greater will be\nOur wonder, our transport, when Jesus we see."),
    ],
  ),
  Song(id: 3, number: 3,
    title: "Rejoice and Be Glad!",
    author: "Horatius Bonar",
    parts: [
      Verse(1, "Rejoice and be glad!\nThe Redeemer has come!\nGo look on His cradle,\nHis cross, and His tomb."),
      Chorus("Sound His praises, tell the story\nOf Him who was slain;\nSound His praises, tell with gladness,\nHe liveth again."),
      Verse(2, "Rejoice and be glad!\nIt is sunshine at last!\nThe clouds have departed,\nThe shadows are past."),
      Verse(3, "Rejoice and be glad!\nFor the blood has been shed;\nRedemption is finished,\nThe price has been paid."),
      Verse(4, "Rejoice and be glad!\nNow the pardon is free!\nThe just for the unjust\nHas died on the tree."),
      Verse(5, "Rejoice and be glad!\nFor the lamb that was slain\nO’er death is triumphant,\nAnd liveth again."),
      Verse(6, "Rejoice and be glad!\nFor He cometh again;\nHe cometh to glory,\nThe lamb that was slain."),
    ],
  ),
  Song(id: 4, number: 4,
    title: "I Will Sing of My Redeemer",
    author: "Philip P. Bliss",
    parts: [
      Verse(1, "I will sing of my Redeemer,\nAnd His wondrous love to me;\nOn the cruel cross He suffered,\nFrom the curse to set me free."),
      Chorus("Sing, oh sing, of my Redeemer,\nWith his blood, He purchased me,\nOn the cross, He sealed my pardon,\nPaid the debt, and made me free."),
      Verse(2, "I will tell the wondrous story,\nHow my lost estate to save,\nIn His boundless love and mercy,\nHe the ransom freely gave."),
      Verse(3, "I will praise my dear Redeemer,\nHis triumphant pow’r I’ll tell,\nHow the victory He giveth\nOver sin, and death, and hell."),
      Verse(4, "I will sing of my Redeemer,\nAnd His heav’nly love to me;\nHe from death to life hath brought me,\nSon of God with Him to be."),
    ],
  ),
  Song(id: 5, number: 5,
    title: "O Worship The King, All Glorious Above",
    author: "Robert Grant",
    parts: [
      Verse(1, "O worship the King all-glorious above,\nO gratefully sing his power and his love:\nOur shield and defender, the Ancient of Days,\nPavilioned in splendor and girded with praise."),
      Verse(2, "O tell of his might and sing of his grace,\nWhose robe is the light, whose canopy space.\nHis chariots of wrath the deep thunderclouds form,\nAnd dark is his path on the wings of the storm."),
      Verse(3, "The earth with its store of wonders untold,\nAlmighty, Thy power hath founded of old;\nEstablished it fast by a changeless decree,\nAnd round it hath cast, like a mantle, the sea."),
      Verse(4, "Thy bountiful care, what tongue can recite?\nIt breathes in the air, it shines in the light;\nIt streams from the hills, it descends to the plain,\nAnd sweetly distills in the dew and the rain."),
      Verse(5, "Frail children of dust, and feeble as frail,\nIn you do we trust, nor find you to fail.\nYour mercies, how tender, how firm to the end,\nOur Maker, Defender, Redeemer, and Friend!"),
      Verse(6, "O measureless Might, unchangeable Love,\nWhom angels delight to worship above!\nYour ransomed creation, with glory ablaze,\nIn true adoration shall sing to your praise!"),
    ],
  ),
  Song(id: 6, number: 6,
    title: "Holy, Holy, Holy! Lord God Almighty!",
    author: "Reginald Heber",
    parts: [
      Verse(1, "Holy, holy, holy! Lord God Almighty!\nEarly in the morning our song shall rise to thee.\nHoly, holy, holy! merciful and mighty!\nGod in three Persons, blessed Trinity!"),
      Verse(2, "Holy, holy, holy! all the saints adore thee,\nCasting down their golden crowns around the glassy sea.\nCherubim and seraphim, falling down before thee,\nWho was and is and evermore shall be."),
      Verse(3, "Holy, Holy, Holy! though the darkness hide thee,\nThough the eye of sinful man thy glory may not see,\nOnly thou art holy; there is none beside thee,\nPerfect in pow'r, in love, and purity."),
      Verse(4, "Holy, holy, holy! Lord God Almighty!\nAll thy works shall praise thy name, in earth, and sky, and sea;\nHoly, holy, holy! merciful and mighty!\nGod in three Persons, blessed Trinity."),
    ],
  ),
  Song(id: 7, number: 7,
    title: "Praise My Soul The King of Heaven",
    author: "Henry Francis Lyte",
    parts: [
      Verse(1, "Praise, my soul, the King of heaven;\nTo his feet your tribute bring.\nRansomed, healed, restored, forgiven,\nWho like thee, His praise should sing?\nAlleluia! Alleluia!\nPraise the everlasting King!"),
      Verse(2, "Praise him for His grace and favor\nTo our fathers in distress.\nPraise him, still the same as ever,\nSlow to chide, and swift to bless.\nAlleluia! Alleluia!\nGlorious in his faithfulness!"),
      Verse(3, "Fatherlike He tends and spares us;\nWell our feeble frame He knows.\nIn His hands He gently bears us,\nRescues us from all our foes.\nAlleluia! Alleluia!\nWidely yet his mercy flows!"),
      Verse(4, "Angels, in the height adore Him;\nYe behold Him face to face;\nSun and moon, bow down before Him,\nDwellers all in time and space.\nAlleluia! Alleluia!\nPraise with us the God of grace."),
    ],
  ),
  Song(id: 8, number: 8,
    title: "O The Deep, Deep Love of Jesus",
    author: "Samuel Trevor Francis",
    parts: [
      Verse(1, "Oh, the deep, deep love of Jesus, vast, unmeasured, boundless, free\nRolling as a mighty ocean in its fullness over me!\nUnderneath me, all around me, is the current of His love\nLeading onward, leading homeward to His glorious rest above."),
      Verse(2, "Oh, the deep, deep love of Jesus, spread His praise from shore to shore!\nHow He loveth, ever loveth, changeth never, nevermore!\nHow He watches o’er His loved ones, died to call them all His own;\nHow for them He intercedeth, Watcheth o’er them from the throne!"),
      Verse(3, "Oh, the deep, deep love of Jesus love of ev’ry love the best!\n’Tis an ocean vast of blessing, ’tis a haven sweet of rest!\nOh, the deep, deep love of Jesus, ’tis a heav’n of heav’ns to me;\nAnd it lifts me up to glory, for it lifts me up to Thee!"),
    ],
  ),
  Song(id: 9, number: 9,
    title: "Look Ye Saints! The Sight is Glorious",
    author: "Thomas Kelly",
    parts: [
      Verse(1, "Look, ye saints, the sight is glorious:\nSee the Man of Sorrows now;\nFrom the fight returned victorious,\nEvery knee to Him shall bow.\nCrown Him! Crown Him!\nCrowns become the Victor's brow."),
      Verse(2, "Crown the Savior, angels, crown Him;\nRich the trophies Jesus brings;\nIn the seat of pow'r enthrone Him,\nWhile the vault of heaven rings.\nCrown Him! Crown Him!\nCrown the Savior King of kings."),
      Verse(3, "Sinners in derision crowned Him,\nMocking thus the Savior's claim;\nSaints and angels crowd around Him,\nOwn His title, praise His name.\nCrown Him! Crown Him!\nSpread abroad the Victor's fame!"),
      Verse(4, "Hark, those bursts of acclamation!\nHark! those loud triumphant chords!\nJesus takes the highest station;\nO what joy the si affords!\nCrown Him! Crown Him!\nKing of kings, and Lord of lords!"),
    ],
  ),
  Song(id: 10, number: 10,
    title: "O Lord My God! When I in Awesome Wonder",
    author: "Carl Boberg",
    parts: [
      Verse(1, "O Lord my God! When I in awesome wonder\nConsider all the works Thy hand hath made,\nI see the stars, I hear the mighty thunder,\nThy power throughout the universe displayed;"),
      Chorus("Then sings my soul, my Saviour God, to thee,\nHow great Thou art! How great Thou art!\nThen sings my soul, my Saviour God, to Thee,\nHow great Thou art! How great Thou art!"),
      Verse(2, "When through the woods and forest glades I wander\nAnd hear the birds sing sweetly in the trees;\nWhen I look down from lofty mountain grandeur\nAnd hear the brook and feel the gentle breeze"),
      Verse(3, "And when I think that God, His Son not sparing,\nSent Him to die – I scarce can take it in\nThat on the cross, my burden gladly bearing,\nHe bled and died to take away my sin"),
      Verse(4, "When Christ shall come with shouts of acclamation\nAnd take me home – what joy shall fill my heart!\nThen shall I bow in humble adoration\nAnd there proclaim, ‘my God, how great Thou art!’"),
    ],
  ),
  Song(id: 11, number: 11,
    title: "Crown Him With Many Crowns",
    author: "Matthew Bridges & Godfrey Thring",
    parts: [
      Verse(1, "Crown Him with many crowns, the Lamb upon His throne.\nHark! how the heavenly anthem drowns all music but its own.\nAwake, my soul, and sing of Him who died for thee,\nAnd hail Him as thy matchless King through all eternity."),
      Verse(2, "Crown Him the Lord of love; behold His hands and side,\nRich wounds, yet visible above, in beauty glorified;\nNo angels in the sky can fully bear that sight,\nBut downward bends their burning eye at mysteries so bright."),
      Verse(3, "Crown Him the Lord of life, who triumphed o'er the grave,\nAnd rose victorious in the strife for those He came to save;\nHis glories now we sing who died and rose on high,\nWho died eternal life to bring and lives that death may die."),
      Verse(4, "Crown Him the Lord of years, the Potentate of time,\nCreator of the rolling spheres, ineffably sublime.\nAll hail, Redeemer, hail! For Thou hast died for me;\nThy praise and glory shall not fail throughout eternity."),
    ],
  ),
  Song(id: 12, number: 12,
    title: "Loved With Everylasting Love",
    author: "George Wade Robinson",
    parts: [
      Verse(1, "Loved with everlasting love, led by grace that love to know;\nGracious Spirit from above, Thou hast taught me it is so.\nOh, this full and perfect peace! Oh, this transport all divine!\nIn a love which cannot cease, I am His, and He is mine."),
      Verse(2, "Heaven above is softer blue, Earth around is sweeter green;\nSomething lives in every hue Christless eyes have never seen:\nBirds with gladder songs o’erflow, flowers with deeper beauties shine,\nSince I know, as now I know, I am His, and He is mine."),
      Verse(3, "Things that once were wild alarms cannot now disturb my rest;\nClosed in everlasting arms, pillowed on the loving breast.\nOh, to lie forever here, doubt and care and self resign,\nWhile He whispers in my ear, I am His, and He is mine."),
      Verse(4, "His forever, only His: Who the Lord and me shall part?\nAh, with what a rest of bliss Christ can fill the loving heart.\nHeaven and earth may fade and flee, Firstborn light in gloom decline;\nBut, while God and I shall be, I am His, and He is mine."),
    ],
  ),
  Song(id: 13, number: 13,
    title: "It Passeth Knowledge, That Dear Love of Thine!",
    author: "Mary Shekleton",
    parts: [
      Verse(1, "It passeth knowledge, that dear love of Thine!\nLord Jesus! Savior! yet this soul of mine\nWould of Thy love in all its breadth and length,\nIts height and depth, its everlasting strength\nKnow more and more."),
      Verse(2, "It passeth telling, that dear love of Thine!\nLord Jesus! Savior! yet these lips of mine\nWould fain proclaim to sinners, far and near,\nA love which can remove all guilty fear,\nAnd love beget."),
      Verse(3, "It passeth praises, that dear love of Thine!\nLord Jesus! Savior! yet this heart of mine\nWould sing that love, so full, so rich, so free,\nWhich brings a rebel sinner, even me,\nRight home to God."),
      Verse(4, "But though I cannot sing, or tell, or know,\nThe fullness of Thy love, while here below,\nMy empty vessel I may freely bring;\nO Thou, who art of love the living spring,\nMy vessel fill."),
      Verse(5, "Then fill me, O my Savior with Thy love;\nLead, lead me to the living fount above!\nThither may I, in simple faith draw nigh,\nAnd never to another fountain fly,\nBut unto Thee."),
      Verse(6, "And when, Lord Jesus, Thine own face I see,\nWhen at Thy lofty throne, I bow the knee,\nThen of Thy love, in all its breadth and length,\nIts height and depth, its everlasting strength,\nMy soul shall sing."),
    ],
  ),
  Song(id: 14, number: 14,
    title: "Immortal, Invisible God Only Wise",
    author: "Walter Chalmers Smith",
    parts: [
      Verse(1, "Immortal, invisible, God only wise,\nIn light inaccessible hid from our eyes,\nMost blessed, most glorious, the Ancient of Days,\nAlmighty, victorious, Thy great name we praise."),
      Verse(2, "Unresting, uuhasting, and silent as light,\nNor wanting, nor wasting, Thou rulest in might;\nThy justice like mountains high soaring above\nThy clouds, which are fountains of goodness and love."),
      Verse(3, "To all life Thou givest, to both great and small;\nIn all life Thou livest, the true life of all;\nWe blossom and flourish as leaves on the tree,\nAnd wither and perish, but nought changeth Thee."),
      Verse(4, "Great Father of Glory, pure Father of Light\nThine angels adore Thee, all veiling their sight;\nAll laud we would render, O help us to see:\n’Tis only the splendor of light hideth Thee."),
    ],
  ),
  Song(id: 15, number: 15,
    title: "Holy, Holy, Holy, Holy, Holy, Holy, Lord God Almighty",
    author: "Jimmy Owens",
    parts: [
      Verse(1, "Holy, holy, holy, holy, holy\nHoly, Lord God almighty\nAnd we lift our hearts before You\nAs a token of our love\nHoly, holy, holy, holy"),
      Verse(2, "Gracious Father, Gracious Father\nWe’re so glad to be Your children Gracious Father\nAnd we lift our heads before You\nAs a token of our love\nGracious Father, Gracious Father"),
      Verse(3, "Holy Spirit, Holy Spirit\nCome and fill our hearts anew Holy Spirit\nAnd we lift our voice before You\nAs a token of our love\nHoly Spirit, Holy Spirit"),
      Verse(4, "Hallelujah, Hallelujah\nHallelujah, Hallelujah\nAnd we lift our hearts before You\nAs a token of our love\nHallelujah, Hallelujah"),
    ],
  ),
  Song(id: 16, number: 16,
    title: "Joyful Joyful We Adore Thee",
    author: "Henry van Dyke",
    parts: [
      Verse(1, "Joyful, joyful, we adore Thee, God of glory, Lord of love;\nHearts unfold like flowers before You, opening to the sun above.\nMelt the clouds of sin and sadness; drive the dark of doubt away;\nGiver of immortal gladness, fill us with the light of day!"),
      Verse(2, "All Thy works with joy surround You,\nEarth and heav'n reflect Thy rays,\nStars and angels sing around Thee,\nCenter of unbroken praise;\nField and forest, vale and mountain, flowery meadow, flashing sea,\nSinging bird and flowing fountain call us to rejoice in Thee."),
      Verse(3, "Always giving and forgiving, ever blessing, ever blest,\nWellspring of the joy of living, ocean-depth of happy rest!\nThou our Father, Christ our Brother, all who live in love are Thine;\nTeach us how to love each other, lift us to the joy divine."),
      Verse(4, "Mortals, join the mighty chorus, which the morning stars began;\nFather love is reigning o’er us, brother love binds man to man.\nEver singing, march we onward, victors in the midst of strife;\nJoyful music leads us sunward in the triumph song of life."),
    ],
  ),
  Song(id: 17, number: 17,
    title: "Jesus, The Very Thought of Thee",
    author: "Bernard of Clairvaux",
    parts: [
      Verse(1, "Jesus, the very thought of Thee\nWith sweetness fills my breast;\nBut sweeter far Thy face to see,\nAnd in Thy presence rest."),
      Verse(2, "Nor voice can sing, nor heart can frame,\nNor can the memory find\nA sweeter sound than Thy blest Name,\nO Savior of mankind!"),
      Verse(3, "Hope of every contrite heart,\nO Joy of all the meek,\nTo those who fall, how kind Thou art!\nHow good to those who seek!"),
      Verse(4, "But what to those who find? Ah, this\nNor tongue nor pen can show;\nThe love of Jesus, what it is\nNone but His loved ones know."),
      Verse(5, "Jesus, our only Joy be Thou,\nAs Thou our Prize wilt be;\nJesus, be Thou our Glory now,\nAnd through eternity."),
    ],
  ),
  Song(id: 18, number: 18,
    title: "All Things Bright and Beautiful",
    author: "Cecil Frances Alexander",
    parts: [
      Chorus("All things bright and beautiful,\nAll creatures great and small,\nAll things_wise and wonderful;\nThe Lord God made them all."),
      Verse(1, "Each little flower that opens, each little bird that sings,\nHe made their glowing colors, He made their tiny wings."),
      Verse(2, "The purple-headed mountain, the river running by,\nThe sunset and the morning that brightens up the sky."),
      Verse(3, "The cold wind in the winter, the pleasant summer sun,\nThe ripe fruits in the garden, He made them every one."),
      Verse(4, "He gave us eyes to see them, and lips that we might tell\nHow great is God Almighty, who has made all things well."),
    ],
  ),
  Song(id: 19, number: 19,
    title: "Praise to The Lord, The Almighty, The King of Creation",
    author: "Joachim Neander",
    parts: [
      Verse(1, "Praise to the Lord, the Almighty, the King of creation!\nO my soul, praise Him, for He is thy   health and salvation!\nAll ye who hear, brothers and sisters draw near;\nPraise Him in glad adoration!"),
      Verse(2, "Praise to the Lord, who doth prosper thy work and defend thee;\nSurely His goodness and mercy here daily attend thee.\nPonder anew what the Almighty can do,\nIf with His love He befriend thee."),
      Verse(3, "Praise to the Lord, Who, when tempests their warfare are waging,\nWho, when the elements madly around thee are raging,\nBiddeth them cease, turneth their fury to peace,\nWhirlwinds and waters assuaging."),
      Verse(4, "Praise to the Lord, Who, when darkness of si is abounding,\nWho, when the godless do triumph, all virtue confounding,\nSheddeth His light, chaseth the horrors of night,\nSaint with His mercy surrounding."),
      Verse(5, "Praise to the Lord, O let all that is in me adore Him!\nAll that hath life and breath, come now with praises before Him.\nLet the Amen sound from His people again,\nGladly for aye we adore Him."),
    ],
  ),
  Song(id: 20, number: 20,
    title: "Amidst Us Our Beloved Stands",
    author: "Charles H. Spurgeon",
    parts: [
      Verse(1, "Amidst us our Beloved stands,\nAnd bids us view His pierced hands;\nPoints to the wounded feet and side,\nBlest emblems of the Crucified."),
      Verse(2, "What food luxurious loads the board\nWhen, at His table, sits the Lord!\nThe wine how rich, the bread how sweet,\nWhen Jesus deigns the guests to meet!"),
      Verse(3, "If now, with eyes defiled and dim,\nWe see the signs, but see not Him;\nOh, may His love the scales displace,\nAnd bid us see Him face to face!"),
      Verse(4, "Our former transports we recount\nWhen with Him in the holy mount;\nThese cause our souls to thirst anew\nThis marred but lovely face to view!"),
      Verse(5, "O glorious Bridegroom of our hearts,\nYour present smile a heav’n imparts!\nO lift the veil, if veil there be,\nLet every saint Thy glory see!"),
    ],
  ),
  Song(id: 21, number: 21,
    title: "Lord Jesus, I Love Thee, I know Thou Art Mine",
    author: "William Ralph Featherston",
    parts: [
      Verse(1, "Lord Jesus, I love Thee, I know Thou art mine;\nMy rock and my fortress, my surety divine\nMy gracious Redeemer, my song shall be now,\n‘Tis Thou who art worthy Lord Jesus, ‘tis Thou!"),
      Verse(2, "I love Thee, because Thou hast first loved me,\nAnd purchased my pardon on Calvary’s tree;\nI love Thee for wearing the thorns on Thy brow\n‘Tis Thou who art worthy, Lord Jesus, ‘tis Thou!"),
      Verse(3, "I would love Thee in life, I would love Thee in death,\nAnd praise Thee as long as Thou lendest me breath;\nAnd sing should the death-dew lie cold on my brow,\n‘Tis Thou who art worthy, Lord Jesus, ‘tis Thou!"),
      Verse(4, "And when the bright morn of Thy glory shall come\nAnd the children ascend to the Father’s glad home\nI’ll shout with Thy likeness impressed on my brow\n‘Tis Thou who art worthy, Lord Jesus, ‘tis Thou!"),
    ],
  ),
  Song(id: 22, number: 22,
    title: "Praise Him! Praise Him! Jesus, Our Blessed Redeemer!",
    author: "Fanny Crosby",
    parts: [
      Verse(1, "Praise Him! praise Him! Jesus, our blessed Redeemer!\nSing, O Earth, His wonderful love proclaim!\nHail Him! hail Him! highest archangels in glory;\nStrength and honor give to His holy name!\nLike a shepherd, Jesus will guard His children,\nIn His arms He carries them all day long;\nO ye saints that dwell in the mountains of Zion,\nPraise Him! praise Him! ever in joyful song!"),
      Verse(2, "Praise Him! praise Him! Jesus, our blessed Redeemer! \nFor our sins He suffered and bled and died;\nHe, our Rock, our Hope of eternal salvation,\nHail Him! hail Him! Jesus, the Crucified;\nLoving Savior, meekly enduring sorrow,\nCrowned with thorns that cruelly pierced His brow;\nOnce for us rejected, despised, and forsaken,\nPrince of Glory, ever triumphant now."),
      Verse(3, "Praise Him! praise Him! Jesus, our blessed Redeemer,\nHeav’nly portals, loud with hosannahs ring!\nJesus, Savior, reigneth for ever and ever;\nCrown Him! crown Him! Prophet and Priest and King!\nDeath is vanquished! Tell it with joy, ye faithful,\nWhere is now thy victory, boasting grave?\nJesus lives! No longer thy portals are cheerless;\nJesus lives, the mighty and strong to save."),
    ],
  ),
  Song(id: 23, number: 23,
    title: "All People That On Earth Do Dwell",
    author: "William Kethe",
    parts: [
      Verse(1, "All people that on earth do dwell,\nSing to the Lord with cheerful voice.\nHim serve with fear, His praise forth tell;\nCome ye before Him and rejoice."),
      Verse(2, "The Lord, ye know, is God indeed;\nWithout our aid He did us make;\nWe are His flock, He doth us feed,\nAnd for His sheep He doth us take."),
      Verse(3, "enter then His gates with praise;\nApproach with joy His courts unto;\nPraise, laud, and bless His name always,\nFor it is seemly so to do."),
      Verse(4, "For why? The Lord our God is good;\nHis mercy is for ever sure;\nHis truth at all times firmly stood,\nAnd shall from age to age endure."),
    ],
  ),
  Song(id: 24, number: 24,
    title: "O For a Thousand Tongues To Sing",
    author: "Charles Wesley",
    parts: [
      Verse(1, "O for a thousand tongues to sing\nMy great Redeemer’s praise,\nThe glories of my God and King,\nThe triumphs of His grace."),
      Verse(2, "Jesus! the name that charms our fears,\nThat bids our sorrows cease; \n’Tis music in the singer’s ears,\n’Tis life, and health, and peace."),
      Verse(3, "He speaks, and, listening to His voice,\nNew life the dead receive,\nThe mournful, broken hearts rejoice,\nThe humble poor believe."),
      Verse(4, "Hear Him, ye deaf; His praise, ye dumb,\nYour loosened tongues employ;\nYe blind, behold your Saviour come,\nAnd leap, ye lame, for joy."),
      Verse(5, "See all your sins on Jesus laid:\nThe Lamb of God was slain,\nHis soul was once an offering made\nFor every soul of man."),
      Verse(6, "He breaks the power of canceled sin,\nHe sets the prisoner free;\nHis blood can make the foulest clean;\nHis blood availed for me."),
      Verse(7, "My gracious Master and my God,\nAssist me to proclaim,\nTo spread through all the earth abroad,\nThe honors of Thy name."),
    ],
  ),
  Song(id: 25, number: 25,
    title: "Fairest of All The Earth Beside",
    author: "Herbert G. Tovey",
    parts: [
      Verse(1, "Fairest of all the earth beside,\nChiefest of all unto Thy bride,\nFullness divine in Thee I see,\nWonderful man of Calvary!"),
      Chorus("That man of Calvary\nHas won my heart from me\nAnd died to set me free\nBlest Man of Calvary!"),
      Verse(2, "Granting the Sinner life and peace,\nGranting the captive sweet release,\nShedding his blood to make us free\nMerciful man of Calvary!"),
      Verse(3, "Giving the gifts obtained for men,\nPouring out love beyond our ken,\nGiving us spotless purity,\nBountiful Man of Calvary!"),
      Verse(4, "Comfort of all my earthly way,\nJesus I’ll meet Thee some sweet day;\nCenter of glory Thee I’ll see,\nWonderful Man of Calvary!"),
    ],
  ),
  Song(id: 26, number: 26,
    title: "Praise The Savior, Ye Who Know Him!",
    author: "Thomas Kelly",
    parts: [
      Verse(1, "Praise the Savior, ye who know Him!\nWho can tell how much we owe Him?\nGladly let us render to Him\nAll we are and have."),
      Verse(2, "Jesus is the name that charms us;\nHe for conflicts fits and arms us;\nNothing moves and nothing harms us\nWhile we trust in Him."),
      Verse(3, "Trust in Him, ye saints, forever;\nHe is faithful, changing never;\nNeither force nor guile can sever\nThose He loves from Him."),
      Verse(4, "Keep us, Lord, oh, keep us cleaving\nTo Thyself and still believing,\nTill the hour of our receiving\nPromised joys with Thee."),
      Verse(5, "Then we shall be where we would be;\nThen we shall be what we should be;\nThings which are not now, nor could be,\nSoon shall be our own."),
    ],
  ),
  Song(id: 27, number: 27,
    title: "In The Name of Jesus",
    author: "Caroline Maria Noel",
    parts: [
      Verse(1, "In the Name of Jesus\nEvery knee shall bow,\nEvery tongue confess Him\nKing of glory now;\n’Tis the Father’s pleasure\nWe should call Him Lord,\nWho from the beginning\nWas the Mighty Word."),
      Verse(2, "Humbled for a season,\nTo receive a Name\nFrom the lips of sinners\nUnto whom He came,\nFaithfully He bore it\nSpotless to the last,\nBrought it back victorious,\nWhen from death He passed;"),
      Verse(3, "Bore it up triumphant,\nWith its human light,\nThrough all ranks of creatures,\nTo the central height;\nTo the throne of Godhead,\nTo the Father’s breast,\nFilled it with the glory\nOf that perfect rest."),
      Verse(4, "Brothers, this Lord Jesus\nShall return again,\nWith His Father’s glory,\nWith His angel train;\nFor all wreaths of empire\nMeet upon His brow,\nAnd our hearts confess Him\nKing of glory now."),
    ],
  ),
  Song(id: 28, number: 28,
    title: "Jesus Our Lord, With What Joy We Adore Thee",
    author: "Robert C. Chapman",
    parts: [
      Verse(1, "Jesus, our Lord, with what joy we adore Thee,\nChanting our praise to Thyself on the throne!\nBlest in Thy presence, we worship before Thee,\nOwn Thou art worthy, and worthy alone."),
      Chorus("Lord, Thou art worthy, Lord Thou art worthy\nLord, thou art worthy, and worthy alone!\nBlest in Thy presence we worship before Thee\nOwn Thou art worthy and worthy alone."),
      Verse(2, "Verily God, yet become truly human,\nLower than angels to die in our stead;\nHow hast Thou long promised “Seed of the woman”\nTrod on the serpent and bruised his head!"),
      Verse(3, "How didst Thou humble Thyself to be taken.\nLed by Thy creatures and nailed to the cross.\nHated of men, and of God too forsaken,\nShunning not darkness, the curse, and the loss!"),
      Verse(4, "How hast Thou triumphed, and triumphed with glory,\nBattled death’s forces, rolled back every wave!\nCan we refrain then from telling the story?\nLord, Thou art Victor o’er death and the grave."),
    ],
  ),
  Song(id: 29, number: 29,
    title: "When I Survey The Wonderous Cross",
    author: "Isaac Watts",
    parts: [
      Verse(1, "When I survey the wondrous cross\nOn which the Prince of glory died,\nMy richest gain I count but loss,\nAnd pour contempt on all my pride."),
      Verse(2, "Forbid it, Lord, that I should boast,\nSave in the cross of Christ my God!\nAll the vain things that charm me most,\nI sacrifice them to His blood."),
      Verse(3, "See from his head, His hands, His feet,\nSorrow and love flow mingled down!\nDid e’er such love and sorrow meet,\nOr thorns compose so rich a crown?"),
      Verse(4, "His dying crimson, like a robe,\nSpreads o’er His body on the tree;\nThen am I dead to all the globe,\nAnd all the globe is dead to me."),
      Verse(5, "Were the whole realm of nature mine\nThat were an offering far too small;\nLove so amazing, so divine,\nDemands mu soul, my life, my all."),
    ],
  ),
  Song(id: 30, number: 30,
    title: "Abba Father We Approach Thee",
    author: "James George Deck",
    parts: [
      Verse(1, "“Abba, Father,” we approach Thee\nIn our Savior’s precious name.\nWe, Thy children, here assembled,\nNow Thy promised blessing claim.\nFrom our sins His blood hath washed us,\n’Tis through Him our souls draw nigh,\nAnd Thy Spirit, too, has taught us,\n“Abba, Father,” thus to cry."),
      Verse(2, "Once as prodigals we wandered,\nIn our folly, far from Thee;\nBut Thy grace, o’er sin abounding,\nRescued us from misery.\nThou Thy prodigals hast pardoned,\nKissed us with a Father’s love,\nSpread the festive board, and called us,\nE’er to dwell with Thee above."),
      Verse(3, "Clothed in garments of salvation,\nAt Thy table is our place,\nWe rejoice, and thou rejoices,\nIn the riches of thy grace;\n“It is meet,” we hear Thee saying,\n“We should merry and be glad,\nI have found My once lost children,\nNow they live who once were dead.”"),
      Verse(4, "“Abba, Father!” all adore Thee,\nAll rejoice in Heav’n above,\nWhile in us they learn the wonders\nOf Thy wisdom, grace, and love;\nSoon before Thy throne assembled,\nAll thy children shall proclaim,\n“Glory, everlasting glory,\nBe to God and to the Lamb!”"),
    ],
  ),
  Song(id: 31, number: 31,
    title: "Who Is He In Yonder Stall",
    author: "Benjamin R. Hanby",
    parts: [
      Verse(1, "Who is He in yonder stall\nAt Whose feet the shepherds fall?"),
      Chorus("'Tis the Lord! O wondrous story!\n'Tis the Lord! The King of glory!\nAt His feet we humbly fall,\nCrown Him! crown Him, Lord of all!"),
      Verse(2, "Who is He in deep distress,\nFasting in the wilderness?"),
      Verse(3, "Who is He the people bless\nFor His words of gentleness?"),
      Verse(4, "Who is He to Whom they bring,\nAll the sick and sorrowing?"),
      Verse(5, "Who is He who stands and weeps\nAt the grave where Lazarus sleeps?"),
      Verse(6, "Who is He the gathering throng\nGreet with loud triumphant song?"),
      Verse(7, "Lo! At midnight, who is He\nPrays in dark Gethsemane?"),
      Verse(8, "Who is He on yonder tree\nDies in grief and agony?"),
      Verse(9, "Who is He that from the grave\nComes to succour, help and save?"),
      Verse(10, "Who is He that from His throne\nRules through all the world alone?"),
    ],
  ),
  Song(id: 32, number: 32,
    title: "One Day",
    author: "J. Wilbur Chapman",
    parts: [
      Verse(1, "One day when Heaven was filled with His praises,\nOne day when sin was as black as could be,\nJesus came forth to be born of a virgin,\nDwelt among men, my Example is He!"),
      Chorus("Living, He loved me; dying, He saved me;\nBuried, He carried my sins far away;\nRising, He justified freely forever;\nOne day He's coming—O glorious day!"),
      Verse(2, "One day they led Him up Calvary's mountain,\nOne day they nailed Him to die on the tree;\nSuffering anguish, despised and rejected:\nBearing our sins, my Redeemer is He!"),
      Verse(3, "One day they left Him alone in the garden,\nOne day He rested, from suffering free;\nAngels came down o'er His tomb to keep vigil;\nHope of the hopeless, my Savior is He!"),
      Verse(4, "One day the grave could conceal Him no longer,\nOne day the stone rolled away from the door;\nThen He arose, over death He had conquered;\nNow is ascended, my Lord evermore!"),
      Verse(5, "One day the trumpet will sound for His coming.\nOne day the skies with His glories will shine;\nWonderful day, my beloved ones bringing;\nGlorious Savior, this Jesus is mine!"),
    ],
  ),
  Song(id: 33, number: 33,
    title: "Man Of Sorrows! What A Name",
    author: "Philip P. Bliss",
    parts: [
      Verse(1, "Man of Sorrows! what a name\nFor the Son of God, Who came\nRuined sinners to reclaim.\nHallelujah! What a Savior"),
      Verse(2, "Bearing shame and scoffing rude,\nIn my place condemned He stood;\nSealed my pardon with His blood.\nHallelujah! What a Savior!"),
      Verse(3, "Guilty, vile, and helpless we;\nSpotless Lamb of God was He;\n\"Full atonement!\" can it be?\nHallelujah! What a Savior!"),
      Verse(4, "Lifted up was He to die;\n\"It is finished!\" was His cry;\nNow in Heav'n exalted high.\nHallelujah! What a Savior!"),
      Verse(5, "When He comes, our glorious King,\nAll His ransomed home to bring,\nThen anew His song we'll sing:\nHallelujah! What a Savior!"),
    ],
  ),
  Song(id: 34, number: 34,
    title: "No Blood, No Altar Now",
    author: "Horatius Bonar",
    parts: [
      Verse(1, "No blood, no altar now\nThe sacrifice is o'er\nNo flame, no smoke ascends on high\nThe lamb is slain no more\nBut richer blood has flowed from nobler veins\nTo purge the soul from guilt, and cleanse the reddest stain"),
      Verse(2, "We thank Thee for the blood\nThe blood of Christ, Thy Son\nThe blood by which our peace is made\nOur victory won\nGreat victory o'er hell, and sin, and woe\nThat needs no second fight and leaves no second foe"),
      Verse(3, "We thank Thee for the grace\nDescending from above\nThat overflows our widest guilt\nThe eternal Father's Love\nLove of the Father, everlasting Son\nLove of the Holy Ghost, Jehovah, three in One"),
      Verse(4, "We thank Thee for the hope\nSo glad, and sure and clear\nIt holds the drooping spirit up\nTill the long dawn appear\nFair hope! with what a sunshine does it cheer\nOur roughest path on earth, our dreariest desert here!"),
      Verse(5, "We thank Thee for the crown\nOf glory and of life\n'Tis no poor, with'ring wreath of earth\nMan's prize in mortal strife\n'Tis incorruptible as is the throne\nThe kingdom of our God and His incarnate Son"),
    ],
  ),
  Song(id: 35, number: 35,
    title: "Jesus, The Lord Our Righteousness!",
    author: "Nicolaus Ludwig von Zinzendorf",
    parts: [
      Verse(1, "Jesus, the Lord our Righteousness!\nOur beauty Thou, our glorious dress\n‘Midst flaming worlds. whilst thus arrayed\nWith joy shall we lift up our head"),
      Verse(2, "Bold shall we stand in that great day\nFor who aught to our charge shall lay?\nWhile by Thy blood absolved wear\nFrom sin's tremendous curse and fear"),
      Verse(3, "Thus Abraham, the friend of God\nThus all the saints redeemed by blood\nSaviour of sinners Thee proclaim\nAnd all their boast is in Thy Name"),
      Verse(4, "Till we behold Thee on Thy throne\nIn Thee we boast, in Thee alone\nOur beauty this, our glorious dress\nJesus, the Lord our Righteousness."),
    ],
  ),
  Song(id: 36, number: 36,
    title: "Jesus, Lord, We Know Thee Present",
    author: "James George Deck",
    parts: [
      Verse(1, "Jesus, Lord, we know Thee present\nAt Thy table freshly spread\nSeated at Thy priceless banquet\nWith Thy banner overhead\nPrecious moments at Thy table\nFrom all fear and doubt set free\nHere to rest, so sweetly able\nOccupied alone with Thee"),
      Verse(2, "Here rejoicing in Thy nearness\nGladly by Thy Spirit led\nCalmly in the blest remembrance\nOf Thy precious blood once shed\nLord, we take each simple token\nIn fond memory of Thee\nMuse upon Thy body broken\nAnd Thy blood shed on the tree"),
      Verse(3, "Oh what joy it is to see Thee\nIn these emblems gathered here!\nIn the bread and wine of blessing\nBread to strengthen, wine to cheer\nLord, behold us met together\nMembers of our risen Head\nThus to take the cup of blessing\nThus to share the broken bread"),
      Verse(4, "Lord, we know how true Thy promise\nTo be with us where we meet\nWhen in Thy loved Name we gather\nTo enjoy communion sweet\nDearer still that looked for promise\nto each waiting, yearning heart\nThat we soon will be with Thee, Lord\nAnd forever where Thou art."),
    ],
  ),
  Song(id: 37, number: 37,
    title: "How Sweet The Name of Jesus Sounds",
    author: "John Newton",
    parts: [
      Verse(1, "How sweet the Name of Jesus sounds\nIn a believer's ear!\nIt soothes his sorrows, heals his wounds,\nAnd drives away his fear."),
      Verse(2, "It makes the wounded spirit whole,\nAnd calms the Photo breast:\n'Tis manna to the hungry soul,\nAnd to the weary, rest."),
      Verse(3, "Dear Name, the Rock on which I build,\nMy Shield and Hiding Place\nMy never-failing treasury, filled\nWith boundless stores of grace!"),
      Verse(4, "Jesus my Shepherd, Husband, Friend,\nMy Prophet, Priest and King\nMy Lord, my Life, my Way my End,\nAccept the praise bring."),
      Verse(5, "Weak is the fort of my heart,\nAnd cold my warmest thought;\nBut when I see Thee as Thou art,\nI'll praise There as fought."),
      Verse(6, "Till then I would Thy love proclaim\nWith every fleeting breath,\nAnd may the music of Thy Name\nRefresh my soul in death!"),
    ],
  ),
  Song(id: 38, number: 38,
    title: "Midst The Darkness, Storm and Sorrow",
    author: "Emma Frances Bevan",
    parts: [
      Verse(1, "Midst the darkness, storm and sorrow\nOne bright glam I see\nWell I know the blessed morrow\nChrist will come for me\nMidst the light and peace, and glory\nOf the Father's home\nChrist for me is watching, waiting\nWaiting till I come"),
      Verse(2, "Long the blessed Guide has led me\nBy the desert road\nNow I see the golden towers\nCity of my God\nThere, amidst the love and glory\nHe is waiting\nOn His hands a name is graven\nHe can ne'er forget"),
      Verse(3, "There, amidst the songs of heaven\nSweeter to His ear\nIs the footfall through the desert\nEver drawing near\nThere, made ready are the mansions\nGlorious, bright and fair\nBut the bride the Father gave Him\nStill is wanting there"),
      Verse(4, "Who is this, who comes to meet me\nOn the desert way?\nAs the Morning star foretelling\nGod's unclouded day\nHe it is who came to win me\nIn His glory well I know Him\nEvermore the same"),
      Verse(5, "Oh! the blessed joy of meeting\nAll the desert past\nOh! the wondrous words of greeting\nHe shall speak at last.\nHe and I together entering\nThose bright courts above\nHe and I together sharing\nAll the Father's love"),
      Verse(6, "Where no shade nor stain can enter\nNor the gold be dim\nIn that holiness unsullied\nI shall walk with Him\nMeet companion, then, for Jesus\nFrom Him, for Him, made\nGlory of God's grace for ever.\nThere in me displayed"),
      Verse(7, "He, who in the hour of sorrow\nBore the curse alone\nI, who through the lonely desert\nTrod where He had gone\nHe and I, in that bright glory\nOne deep joy shall share\nMine, to be for ever with Him\nHis, that I am there"),
    ],
  ),
  Song(id: 39, number: 39,
    title: "To Calvary, Lord, in Spirit, Now",
    author: "Sir Edward Denny",
    parts: [
      Verse(1, "To Calvary, Lord, in spirit, now\nOur weary souls repair\nTo dwell upon Thy dying love\nAnd taste its sweetness there"),
      Verse(2, "Sweet resting place of every heart\nThat feels the plague of sin\nYet knows the deep, mysterious joy\nOf peace with God within"),
      Verse(3, "There, through Thine hour of deepest woe\nThy suffering Spirit passed\nGrace there its wondrous victory gained\nAnd love endured its last"),
      Verse(4, "O Lamb of God! Thy bleeding wounds,\nWith cords of love divine\nHave drawn our willing hearts to Thee\nAnd linked our life with Thine"),
      Verse(5, "Our longing eyes would fain behold\nThat bright and blessed brow\nOnce wrung with bitterest anguish wear\nIts crown of glory now"),
      Verse(6, "Thy sympathies and hopes are ours\nWe long, O Lord, to see\nCreation all - below, above\nRedeemed and blessed by Thee"),
    ],
  ),
  Song(id: 40, number: 40,
    title: "King of My Life, I Crown Thee Now",
    author: "Jennie Evelyn Hussey",
    parts: [
      Verse(1, "King of my life, I crown Thee now,\nThine shall the glory be;\nLest I forget Thy thorn crowned brow,\nLead me to Calvary."),
      Chorus("Lest I forget Gethsemane.\nLest I forget Thine agony;\nLest I forget Thy love for me,\nLead me to Calvary."),
      Verse(2, "Show me the tomb where Thou wast laid,\nTenderly mourned and wept;\nAngels in robes of light arrayed\nGuarded Thee whilst Thou slept."),
      Verse(3, "Let me like Mary, through the gloom,\nCome with a gift to Thee;\nShow to me now the empty tomb,\nLead me to Calvary."),
      Verse(4, "May I be willing, Lord, to bear\nDaily my cross for Thee;\nEven Thy cup of grief to share, \nThou hast borne all for me."),
    ],
  ),
  Song(id: 41, number: 41,
    title: "According to Thy gracious word",
    author: "James Montgomery",
    parts: [
      Verse(1, "According to Thy gracious word, \nIn meek humility, \nThis will I do, my dying Lord, \nI will remember Thee."),
      Verse(2, "Thy body, broken for my sake, \nMy bread from Heaven shall be: \nThy testamental cup I take, \nAnd thus remember Thee."),
      Verse(3, "Gethsemane can I forget? \nOr there Thy conflict see, \nThine agony, and blood-like sweat, \nAnd not remember Thee?"),
      Verse(4, "When to the cross I turn mine eyes, \nAnd rest on Calvary, \nO Lamb of God, my sacrifice, \nI must remember Thee;"),
      Verse(5, "Remember Thee, and all Thy pains \nAnd all Thy love to me; \nYea, while a breath, a pulse remains, \nWill I remember Thee."),
    ],
  ),
  Song(id: 42, number: 42,
    title: "O Blessed God! How Kind",
    author: "Samuel Stennett",
    parts: [
      Verse(1, "O blessed God! how kind \nAre all Thy ways to me, \nWhose dark benighted mind \nWas enmity with Thee\nYet now subdued by sovereign grace\nMy spirit longs for Thine embrace"),
      Verse(2, "How precious are Thy thoughts\nThat o'er my spirit roll!\nThey swell beyond my faults,\nAnd captivate my soul; How great their sum, how high they rise\nCan ne'er be known beneath the skies"),
      Verse(3, "Preserved by Jesus, when\nMy feet made haste to hell!\nAnd there should I have gone,\nBut Thou dost all things well; Thy love was great, Thy mercy free,\nWhich from the pit delivered me."),
      Verse(4, "Before Thy hands had made\nThe sun to rule the day,\nOr earth's foundations laid,\nOr fashioned Adam's clay. What thoughts of peace and mercy flowed\nIn Thy great heart of love, O God!"),
      Verse(5, "A monument of grace,\nA sinner saved by blood. The streams of love I trace\nUp to the fountain, God,\nAnd in His sovereign counsels see\nEternal thoughts of love to me."),
    ],
  ),
  Song(id: 43, number: 43,
    title: "Behold! Behold The Lamb of God, On The Cross",
    author: "Unknown",
    parts: [
      Verse(1, "Behold! behold the Lamb of God, on the cross;\nFor us He shed His precious blood on the cross.\nO hear His all important cry,\n'Eli, lama sabachthani?\"\nDraw near and see the Savior die\nOn the cross."),
      Verse(2, "Behold His arms extended wide on the cross: Behold His bleeding hands and side on the cross.\nThe sun withholds his rays of light,\nThe heav'ns are clothed in shades of night,\nWhile Jesus wins the glorious fight\nOn the cross."),
      Verse(3, "By faith we see Him lifted up, on the cross: He drinks for us the Pack Photo cup, on the Cross.\nThe rocks do rend, the mountains quake,\nWhile Jesus doth atonement make,\nWhile Jesus suffers for our sake,\nOn the cross."),
      Verse(4, "And now the mighty deed is done on the cross; The battle's fought, the victory's won on the cross.\nTo Heav'n He turns His dying eyes;\n'Tis finished! now the Conqueror cries;\nThen bows His sacred head and dies\nOn the cross."),
    ],
  ),
  Song(id: 44, number: 44,
    title: "My Redeemer! O What Beauties",
    author: "Thomas Kelly",
    parts: [
      Verse(1, "My Redeemer! O what beauties\nIn that lovely Name appear\nNone but Jesus, in His glories\nShall the honoured title wear\nMy Redeemer!\nThou hast my salvation wrought."),
      Verse(2, "Sunk in ruin, sin and mercy\nBound by Satan's captive chain\nGuided by his artful treachery\nHurrying on to endless pain\nMy Redeemer!\nPlucked me as a brand from hell"),
      Verse(3, "Mine by covenant, mine for ever\nMine by oath, and mine by blood\nMine - nor time the bond shall sever\nMine as an unchanging God\nMy Redeemer!\nO how sweet to call Thee mine!"),
      Verse(4, "When in heaven I see Thy glory\nWhen before Thy throne I bow\nPerfected I shall be like Thee\nFully Thy redemption know\nMy Redeemer!\nThen shall hear me shout His praise"),
    ],
  ),
  Song(id: 45, number: 45,
    title: "Who Can Cheer The Heart Like Jesus",
    author: "Thoro Harris",
    parts: [
      Verse(1, "Who can cheer the heart like Jesus\nBy His presence all divine?\nTrue and tender, pure and precious\nO how blest to call Him mine!"),
      Chorus("All that thrills my soul is Jesus\nHe is more than life to me\nAnd the fairest of ten thousand\nIn my blessed Lord I see"),
      Verse(2, "Love of Christ so freely given\nGrace of God beyond degree\nMercy higher than the heaven\nDeeper than the deepest sea"),
      Verse(3, "what a wonderful redemption!\nNever can a mortal know\nHow my sin though red like crimson\nCan be whiter than the snow"),
      Verse(4, "Every need His hand supplying\nEvery good in Him I see\nOn His strength divine relying\nHe is all in all to me"),
      Verse(5, "By the crystal flowing river\nWith the ransomed I will sing\nAnd for ever and for ever\nPraise and glorify the King"),
    ],
  ),
  Song(id: 46, number: 46,
    title: "Lamb of God! Our Souls Adore Thee",
    author: "James George Deck",
    parts: [
      Verse(1, "Lamb of God! Our souls adore Thee\nWhile upon Thy face we gaze;\nThere the Father's love and glory\nShine in all their brightest rays;\nThine almighty power and wisdom\nAll creation's works proclaim;\nHeaven and earth alike confession Thee\nAs the ever great \"I AM.\""),
      Verse(2, "Lamb of God! Thy Father's bosom Ever was Thy dwelling place;\nHis delight, in Him rejoicing, One with Him in power and grace;\nOh, that wondrous love and mercy- Thou didst lay Thy glory by,\nAnd for us didst come from Heaven, As the Lamb of God, to die!"),
      Verse(3, "Lamb of God! When we behold Thee Lowly in the manger laid\nWandering as a homeless stranger In the world Thy hands had made;\nWhen we see Thee in the garden, In Thine agony of blood,\nAt Thy grace we are confounded, Holy, spotless, Lamb of God!"),
      Verse(4, "When we see Thee, as the Victim, Bound for us upon the tree,\nFor our guilt and folly stricken, All our judgment born by Thee-\nLord, we own, with hearts adoring, Thou hast loved us unto blood: Glory, glory everlasting,\nBe to Thee, Thou Lamb of God!"),
    ],
  ),
  Song(id: 47, number: 47,
    title: "Through Thy Precious Body Broken Inside The Veil",
    author: "James George Deck",
    parts: [
      Verse(1, "Through Thy precious body broken inside the veil\nO what words to sinners spoken; Inside the veil\nPrecious as the blood that bought us\nPerfect as the love that sought us\nHoly as the Lamb that brought us; Inside the veil"),
      Verse(2, "When we see Thy love unshaken; Outside the camp\nScorned by man, by God forsaken; Outside the camp\nThy loved Cross alone can charm us\nShame need now no more alarm us\nGlad we follow, nought can harm us; Outside the camp"),
      Verse(3, "Lamb of God, through Thee we enter; Inside the veil\nCleansed by Thee, we boldly venture; Inside the veil\nNot a stain; a new creation\nOurs is such a full salvation\nLow we bow in adoration; Inside the veil"),
      Verse(4, "Unto Thee, the homeless stranger; Outside the camp\nForth be hasten, fear no danger; Outside the camp\nThy reproach, far richer treasure\nThan all Egypt's boasted pleasure\nDrawn by love that knows no measure; Outside the camp"),
      Verse(5, "Soon Thy saints shall all be gathered; Inside the veil\nAll at home, no more be scattered; Inside the veil\nNought from Thee our hearts shall sever\nWe shall see Thee, grieve Thee never\n\"Praise the Lamb!\" shall sound forever; Inside the veil"),
    ],
  ),
  Song(id: 48, number: 48,
    title: "Crowned With Thorns Upon The Tree",
    author: "Unknown",
    parts: [
      Verse(1, "Crowned with thorns upon the tree\nSilent in Thine agony\nDying, crushed beneath the load\nOf the wrath and curse of God"),
      Verse(2, "On Thy pale and suff'ring brow\nMystery of love and woe\nOn Thy grief and sore amaze\nSaviour, I would fix my gaze!"),
      Verse(3, "On Thy pierced and bleeding breast\nThou dost bid the weary rest\nRest there from the world's false ways\nRest there from its vanities"),
      Verse(4, "Rest in pardon and relief\nFrom the load of guilt and grief\nRest in Thy redeeming blood\nRest in perfect peace with God"),
      Verse(5, "Sin atoning Sacrifice\nThou art precious in mine eyes;\nThou alone my rest shall be\nNow and through eternity"),
    ],
  ),
  Song(id: 49, number: 49,
    title: "O Come, Thou Stricken Lamb of God!",
    author: "N. L. von Zinzendorf",
    parts: [
      Verse(1, "O come, Thou stricken Lamb of God!\nWho shed'st for us Thine own life blood\nAnd teach us all Thy love: then pain\nWere sweet, and life or death were gain"),
      Verse(2, "Take Thou-our hearts, and let them be\nFor ever closed to all but Thee\nThy willing servants, let us wear\nThe seal of love for ever there"),
      Verse(3, "How blest are they who still abide\nClose sheltered by Thy watchful side\nWho life and strength from Thee receive\nAnd with Thee move, and in Thee live!"),
      Verse(4, "Ah, Lord! enlarge our scanty thought\nTo know the wonders Thou hast wrought\nUnloose our stamm'ring tongues to tell\nThy love, immense, unsearchable"),
      Verse(5, "First-born of man brethren. Thou!\nTo whom both heaven and earth must bow\nHeirs of Thy shame and of Thy throne\nWe bear the cross, and seek the crown"),
    ],
  ),
  Song(id: 50, number: 50,
    title: "Glory Be To Him Who Loved Us",
    author: "Horatius Bonar",
    parts: [
      Verse(1, "Glory be to Him Who loved us,\nWashed us from each sinful stain;\nGlory be to Him Who made us\nPriests and kings with Him to reign;\nGlory, worship, laud and blessing\nTo the Lamb Who once was slain."),
      Verse(2, "\"Glory, worship, laud and blessing,\"\nThus the choir triumphant sings;\n\"Honor, riches, pow'r, dominion,'\nThus its praise creation brings;\nThou art worthy, Thou art worthy,\nLord of Lords, and King of kings."),
      Verse(3, "Glory to the King of angels,\nGlory to the Church's King,\nGlory to the King of nations,\nHeav' n and earth His praises sing:\nGlory ever and for ever\nTo the King of Glory bring."),
      Verse(4, "Glory be to Thee, O Father.\nGlory be to Thee, O Son,\nGlory be to Thee, O Spirit,\nGlory be to God alone,\nAs it was, is now, and shall be\nWhile the endless ages run."),
    ],
  ),
  Song(id: 51, number: 51,
    title: "Lamb of God! Thou now art seated",
    author: "James George Deck",
    parts: [
      Verse(1, "Lamb of God! Thou now art seated\nHigh upon Thy Father's throne\nAll Thy gracious work completed\nAll Thy might vict'ry won\nEvery knee in heaven is bending\nTo the lamb for sinners slain\nEvery voice and harp is swelling\n\"Worthy is the Lamb to reign\""),
      Verse(2, "Lord, in all Thy pow'r and glory\nStill Thy thoughts and eyes are here\nWatching o'er Thy ransomed people\nTo Thy gracious heart so dear\nThou for us art intercedeth\nEverlasting is Thy love\nAnd a blessed rest preparing\nIn the Father's house above"),
      Verse(3, "Lamb of God! Thou soon in glory\nWilt to this sad earth return\nAl Thy foes shall quake before Thee\nAll that now despise Thee mourn\nThen Thy saints all gathered to Thee\nWith thee in Thy kingdom reign\nThine the praise, and Thine the glory\nLamb of God, for sinners slain!"),
    ],
  ),
  Song(id: 52, number: 52,
    title: "O blessed Lord, what hast Thou done!",
    author: "James George Deck",
    parts: [
      Verse(1, "O blessed Lord, what hast Thou done!\nHow vast a ransom paid!\nWho could conceive God's only Son\nUpon the altar laid!"),
      Verse(2, "Thy Father, in His perfect love,\nDid spare Thee from His side;,\nAnd Thou did stoop to bear above,\nAt such a cost Thy bride."),
      Verse(3, "Lord, while our souls in faith repose\nUpon Thy precious blood,\nPeace like an even river flows,\nAnd mercy like a flood"),
      Verse(4, "But boundless joy shall fill our hearts\nWhen gazing on Thy face.\nWe fully see what faith imparts,\nAnd glory crowns Thy grace."),
      Verse(5, "Unseen we love Thee, dear Thy Name\nBut when our eyes behold,\nWith joyful wonder we` H exclaim,\nThe half hath not been told!"),
    ],
  ),
  Song(id: 53, number: 53,
    title: "The countless multitude on high",
    author: "Robert C. Chapman",
    parts: [
      Verse(1, "The countless multitude on high\nThat tune their songs to Jesus' name\nAll merit of their own deny\nAnd Jesus worth alone proclaim\nFirm on the ground of sovereign grace\nThey stand before Jehovah throne\nThe only song in that blest place\nIs, \"Thou art worthy! Thou alone!\""),
      Verse(2, "With spotless robes of purest white\nAnd branches of triumphal palm\nThey shout, with transports of delight\nHeaven's ceaseless, universal psalm:\nSalvation's glory all be paid\nTo Him who sits upon the throne\nAnd to the Lamb whose blood was shed\nThou! Thou art worthy! Thou alone!"),
      Verse(3, "\"For Thou wast slain, and in Thy blood\nThese robes were washed so spotless pure\nThou mad'st us kings and priests to God\nForever let the praise endure\"\nLet us with joy adopt the strain\nWe soon shall sing for ever there\nWorthy's the Lamb for sinners slain\nWorthy alone the crown to wear!\""),
    ],
  ),
  Song(id: 54, number: 54,
    title: "Done is the work that saves",
    author: "Horatius Bonar",
    parts: [
      Verse(1, "Done is the work that saves\nOnce and forever done\nFinished the righteousness\nThat clothes the unrighteous one\nThe love that blesses us bello\nIs flowing freely to us now"),
      Verse(2, "The sacrifice is o'er\nThe veil is rent in twain\nThe mercy-seat is red\nWith blood of the Victim slain\nWhy stand we then without, in fear?\nThe blood of Christ invites us near"),
      Verse(3, "The gate is open wide\nThe new and living way\nIs clear. and free and bright\nWith love, and peace and day\nInto the holiest now we come\nOur present and our endless home"),
      Verse(4, "Enthroned in majesty\nThe High Priest sits within\nHis precious blood, once shed\nHas mad and keeps us clean\nWith boldness let us now draw near\nThat blood has banished every fear"),
      Verse(5, "Then to the Lamb once slain\nBe glory, Praise and power\nWho died, and lives again\nWho liveth evermore\nWho loved us, cleansed us by His blood\nAnd made us kings and priests to God!"),
    ],
  ),
  Song(id: 55, number: 55,
    title: "Sweet the moments, rich in blessing",
    author: "James Allen & Walter Shirley",
    parts: [
      Verse(1, "Sweet the moments, rich in blessing\nWhich before the cross we spend,\nLife and health and peace possessing\nFrom the sinner's dying Friend."),
      Verse(2, "Here we rest, in wonder viewing\nAll our sins on Jesus laid,\nAnd full redemption flowing\nFrom the sacrifice He made."),
      Verse(3, "Here find the dawn of Heaven\nWhile upon the Cross we gaze;\nSee our trespasses forgiven.\nAnd our songs of triumph raise."),
      Verse(4, "Oh, that, near the cross abiding,\nWay to the Savior cleave.\nNaught with Him our hearts dividing\nAll for Him content to leave!"),
      Verse(5, "May we stil, the Cross discerning\nThere for peace and comfort 80: \nThere new wonders daily learning.\nAll the depths of mercy know."),
    ],
  ),
  Song(id: 56, number: 56,
    title: "For the bread and for the wine",
    author: "Horatius Bonar",
    parts: [
      Verse(1, "For the bread and for the wine\nFor the pledge that seals Him mine\nFor the words of love divine\nWe give Thee thanks, O Lord"),
      Verse(2, "Only bread and only wine\nYet to faith the solemn sign\nOf the heavenly and divine.\nWe give Thee thanks, O Lord"),
      Verse(3, "For the words that turn our eye\nTo the Cross of Calvary\nBidding us in faith draw nigh\nWe give Thee thanks, O Lord"),
      Verse(4, "For the words that fragrance Breathe\nThese plain symbols underneath\nWords that His own peace bequeath\nWe give Thee thanks, O Lord"),
      Verse(5, "For the words that tell of home\nPointing us beyond the tomb\n\"Do ye this, until I come!\"\nWe give Thee thanks, O Lord"),
      Verse(6, "Till He come we take the bread\nType of Him on whom we feed\nHim who liveth and was dead!\nWe give Thee thanks, O Lord"),
      Verse(7, "Till He come we take the cur\nAs we at His tables up\nEye and heart are lifted up!\nWe give Thee thanks, O Lord"),
      Verse(8, "For that coming herefore shown \nFor that day to man unknovn \nFor the glory and the throne \nWe give Thee thanks, O Lord"),
    ],
  ),
  Song(id: 57, number: 57,
    title: "Low in the grave He lay, Jesus my Savior",
    author: "Robert Lowry",
    parts: [
      Verse(1, "Low in the grave He lay, Jesus my Savior, \nWaiting the coming day, Jesus my Lord"),
      Chorus("Up from the grave He arose, \nWith a mighty triumph o’er His foes, \nHe arose a Victor from the dark domain, \nAnd He lives forever, with His saints to reign. \nHe arose! He arose! \nHallelujah! Christ arose!"),
      Verse(2, "Vainly they watch His bed, Jesus my Savior; \nVainly they seal the dead, Jesus my Lord!"),
      Verse(3, "Death cannot keep its prey, Jesus my Savior; \nHe tore the bars away, Jesus my Lord!"),
    ],
  ),
  Song(id: 58, number: 58,
    title: "O Blessed Saviour! Is Thy love",
    author: "Robert C. Chapman",
    parts: [
      Verse(1, "O Blessed Saviour! Is Thy love \nSo great, so full, so free? \nFain would we give our hearts, our minds \nOur lives, our all to Thee"),
      Verse(2, "We love Thee for the glorious worth \nWhich in Thyself we see \nWe love Thee for the shameful Cross \nEndured so patiently"),
      Verse(3, "No man of greater love can boast\nThan for his friend to die\nThou for Thine enemies wast slain!\nWhat love with Thine can vie?"),
      Verse(4, "Though in the very form of God\nWith heavely glory crowned\nThou didst partake of human flesh\nBeset with sorrows round"),
      Verse(5, "Thou woulds like sinful man be made\nIn everything but sin\nThat we as like Thee might become\nAs we unlike have been"),
      Verse(6, "Like Thee in faith, in meekness, love\nIn every heavenly grace\nMore of Thine image daily gain\nTill we behold Thy face"),
      Verse(7, "O Lord! we treasure in our souls\nThe memory of Thy Love\nAnd ever may Thy Name to us\nA grateful odour prove"),
    ],
  ),
  Song(id: 59, number: 59,
    title: "Majestic sweetness sits enthroned",
    author: "Samuel Stennett",
    parts: [
      Verse(1, "Majestic sweetness sits enthroned\nUpon the Savior's brow:\nHis head with radiant glories crowned,\nHis lips with grace o'erflow."),
      Verse(2, "No mortal can with Him compare\nAmong the sons of men;\nFairer is He than all the fair\nWho fill the heav' nly train."),
      Verse(3, "He saw me plunged in deep distress \nAnd flew to my relief; \nFor me He bore the shameful cross \nAnd carried all my grief."),
      Verse(4, "To Him I owe my life and breath \nAnd all the joys I have; \nHe makes me triumph over death \nAnd saves me from the grave."),
      Verse(5, "To Heav'n, the place of His abode. \nHe brings my weary feet; \nShows me the glories of my God, \nAnd makes my joys complete."),
      Verse(6, "Since from His bounty I receive \nSuch proofs of love divine, \nHad I a thousand hearts to give, \nLord, they should all be Thine."),
    ],
  ),
  Song(id: 60, number: 60,
    title: "Saviour, we remember Thee!",
    author: "Thomas Kelly",
    parts: [
      Verse(1, "Saviour, we remember Thee! \nThy deep woe and agony \nAll Thy suffering on the tree \nSaviour, we adore Thee!"),
      Verse(2, "Calvary! O Calvary! \nMercy's vast unfathomed sea \nLove, eternal love to me \nSaviour, we adore Thee!"),
      Verse(3, "Darkness hung around Thy head \nWhen for sin Thy blood was shed \nVictim in the singer's stead \nSaviour, we adore Thee!"),
      Verse(4, "Jesus, Lord. Thou now art risen!\nThou hast all our sins forgiven!\nHaste we to our home in heaven\nSaviour. we adore Thee!"),
      Verse(5, "Soon, with joyful, glad surprise\nWe shall hear Thy word- Arise!\nMounting upward to the skies\nGlory, glory, glory"),
      Verse(6, "Saviour, we Thy love adore\nWe will praise Thee more and more\nSpread Thy Name from shore to shore\nSaviour, we adore Thee!"),
    ],
  ),
  Song(id: 61, number: 61,
    title: "O God of matchless grace",
    author: "Edward Denny",
    parts: [
      Verse(1, "O God of matchless grace\nWe sing unto Thy Name!\nWe stand accepted in the place\nThat none but Christ could claim\nOur willing hearts have heard Thy voice\nAnd in Thy mercy we rejoice"),
      Verse(2, "Tis meet that Thy delight\nShould centre in Thy Son\nThat Thou shouldst place us in Thy sight\nIn Him, Thy Holy One\nThy perfect love has cast out fear\nThy favour shines upon us here"),
      Verse(3, "Eternal is our rest\nO Christ of God, in Thee!\nNow of Thy peace, Thy joy possessed\nWe wait Thy face to see\nNow to the Father's heart received\nWe know in whom we have believed"),
      Verse(4, "A sacrifice to God\nIn life or death are we\nThen keep us ever, blessed Lord\nThus set apart to Thee\nBought with a price, we're not our own\nWe died, we live to God alone!"),
    ],
  ),
  Song(id: 62, number: 62,
    title: "O Lord, how much Thy name unfolds",
    author: "Mary Bowly Peters",
    parts: [
      Verse(1, "O Lord, how much Thy name unfolds\nTo every opened ear\nThe pardoned sinner's memory holds\nNone other half so dear"),
      Verse(2, "Jesus! it speaks a life of love\nAnd sorrows meekly borne\nIt tells of sympathy above\nWhatever griefs we mourn"),
      Verse(3, "It tells us of Thy walk\nIn fellowship with God\nAnd to our ears no tale so sweet\nAs Thine atoning blood"),
      Verse(4, "This name encircles every grace\nThat God, as man, could show\nThere only can the spirit trace\nA perfect life below"),
      Verse(5, "The mention of Thy Name shall bow\nOur hearts to worship Thee\nThe chiefest of the thousand Thou\nThe chief of sinners we"),
    ],
  ),
  Song(id: 63, number: 63,
    title: "O Lord, Thy love's unbounded",
    author: "J. N. Darby",
    parts: [
      Verse(1, "O Lord, Thy love's unbounded, \nSo sweet, so full, so free; \nMy soul is all transported \nWhene'er I think on Thee. \nYet, Lord, alas, what weakness \nWithin myself I find: \nNo infant's changing pleasure \nIs like my wandering mind."),
      Verse(2, "And yet Thy love's unchanging, \nAnd doth recall my heart\nTo joy in all its brightness-\nThe peace its beams impart.\nYet sure, if in Thy presence\nMy soul still constant were,\nMine eye would, more familiar,\nIts brighter glories bear."),
      Verse(3, "And thus Thy deep perfections\nMuch better should I know,\nAnd with adoring fervor\nIn this Thy nature grow.\nStill sweet 'tis to discover,\nIf clouds have dimmed my sight,\nWhen passed, eternal Lover, \nTowards me, as e'er, Thou'rt bright"),
      Verse(4, "O keep my soul, then, Jesus,\nAbiding still with Thee;\nAnd if I wander, teach me\nSoon back to Thee to flee,\nThat all Thy gracious favor\nMay to my soul be known;\nAnd, versed in this Thy goodness,\nMy hopes Thyself shalt crown."),
    ],
  ),
  Song(id: 64, number: 64,
    title: "Come, let us sing the matchless worth",
    author: "Samuel Medley",
    parts: [
      Verse(1, "Come, let us sing the matchless worth\nAnd sweetly sound the glories forth\nWhich in the Saviour shine:\nTo God and Christ our praises bring\nThe song with which high heaven will ring,\nPraises for grace divine."),
      Verse(2, "How rich the precious blood He spilt,\nOur ransom from the dreadful guilt\nOf sin against our God;\nHow perfect is that righteousness.\nIn which unspotted beauteous dress\nHis saints have ever stood!"),
      Verse(3, "How rich the character He bears,\nAnd all the form of love He wears,\nExalted on the throne;\nIn songs of sweet untiring praise,\nWe e'er would sing His perfect ways,\nAnd make His glories known."),
      Verse(4, "And soon the happy day shall come,\nWhen we shall reach our destined home,\nAnd see Him face to face;\nThen with our Saviour, Lord and Friend,\nThe one unbroken day we'l spend\nIn singing still His grace"),
    ],
  ),
  Song(id: 65, number: 65,
    title: "Sweet is the work, my God, my King",
    author: "Isaac Watts",
    parts: [
      Verse(1, "Sweet is the work, my God, my King,\nTo praise Thy Name, give thanks and sing\nTo show Thy love by morning light\nAnd talk of all Thy truth at night."),
      Verse(2, "Sweet is the day of sacred rest,\nNo mortal cares shall seize my breast.\nO may my heart in tune be found,\nLike David's harp of solemn sound!"),
      Verse(3, "My heart shall triumph in my Lord\nAnd bless His works and bless His Word.\nThy works of grace, how bright they shine!\nHow deep Thy counsels, how divine!"),
      Verse(4, "And I shall share a glorious part,\nWhen grace has well refined my heart; \nAnd fresh supplies of joy are shed,\nLike holy oil, to cheer my head."),
      Verse(5, "Then shall I see. and hear, and know\nAll I desired and wished below;\nAnd every power find sweet employ\nIn that eternal world of joy."),
    ],
  ),
  Song(id: 66, number: 66,
    title: "Hark! ten thousand voices crying",
    author: "Thomas Kelly",
    parts: [
      Verse(1, "Hark! ten thousand voices crying\n\"Lamb of God\" with one accord;\nThousand thousand saints replying,\nWake at once the echoing chord."),
      Verse(2, "\"Praise the Lamb\", the chorus waking,\nAll in heaven together throng;\nLoud and far each tongue partaking\nRolls around the endless song."),
      Verse(3, "Grateful incense this, ascending\nEver to the Father's throne;\nEvery knee to Jesus bending,\nAll the mind in heaven is one."),
      Verse(4, "All the Father's counsels claiming\nEqual honors to the Son:\nAll the Son's effulgence beaming\nMakes the Father's glory known."),
      Verse(5, "By the Spirit all-pervading,\nHosts unnumbered round the Lamb,\nCrowned with light and joy unfading,\nHail Him as the great \"I AM\"."),
      Verse(6, "Joyful now the new creation\nRests in undisturbed repose,\nBlest in Jesus full salvation,\nSorrow now nor thralldom knows."),
    ],
  ),
  Song(id: 67, number: 67,
    title: "God moves in a mysterious way",
    author: "William Cowper",
    parts: [
      Verse(1, "God moves in a mysterious way\nHis wonders to perform;\nHe plants His footsteps in the sea\nAnd rides upon the storm."),
      Verse(2, "Deep in unfathomable mines\nOf never-failing skill\nHe treasures up His bright designs\nAnd works His sovereign will."),
      Verse(3, "Ye fearful saints, fresh courage take:\nThe clouds ye so much dread\nAre big with mercy and shall break\nIn blessings on your head."),
      Verse(4, "Judge not the Lord by feeble sense,\nBut trust Him for His grace;\nBehind a frowning providence\nHe hides a smiling face."),
      Verse(5, "His purposes will ripen fast,\nUnfolding every hour;\nThe bud may have a bitter taste.\nBut sweet will be the flower."),
      Verse(6, "Blind unbelief is sure to err\nAnd scan His work in vain;\nGod is His own interpreter,\nAnd He will make it plain."),
    ],
  ),
  Song(id: 68, number: 68,
    title: "Sweet feast of love divine",
    author: "Edward Denny",
    parts: [
      Verse(1, "Sweet feast of love divine.\nTis grace that makes us free\nTo feed upon this bread and wine,\nIn memory, Lord, of Thee."),
      Verse(2, "Here every welcome guest\nWaits, Lord, from Thee to learn\nThe secrets of Thy Father's breast,\nAnd all Thy grace discern."),
      Verse(3, "Here conscience ends its strife,\nAnd faith delights to prove\nThe sweetness of the bread of life,\nThe fullness of Thy love."),
      Verse(4, "Thy blood that flowed for sin,\nIn symbol here we see,\nAnd feel the blessed pledge within,\nThat we are loved o Thee."),
      Verse(5, "But if this glimpse of love\nIs so divinely sweet,\nWhat will it be, O Lord, above, \nThy gladdening smile to meet"),
      Verse(6, "To see Thee face to face, \nThy perfect likeness wear, \nAnd all Thy ways of wondrous grace \nThrough endless years declare!"),
    ],
  ),
  Song(id: 69, number: 69,
    title: "Behold, what love. what boundless love",
    author: "Robert Sandeman",
    parts: [
      Verse(1, "Behold, what love. what boundless love, \nThe Father hath bestowed \nOn sinners lost, that we should be \nNow called \"the sons of God!\""),
      Chorus("Behold, what manner of love! \nWhat manner of love the Father hath bestowed upon us,\nThat we, that we should be called, \nShould be called the sons of God!"),
      Verse(2, "No longer far from Him but now \nBy \"precious blood\" made nigh, \nAccepted in the \"Well beloved,'' \nNear to God's heart we lie."),
      Verse(3, "What we in glory soon shall be, \nIt doth not yet appear; \nBut when our precious Lord we see, \nWe shall His image bear."),
      Verse(4, "With such a blessed hope in view, \nWe would more holy be, \nMore like our risen, glorious Lord, \nWhose face we soon shall see."),
    ],
  ),
  Song(id: 70, number: 70,
    title: "O head once full of bruises",
    author: "Unknown",
    parts: [
      Verse(1, "O head once full of bruises,\nSo full of pain and scorn,\nMid other sore abuses,\nMocked with a crown of thorn:\nO Head! e’en now surrounded\nWith brightest majesty,\nIn death once bowed and wounded\nOn the accursed tree."),
      Verse(2, "Thou Countenance transcendent!\nThou life-creating Sun!\nTo worlds on Thee dependent\nYet bruised and spit upon:\nO Lord! what Thee tormented\nWas our sin’s heavy load,\nWe had the debt augmented\nWhich Thou didst pay in blood."),
      Verse(3, "We give Thee thanks unfeigned,\nO Saviour! Friend in need,\nFor what Thy soul sustained\nWhen Thou for us didst bleed;\nGrant us to lean unshaken\nUpon Thy faithfulness;\nUntil to glory taken,\nWe see Thee face to face."),
    ],
  ),
  Song(id: 71, number: 71,
    title: "Oh, my Savior crucified",
    author: "Unknown",
    parts: [
      Verse(1, "Oh, my Savior crucified\nNear Thy cross would I abide,\nGazing with adoring eye\nOn Thy dying agony."),
      Verse(2, "Jesus bruised and put to shame,\nTells the glories of God's name:\nHoly judgment there I found,\nGrace did there o'er sin abound,"),
      Verse(3, "God is love I surely know,\nIn the Savior's depth of woe,\nIn the Sinless, in God's sight,\nSin is justly brought to light."),
      Verse(4, "In His spotless soul's distress.\nI have learnt my guiltiness;\nOh how vilo my low estate,\nSince my ransom was so great!"),
      Verse(5, "Rent the veil that closed the way\nTo my home of heavenly day,\nIn the flesh of Christ the Lord,\nEver be His name adored!"),
      Verse(6, "Yet in sight of Calvary,\nContrite should my spirit be,\nContrite spirit holiness there find\nFashioned like my Savior's mind."),
    ],
  ),
  Song(id: 72, number: 72,
    title: "We are gathering together unto Him",
    author: "Unknown",
    parts: [
      Verse(1, "We are gathering together unto Him (2)\nUnto Him shall the gathering of the people be\nWe are gathering together unto Him"),
      Verse(2, "We are offering together unto Him (2)\nUnto Him shall the offering of the people be\nWe are gathering together unto Him"),
      Verse(3, "We are singing together unto Him (2)\nUnto Him shall the singing of the people be\nWe are singing together unto Him"),
      Verse(4, "We are praying together unto Him (2)\nUnto Him shall the praying of the people be\nWe are gathering together unto Him"),
    ],
  ),
  Song(id: 73, number: 73,
    title: "O Lord, we adore Thee",
    author: "Unknown",
    parts: [
      Verse(1, "O Lord, we adore Thee,\nFor Thou art the slain One\nThat livest forever,\nEnthroned in heaven;\nO Lord, we adore Thee,\nFor Thou hast redeemed us;\nOur title to glory\nWe read in Thy blood."),
      Verse(2, "O God, we acknowledge\nThy greatness, Thy glory,\nFor of Thee are all things\nOn earth and in heaven;\nHow rich is Thy mercy,\nHow great Thy salvation!\nWe bless Thee, we praise Thee,\nAmen, and Amen."),
    ],
  ),
  Song(id: 74, number: 74,
    title: "Blessed be the name of the Lord",
    author: "Unknown",
    parts: [
      Verse(1, "Blessed be the name of the Lord, (2)\nBlessed be the name of the Lord Most High\n\nThe name of the Lord is\nA strong tower\nThe righteous run into it\nAnd they are saved"),
      Verse(2, "Holy is the name of the Lord (2)\nHoly is the name of the Lord on high"),
      Verse(3, "Glory to the name of the Lord (2)\nGlory to the name of the Lord on high"),
    ],
  ),
  Song(id: 75, number: 75,
    title: "I will call upon the Lord",
    author: "Unknown",
    parts: [
      Verse(1, "I will call upon the Lord\nWho is worthy to be praised\nSo shall I be saved\nFrom my enemies\nI will call upon the lord\n\nThe Lord liveth\nAnd blessed be the rock\nAnd let the God of my salvation\nBe exalted\nHosanna\nBlessed be the rock\nBlessed be the rock of my salvation"),
    ],
  ),
  Song(id: 76, number: 76,
    title: "Therefore the redeemed of the Lord shall return",
    author: "Unknown",
    parts: [
      Verse(1, "Therefore the redeemed of the Lord shall return\nAnd come with singing unto Zion\nAnd everlasting joy shall be upon their head\nHead shall obtain gladness and joy\nAnd sorrow and morning shall flee away\nTherefore the redeemed of the Lord shall return\nAnd come with singing unto Zion\nAnd everlasting joy shall be upon their head"),
    ],
  ),
  Song(id: 77, number: 77,
    title: "In my life, Lord, be glorified, be glorified",
    author: "Unknown",
    parts: [
      Verse(1, "In my life, Lord, be glorified, be glorified\nIn my life, Lord, be glorified today"),
      Verse(2, "In your Church, Lord, be glorified, be glorified\nIn your Church, Lord, be glorified today"),
    ],
  ),
  Song(id: 78, number: 78,
    title: "Bless the Lord, O my soul",
    author: "Unknown",
    parts: [
      Verse(1, "Bless the Lord, O my soul\nAnd all that is within me\nBless His holy name. \nKing of kings (forever and ever), \nLord of lords (forever and ever), \nKing of kings (forever and ever), \nKing of kings and Lord of l"),
    ],
  ),
  Song(id: 79, number: 79,
    title: "Our God is an awesome God",
    author: "Unknown",
    parts: [
      Verse(1, "Our God is an awesome God, \nHe reigns from heaven above \nWith wisdom, power and love, \nOur God is an awesome God"),
    ],
  ),
  Song(id: 80, number: 80,
    title: "Open our eyes, Lord",
    author: "Unknown",
    parts: [
      Verse(1, "Open our eyes, Lord\nWe want to see Jesus,\nTo reach out and touch Him,\nAnd say that we love Him.\nOpen our ears, Lord\nAnd help us to listen.\nOpen our eyes, Lord\nWe want to see Jesus"),
    ],
  ),
  Song(id: 81, number: 81,
    title: "Turn your eyes upon Jesus",
    author: "Helen Howarth Lemmel",
