    ],
  ),
  Song(id: 122, number: 122,
    title: "Hallehujah hallelujah hallelujah to the Lamb",
    author: "Don Moen",
    parts: [
      Verse(1, "Hallehujah hallelujah hallelujah \nTo the Lamb Hallelujah hallelujah\nBy the blood of Christ we stand\nEvery tongue, every tribe\nEvery people, every land\nGiving glory, giving honor\nGiving praise unto the Lamb of God...."),
      Verse(2, "Lord I stand in the midst of a multitude\nOf those from every tribe and tongue\nWe are Your people redeemed by Your blood\nRescued from death by Your love\nThere are no words good enough to thank You"),
      Verse(3, "There are no words to express my praise\nBut I will lift up my voice\nAnd sing from my heart\nWith all of my strength"),
    ],
  ),
  Song(id: 123, number: 123,
