    ],
  ),
  Song(id: 127, number: 127,
    title: "Fairest Lord Jesus, ruler of all nature",
    author: "Unknown",
    parts: [
      Verse(1, "Fairest Lord Jesus, \nRuler of all nature, \nO Thou of God and man the Son, \nThee will I cherish, \nThee will I honor,\nThou, my soul's glory, joy and crown."),
      Verse(2, "Fair are the meadows, \nFairer still the woodlands, \nRobed in the blooming garb of spring: \nJesus is fairer, \nJesus is purer \nWho makes the woeful heart to sing."),
      Verse(3, "Fair is the sunshine, fairer still the moonlight \nAnd all the twinkling starry host; \nJesus shines brighter, Jesus shines purer \nThan all the angels heaven can boast."),
      Verse(4, "All fairest beauty, heavenly and earthly, \nWondrously, Jesus, is found in Thee; \nNone can be nearer. fairer or dearer. \nThan Thou, my Savior, art to me."),
      Verse(5, "Beautiful Savior! Lord of all the nations! \nSon of God and Son of Man! \nGlory and honor, praise, adoration, \nNow and forever more be Thine."),
    ],
  ),
  Song(id: 128, number: 128,
    title: "The marketplace is empty, no more traffic in the streets",
    author: "Unknown",
    parts: [
      Verse(1, "The marketplace is empty,\nNo more traffic in the streets.\nAll builders’ tools are silent,\nNo more time to harvest wheat.\nBusy housewives cease their labors,\nIn the Courtroom no debate.\nWork on earth is all suspended\nAs the King comes through the gate."),
      Chorus("Oh, the King is coming,\nThe King is coming,\nI just heard the trumpet sounding\nAnd now his face I see.\nOh, the King is coming,\nThe King is coming\nPRAISE GOD,\nHe's coming for me!"),
      Verse(2, "All the railroad road cars are empty,\nAs they rattle down the tracks.\nIn the newsroom no one watches.\nAs machines type pointless facts.\nAll the planes veer off their courses.\nNo one sits at the controls,\nFor the King of all the ages\nComes to claim eternal souls."),
      Verse(3, "Happy faces line the hallways,\nThose whose lives have been redeemed.\nBroken homes that He has mended,\nThose from prison He has freed.\nLittle children and the aged,\nHand in hand stand all aglow,\nWho were crippled, broken, ruined,\nClad in garments white as snow."),
      Verse(4, "I can hear the chariots rumble.\nI can see the marching throng.\nThe flury of God's trumpet\nSpell the end of sin and wrong.\nRegal robes are now enfolding,\nHeaven's grandstand all in place.\nHeaven's choir now assembled\nStart to sing Amazing Grace."),
    ],
  ),
  Song(id: 129, number: 129,
    title: "I heard an old, old story",
    author: "Unknown",
    parts: [
      Verse(1, "I heard an old, old story,\nHow a Savior came from glory,\nHow He gave His life on Calvary\nTo save a wretch like me;\nI heard about His groaning,\nOf His precious blood's atoning,\nThen I repented of my sins\nAnd won the victory."),
      Chorus("O victory in Jesus,\nMy Savior, forever.\nHe sought me and bought me\nWith His redeeming blood;\nHe loved me and I knew Him\nAnd all my love is due Him,\nHe plunged me to victory,\nBeneath the cleansing flood."),
      Verse(2, "I heard about His healing.\nOf His cleansing pow'r revealing.\nHow He made the lame to walk again\nAnd caused the blind to see:\nAnd then I cried, \"Dear Jesus,\nCome and heal my broken spirit,\"\nAnd somehow Jesus came and bro't\nTo me the victory."),
      Verse(3, "I heard about a mansion\nHe has built for me in glory.\nAnd I heard about the streets of gold\nBeyond the crystal sea;\nAbout the angels singing,\nAnd the old redemption story,\nAnd some sweet day I Il sing up there\nThe song of victory."),
    ],
  ),
  Song(id: 130, number: 130,
    title: "You are my hiding place",
    author: "Unknown",
    parts: [
      Verse(1, "You are my hiding place,\nYou always fill my heart with songs of deliverance.\nWhenever I am afraid, I will trust in You.\nI will trust in You. (3)\nLet the weak say I am strong in the strength of my Lord.\nI will trust in You!"),
    ],
  ),
  Song(id: 131, number: 131,
