  Song(id: 144, number: 144,
    title: "Above All",
    author: "Paul Baloche & Lenny LeBlanc",
    parts: [
      Verse(1, "Above all powers, above all kings \nAbove all nature and all created things \nAbove all wisdom and all the ways of man \nYou were here before the world began \nAbove all kingdoms, above all thrones \nAbove all wonders the world has ever known \nAbove wealth and treasures of the earth \nThere's no way to measure what You're worth"),
      Chorus("Crucified, laid behind the stone \nYou lived to die, rejected and alone \nLike a rose, trampled on the ground \nYou took the fall and thought of me \nAbove all"),
    ],
  ),
  Song(id: 145, number: 145,
    title: "Worthy, You are worthy King of Kings Lord of Lords",
    author: "Unknown",
    parts: [
