  Song(id: 151, number: 151,
    title: "Lord, I come to you, let my heart be changed, renewed",
    author: "Unknown",
    parts: [
      Verse(1, "Lord, I come to you, let my heart be changed, renewed. Flowing from the grace, that I found in you. \nAnd Lord, I've come to know the weaknesses I see in me \nWill be stripped away by the power of Your love."),
      Chorus("Hold me close, let your love surround me, \nBring me near, draw me to your side; \nand as I wait, I'll rise up like the eagle, \nand I will soar with you, your spirit leads me on, \nin the power of your love."),
      Verse(2, "Lord, unveil my eyes, let me see you face to face, \nThe knowledge of your love, as you live in me. \nLord, renew my mind as your will unfolds in my life, \nIn living every day in the power of your love."),
    ],
  ),
  Song(id: 152, number: 152,
