  Song(id: 153, number: 153,
    title: "Draw Me Close",
    author: "Kelly Carpenter",
    parts: [
      Verse(1, "Draw me close to you\nNever let me go\nI lay it all down again\nTo hear you say that I' m your friend\nYou are my desire\nNo one else will do\nCause nothing else can take your place\nTo feel the warmth of your embrace\nHelp me find the way \nBring me back to you"),
      Chorus("You're all I want \nYou're all I've ever needed \nYou're all I want \nHelp me know you are near"),
    ],
  ),
  Song(id: 154, number: 154,
    title: "Thank You Lord",
    author: "Don Moen",
    parts: [
      Verse(1, "I come before you today\nAnd there's just one thing that I want to say\nThank you Lord thank you Lord\nFor all you've given to me\nFor all the blessings that I cannot see\nThank you Lord thank you Lord"),
      Verse(2, "With a grateful heart\nWith a song of praise\n\nWith an outstretch arm\nI will bless your name thank you Lord \nI just wanna thank you Lord \nI just wanna thank you Lord \nThank you Lord"),
      Verse(3, "For all you've done in my life \nYou took my darkness and gave me your light\nThank you Lord thank you Lord \nYou took my sin and my shame \nYou took my sickness and healed all my pain \nThank you Lord thank you Lord"),
    ],
  ),
  Song(id: 155, number: 155,
    title: "I just want to be where You are",
    author: "Don Moen",
    parts: [
      Verse(1, "I just want to be where You are, \nDwelling daily in Your presence \nI don't want to worship from afar. \nDraw me near to where You are\n\nI just want to be where You are, \nIn Your dwelling place forever \nTake me to the place where You are, \nI just want to be with You"),
      Verse(2, "I want to be where You are, \nDwelling in Your presence \nFeasting at Your table \nSurrounded by Your glory"),
      Verse(3, "In Your presence \nThat's where I always want to be \nI just want to be. \nI just want to be with You"),
      Verse(4, "I just want to be where You are. \nTo enter boldly in Your presence \nI don't want to worship from afar.\nDraw me near to where You are \n\nOh, my God, \nYou are my strength and my song\nAnd when I’m in Your presence\nThough I'm weak You're always strong\n\nI just want to be \nI just want to be with You"),
    ],
  ),
  Song(id: 156, number: 156,
    title: "When I look into your holiness",
