  Song(id: 168, number: 168,
    title: "Great is the Lord and greatly to be praised",
    author: "Traditional (Psalm 48)",
    parts: [
      Verse(1, "Great is the Lord and greatly to be praised\nIn the city of our God\nIn the mountain of His holiness\nBeautiful for situation the joy of the whole earth\nIs Mount Zion on the sides of the north\nThe city of the great King"),
    ],
  ),
  Song(id: 169, number: 169,
    title: "O Lord Our Lord, how excellent your name is",
    author: "Debbye Graafsma",
    parts: [
      Verse(1, "O Lord Our Lord, how excellent your name is\nHow excellent your name in all the earth\nYour glory fills the heavens\nBeyond the farthest star\nHow excellent your name in all the earth"),
      Verse(2, "When I think about the heavens\nThe moon and all the stars\nI wonder what you ever saw in me\nBut you took me and you loved me\nAnd you have given me a crown\nAnd I'l praise your name eternally"),
    ],
  ),
  Song(id: 170, number: 170,
    title: "All the way my Savior leads me",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "All the way my Savior leads me\nWhat have I to ask beside?\nCan I doubt His tender mercy\nWho through life has been my Guide?\nHeav'nly peace divinest comfort\nHere by faith in Him to dwell!\nFor I know, whate'er befall me\nJesus doeth all things well"),
      Verse(2, "All the way my Savior leads me\nCheers each winding path I tread\nGives me grace for every trial\nFeeds me with the living Bread\nThough my weary steps may falter\nAnd my soul athirst may be\nGushing from the Rock before me\nLo! A spring of joy I see"),
      Verse(3, "All the way my Savior leads me\nOh, the fullness of His love!\nPerfect rest to me is promised\nIn my Father's house above\nWhen my spirit, clothed immortal\nWings its flight to realms of day\nThis my song through endless ages\nJesus led me all the way"),
    ],
  ),
  Song(id: 171, number: 171,
    title: "When upon life's billows you are tempest tossed",
    author: "Johnson Oatman Jr.",
    parts: [
      Verse(1, "When upon life's billows you are tempest tossed\nWhen you are discouraged, thinking all is lost\nCount your many blessings, name them one by one\nAnd it will surprise you what the Lord hath done\n\nCount your blessings, name them one by one\nCount your blessings, see what God hath done!\nCount your blessings, name them one by one\nAnd it will surprise you what the Lord hath done"),
      Verse(2, "Are you ever burdened with a load of care?\nDoes the cross seem heavy you are called to bear?\nCount your many blessings, every doubt will fly\nAnd you will keep singing as the days go by"),
      Verse(3, "When you look at others with their lands and gold\nThink that Christ has promised you His wealth untold\nCount your many blessings, Wealth can never buy\nYour reward in heaven, nor your home on high"),
      Verse(4, "So, amid the conflict whether great or small\nDo not be disheartened, God is over all\nCount your many blessings, angels will attend\nHelp and comfort give you to your journey's end"),
    ],
  ),
  Song(id: 172, number: 172,
    title: "All to Jesus, I surrender",
    author: "Judson W. Van DeVenter",
    parts: [
      Verse(1, "All to Jesus, I surrender\nAll to Him I freely give\nI will ever love and trust Him\nIn His presence daily live\n\nI surrender all, I surrender all\nAll to Thee, my blessed Savior\nI surrender all"),
      Verse(2, "All to Jesus I surrender\nHumbly at His feet I bow\nWorldly pleasures all forsaken\nTake me, Jesus, take me now"),
      Verse(3, "All to Jesus, I surrender\nMake me, Savior, wholly Thine\nLet me feel the Holy Spirit\nTruly know that Thou art mine"),
      Verse(4, "All to Jesus, I surrender\nLord, I give myself to Thee\nFill me with Thy love and power\nLet Thy blessing fall on me"),
      Verse(5, "All to Jesus I surrender\nNow I feel the sacred flame\nO the joy of full salvation!\nGlory, glory, to His Name!"),
    ],
  ),
  Song(id: 173, number: 173,
    title: "I need Thee every hour, most gracious Lord",
    author: "Annie S. Hawks",
    parts: [
      Verse(1, "I need Thee every hour, most gracious Lord\nNo tender voice like Thine can peace afford\n\nI need Thee, O I need Thee\nEvery hour I need Thee\nO bless me now, my Savior\nI come to Thee"),
      Verse(2, "I need Thee every hour, stay Thou nearby\nTemptations lose their power when Thou art nigh"),
      Verse(3, "I need Thee every hour, in joy or pain\nCome quickly and abide, or life is in vain"),
      Verse(4, "I need Thee every hour; teach me Thy will\nAnd Thy rich promises in me fulfil"),
      Verse(5, "I need Thee every hour, most Holy One\nO make me Thine indeed, Thou blessed Son"),
    ],
  ),
  Song(id: 174, number: 174,
    title: "Onward, Christian soldiers, marching as to war",
    author: "Sabine Baring-Gould",
    parts: [
      Verse(1, "Onward, Christian soldiers, marching as to war\nWith the cross of Jesus going on before\nChrist, the royal Master, leads against the foe\nForward into battle see His banners go!"),
      Chorus("Onward, Christian soldiers, marching as to war\nWith the cross of Jesus going on before"),
      Verse(2, "At the sign of triumph Satan's host doth flee\nOn then, Christian soldiers, on to victory!\nHell's foundations quiver at the shout of praise\nBrothers lift your voices, loud your anthems raise"),
      Verse(3, "Like a mighty army moves the church of God\nBrothers, we are treading where the saints have trod\nWe are not divided, all one body we\nOne in hope and doctrine, one in charity"),
      Verse(4, "Crowns and thrones may perish, kingdoms rise and wane\nBut the church of Jesus constant will remain\nGates of hell can never gainst that church prevail\nWe have Christ's own promise, and that cannot fail"),
      Verse(5, "Onward then, ye people, join our happy throng\nBlend with ours your voices in the triumph song\nGlory, laud and honor unto Christ the King\nThis through countless ages men and angels sing"),
    ],
  ),
  Song(id: 175, number: 175,
    title: "Sweet hour of prayer! sweet hour of prayer!",
    author: "William W. Walford",
    parts: [
      Verse(1, "Sweet hour of prayer! sweet hour of prayer!\nThat calls me from a world of care\nAnd bids me at my Father's throne\nMake all my wants and wishes known\nIn seasons of distress and grief\nMy soul has often found relief\nAnd oft escaped the tempter's snare\nBy thy return, sweet hour of prayer!"),
      Verse(2, "Sweet hour of prayer! sweet hour of prayer!\nThe joys I feel, the bliss I share\nOf those whose anxious spirits burn\nWith strong desires for thy return!\nWith such I hasten to the place\nWhere God my Savior shows His face\nAnd gladly take my station there\nAnd wait for thee, sweet hour of prayer!"),
      Verse(3, "Sweet hour of prayer! sweet hour of prayer!\nThy wings shall my petition bear\nTo Him whose truth and faithfulness\nEngage the waiting soul to bless\nAnd since He bids me seek His face\nBelieve His Word and trust His grace\nI'll cast on Him my every care\nAnd wait for thee, sweet hour of prayer!"),
      Verse(4, "Sweet hour of prayer! sweet hour of prayer\nMay I thy consolation share\nTill, from Mount Pisgah's lofty height\nI view my home and take my flight\nThis robe of flesh I'l drop and rise\nTo seize the everlasting prize\nAnd shout, while passing through the air\nFarewell, farewell, sweet hour of prayer!"),
    ],
  ),
  Song(id: 176, number: 176,
    title: "Search me, O God, and I know my heart today",
    author: "J. Edwin Orr",
    parts: [
      Verse(1, "Search me, O God, and I know my heart today\nTry me, O Savior, know my thoughts, I pray\nSee if there be some wicked way in me\nCleanse me from every sin and set me free"),
      Verse(2, "I praise Thee, Lord, for cleansing me from sin\nFulfil Thy Word, and make me pure within\nFill me with fire where once I burned with shame\nGrant my desire to magnify Thy Name"),
      Verse(3, "Lord, take my life, and make it wholly Thine\nFill my poor heart with Thy great love divine\nTake all my will, my passion, self and pride\nI now surrender, Lord in me abide"),
      Verse(4, "O Holy Ghost, revival comes from Thee\nSend a revival, start the work in me\nThy Word declares thou wilt supply our need\nFor blessings now, O Lord, I humbly plead"),
    ],
  ),
  Song(id: 177, number: 177,
    title: "O Jesus, I have promised to serve Thee to the end",
    author: "John Ernest Bode",
    parts: [
      Verse(1, "O Jesus, I have promised to serve Thee to the end\nBe Thou forever near me, my Master and my Friend\nI shall not fear the battle if Thou art by my side\nNor wander from the pathway if Thou wilt be my Guide"),
      Verse(2, "O let me feel Thee near me! The world is ever near\nI see the sights that dazzle, the tempting sounds I hear\nMy foes are ever near me, around me and within\nBut Jesus, draw Thou nearer, and shield my soul from sin"),
      Verse(3, "O let me hear Thee speaking in accents clear and still\nO speak to reassure me, to hasten or control\nAbove the storms of passion, the murmurs of self will\nO speak, and make me listen, Thou Guardian of my soul"),
      Verse(4, "O Jesus, Thou hast promised to all who follow Thee\nThat where Thou art in glory there shall Thy servant be\nAnd Jesus, I have promised to serve Thee to the end\nO give me grace to follow, my Master and my Friend"),
      Verse(5, "O let me see Thy footprints, and in them plant mine own\nMy hope to follow duly is in Thy strength alone\nO guide me, call me, draw me, uphold me to the end\nAnd then in Heaven receive me, my Savior and my Friend"),
    ],
  ),
  Song(id: 178, number: 178,
    title: "Amazing grace! how sweet the sound",
    author: "John Newton",
    parts: [
      Verse(1, "Amazing grace! how sweet the sound\nThat saved a wretch like me!\nI once was lost but now am found\nWas blind but now I see"),
      Verse(2, "'Twas grace that taught my heart to fear\nAnd grace my fears relieved\nHow precious did that grace appear\nThe hour I first believed"),
      Verse(3, "The Lord has promised good to me\nHis word my hope secures\nHe will my shield and portion be\nAs long as life endures"),
      Verse(4, "Through many dangers, toils, and snares\nI have already come\n'Tis grace hath brought me safe thus far\nAnd grace will lead me home"),
      Verse(5, "Yea, when this flesh and heart shall fail\nAnd mortal life shall cease\nI shall possess, within the veil\nA life of joy and peace"),
      Verse(6, "The world shall soon dissolve like snow\nThe sun refuse to shine\nBut God, who called me here below\nShall be forever mine"),
      Verse(7, "When we've been there ten thousand years\nBright shining as the sun\nWe've no less days to sing God's praise\nThan when we'd first begun"),
    ],
  ),
  Song(id: 179, number: 179,
    title: "The love that Jesus had for me",
    author: "Traditional",
    parts: [
      Verse(1, "The love that Jesus had for me\nTo suffer on the cruel tree\nThat I a ransomed soul might be\nIs more than tongue can tell!"),
      Chorus("His love is more than tongue can tell!\nHis love is more than tongue can tell!\nThe love that Jesus had for me\nIs more than tongue can tell!"),
      Verse(2, "The bitter sorrow that He bore\nAnd O that crown of thorns He wore\nThat I might live for evermore\nIs more than tongue can tell"),
      Verse(3, "The peace I have in Him, my Lord\nWho pleads before the throne of God\nThe merit of His precious blood\nIs more than tongue can tell!"),
      Verse(4, "The joy that comes when He is near\nThe rest He gives so free from fear\nThe hope in Him, so bright and clear\nIs more than tongue can tell!"),
    ],
  ),
  Song(id: 180, number: 180,
    title: "Our God, our help in ages past",
    author: "Isaac Watts",
    parts: [
      Verse(1, "Our God, our help in ages past\nOur hope for years to come\nOur shelter from the stormy blast\nAnd our eternal home"),
      Verse(2, "Under the shadow of Thy throne\nThy saints have dwelt secure\nSufficient is Thine arm alone\nAnd our defense is sure"),
      Verse(3, "Before the hills in order stood\nOr earth received her frame\nFrom everlasting Thou art God\nTo endless years the same"),
      Verse(4, "A thousand ages in Thy sight\nAre like an evening gone\nShort as the watch that ends the night\nBefore the rising sun"),
      Verse(5, "Time, like an ever rolling stream\nBears all its sons away\nThey fly, forgotten, as a dream\nDies at the opening day"),
      Verse(6, "Our God, our help in ages past\nOur hope for years to come\nBe Thou our guard while troubles last\nAnd our eternal home"),
    ],
  ),
  Song(id: 181, number: 181,
    title: "Great is Thy faithfulness, O God my Father",
    author: "Thomas O. Chisholm",
    parts: [
      Verse(1, "Great is Thy faithfulness, O God my Father\nThere is no shadow of turning with Thee\nThou changest not, Thy compassions, they fail not\nAs Thou hast been, Thou forever will be"),
      Chorus("Great is Thy faithfulness!\nGreat is Thy faithfulness!\nMorning by morning new mercies I see\nAll I have needed Thy hand hath provided\nGreat is Thy faithfulness, Lord, unto me!"),
      Verse(2, "Summer and winter springtime and harvest\nSun, moon and stars in their courses above\nJoin with all nature in manifold witness\nTo Thy great faithfulness, mercy and love"),
      Verse(3, "Pardon for sin and a peace that endureth\nThine own dear presence to cheer and to guide\nStrength for today and bright hope for tomorrow\nBlessings all mine, with ten thousand beside!"),
    ],
  ),
  Song(id: 182, number: 182,
    title: "O let the Son of God enfold you",
    author: "John Wimber",
    parts: [
      Verse(1, "O let the Son of God enfold you\nWith His Spirit and His love\nLet Him fill your heart and satisfy your soul\nO let Him have the things that hold you\nAnd His Spirit like a dove\nWill descend upon your life and make you whole"),
      Chorus("Jesus, O Jesus\nCome and fill Your lambs\nJesus, O Jesus\nCome and fill Your lambs"),
      Verse(2, "O come and sing this song with gladness\nAs your hearts are filled with joy\nLift your hands in sweet surrender to His name\nO give Him all your tears and sadness\nGive Him all your years of pain\nAnd you'll enter into life in Jesus' name"),
    ],
  ),
  Song(id: 183, number: 183,
    title: "Stand up, stand up for Jesus, ye soldiers of the cross",
    author: "George Duffield Jr.",
    parts: [
      Verse(1, "Stand up, stand up for Jesus, ye soldiers of the cross\nLift high His royal banner, it must not suffer loss\nFrom victory unto victory His army shall He lead\nTill every foe is vanquished, and Christ is Lord indeed"),
      Verse(2, "Stand up, stand up for Jesus, the solemn watchword hear\nIf while ye sleep He suffers, away with shame and fear\nWhere'er ye meet with evil, within you or without\nCharge for the God of battles, and put the foe to rout"),
      Verse(3, "Stand up, stand up for Jesus, the trumpet call obey\nForth to the mighty conflict, in this His glorious day\nYe that are brave now serve Him against unnumbered foes\nLet courage rise with danger, and strength to strength oppose"),
      Verse(4, "Stand up, stand up for Jesus, stand in His strength alone\nThe arm of flesh will fail you, ye dare not trust your own\nPut on the Gospel armor, each piece put on with prayer\nWhere duty calls or danger, be never wanting there"),
      Verse(5, "Stand up, stand up for Jesus, each soldier to his post\nClose up the broken column, and shout through all the host\nMake good the loss so heavy, in those that still remain\nAnd prove to all around you that death itself is gain"),
      Verse(6, "Stand up, stand up for Jesus, the strife will not be long\nThis day the noise of battle, the next the victor's song\nTo those who vanquish evil a crown of life shall be\nThey with the King of Glory shall reign eternally"),
    ],
  ),
  Song(id: 184, number: 184,
    title: "On a hill far away stood an old rugged cross",
    author: "George Bennard",
    parts: [
      Verse(1, "On a hill far away stood an old rugged cross\nThe emblem of suffering and shame\nAnd I love that old cross where the dearest and best\nFor a world of lost sinners was slain"),
      Chorus("So I'll cherish the old rugged cross\nTill my trophies at last I lay down\nI will cling to the old rugged cross\nAnd exchange it some day for a crown"),
      Verse(2, "O that old rugged cross, so despised by the world\nHas a wondrous attraction for me\nFor the dear Lamb of God left His glory above\nTo bear it to dark Calvary"),
      Verse(3, "In that old rugged cross, stained with blood so divine\nA wondrous beauty I see\nFor 'twas on that old cross Jesus suffered and died\nTo pardon and sanctify me"),
      Verse(4, "To the old rugged cross I will ever be true\nIts shame and reproach gladly bear\nThen he'll call me some day to my home far away\nWhere his glory forever I'l share"),
    ],
  ),
  Song(id: 185, number: 185,
    title: "Guide me, O Thou great Jehovah",
    author: "William Williams",
    parts: [
      Verse(1, "Guide me, O Thou great Jehovah\nPilgrim through this barren land\nI am weak, but Thou art mighty\nHold me with Thy powerful hand\nBread of Heaven\nFeed me now and evermore"),
      Verse(2, "Open now the crystal fountain\nWhence the healing stream doth flow\nLet the fire and cloudy pillar\nLead me all my journey through\nStrong Deliverer\nBe Thou still my Strength and Shield"),
      Verse(3, "When I tread the verge of Jordan\nBid my anxious fears subside\nDeath of death, and hell's destruction\nLand me safe on Canaan's side\nSongs of praises\nI will ever give to Thee"),
      Verse(4, "Musing on my habitation\nMusing on my heav'nly home\nFills my soul with holy longings\nCome, my Jesus, quickly come\nVanity is all I see here\nLord, I long to be with Thee!\nLord, I long to be with Thee!"),
    ],
  ),
  Song(id: 186, number: 186,
    title: "Have Thine own way, Lord! Have Thine own way",
    author: "Adelaide A. Pollard",
    parts: [
      Verse(1, "Have Thine own way, Lord! Have Thine own way!\nThou art the Potter, I am the clay\nMold me and make me after Thy will\nWhile I am waiting, yielded and still"),
      Verse(2, "Have Thine own way, Lord! Have Thine own way!\nSearch me and try me, Master, today!\nWhiter than snow, Lord, wash me just now\nAs in Thy presence humbly I bow"),
      Verse(3, "Have Thine own way, Lord! Have Thine own way!\nWounded and weary, help me, I pray!\nPower, all power, surely is Thine!\nTouch me and heal me, Savior divine"),
      Verse(4, "Have Thine own way, Lord! Have Thine own way!\nHold o'er my being absolute sway!\nFill with Thy Spirit till all shall see\nChrist only, always, living in me"),
    ],
  ),
  Song(id: 187, number: 187,
    title: "I will sing the wondrous story",
    author: "Francis H. Rowley",
    parts: [
      Verse(1, "I will sing the wondrous story\nOf the Christ Who died for me\nHow He left His home in glory\nFor the cross of Calvary"),
      Chorus("Yes, I'll sing the wondrous story\nOf the Christ Who died for me\nSing it with the saints in glory\nGathered by the crystal sea"),
      Verse(2, "I was lost, but Jesus found me\nFound the sheep that went astray\nThrew His loving arms around me\nDrew me back into His way"),
      Verse(3, "I was bruised, but Jesus healed me\nFaint was I from many a fall\nSight was gone, and fears possessed me\nBut He freed me from them all"),
      Verse(4, "Days of darkness still come o'er me\nSorrow's path I often tread\nBut His presence still is with me\nBy His guiding hand I'm led"),
      Verse(5, "He will keep me till the river\nRolls its waters at my feet\nThen He'll bear me safely over\nWhere the loved ones I shall meet"),
    ],
  ),
  Song(id: 188, number: 188,
    title: "I am weak, but Thou art strong",
    author: "Unkown",
    parts: [
      Verse(1, "I am weak, but Thou art strong\nJesus, keep me from all wrong\nI'll be satisfied as long\nAs I walk, let me walk close to Thee"),
      Chorus("Just a closer walk with Thee\nGrant it, Jesus, is my plea\nDaily walking close to Thee\nLet it be, dear Lord, let it be"),
      Verse(2, "Through this world of toil and snares\nIf I falter, Lord, who cares?\nWho with me my burden shares?\nNone but Thee, dear Lord, none but Thee"),
      Verse(3, "When my feeble life is o'er\nTime for me will be no more\nGuide me gently, safely o'er\nTo Thy kingdom shore, to Thy shore"),
    ],
  ),
  Song(id: 189, number: 189,
    title: "Revive Thy work, O Lord",
    author: "Albert Midlane",
    parts: [
      Verse(1, "Revive Thy work, O Lord\nThy mighty arm make bare\nSpeak with the voice that wakes the dead\nAnd make Thy people hear"),
      Chorus("Revive Thy work, O Lord\nWhile here to Thee we bow\nDescend O gracious Lord descend\nO come and bless us now"),
      Verse(2, "Revive Thy work, O Lord\nCreate soul-thirst for Thee\nAnd hungering for the Bread of Life\nO may our spirits be"),
      Verse(3, "Revive Thy work, O Lord\nExalt Thy precious Name\nAnd, by the Holy Ghost, our love\nFor Thee and Thine inflame"),
      Verse(4, "Revive Thy work, O Lord\nAnd give refreshing showers\nThe glory shall be all Thine own\nThe blessing, Lord, be ours"),
    ],
  ),
  Song(id: 190, number: 190,
    title: "And can it be that I should gain",
    author: "Charles Wesley",
    parts: [
      Verse(1, "And can it be that I should gain\nAn interest in the Savior's blood?\nDied He for me, who caused His pain\nFor me, who Him to death pursued?\nAmazing love! How can it be\nThat Thou, my God, shouldst die for me?\nAmazing love! How can it be\nThat Thou, my God, shouldst die for me?"),
      Verse(2, "'Tis mystery all: th'Immortal dies\nWho can explore His strange design?\nIn vain the firstborn seraph tries\nTo sound the depths of love divine\n'Tis mercy all! Let earth adore\nLet angel minds inquire no more\n'Tis mercy all! Let earth adore\nLet angel minds inquire no more"),
      Verse(3, "He left His Father's throne above\nSo free, so infinite His grace\nEmptied Himself of all but love\nAnd bled for Adam's helpless race\n'Tis mercy all, immense and free\nFor O my God, it found out me!\n'Tis mercy all, immense and free\nFor O my God, it found out me!"),
      Verse(4, "Long my imprisoned spirit lay\nFast bound in sin and nature's night\nThine eye diffused a quickening ray\nI woke, the dungeon flamed with light\nMy chains fell off, my heart was free\nI rose, went forth, and followed Thee\nMy chains fell off, my heart was free\nI rose, went forth, and followed Thee"),
      Verse(5, "No condemnation now I dread\nJesus, and all in Him, is mine\nAlive in Him, my living Head\nAnd clothed in righteousness divine\nBold I approach th'eternal throne\nAnd claim the crown, through Christ my own\nBold I approach th'eternal throne\nAnd claim the crown, through Christ my own"),
    ],
  ),
  Song(id: 191, number: 191,
    title: "What a Friend we have in Jesus",
    author: "Joseph M. Scriven",
    parts: [
      Verse(1, "What a Friend we have in Jesus, all our sins and griefs to bear!\nWhat a privilege to carry everything to God in prayer!\nO what peace we often forfeit, O what needless pain we bear\nAll because we do not carry everything to God in prayer"),
      Verse(2, "Have we trials and temptations? Is there trouble anywhere?\nWe should never be discouraged; take it to the Lord in prayer\nCan we find a friend so faithful who will all our sorrows share?\nJesus knows our every weakness; take it to the Lord in prayer"),
      Verse(3, "Are we weak and heavy laden, cumbered with a load of care?\nPrecious Savior, still our refuge, take it to the Lord in prayer!\nDo your friends despise, forsake you? Take it to the Lord in prayer!\nIn His arms He'll take and shield you; you will find a solace there"),
      Verse(4, "Blessed Savior, Thou hast promised, Thou wilt all our burdens bear\nMay we ever, Lord, be bringing all to Thee in earnest prayer\nSoon in glory bright unclouded there will be no need for prayer\nRapture, praise and endless worship will be our sweet portion there"),
    ],
  ),
  Song(id: 192, number: 192,
    title: "Come, Thou Fount of every blessing",
    author: "Robert Robinson",
    parts: [
      Verse(1, "Come, Thou Fount of every blessing\nTune my heart to sing Thy grace\nStreams of mercy, never ceasing\nCall for songs of loudest praise\nTeach me some melodious sonnet\nSung by flaming tongues above\nO the vast, the boundless treasure\nOf my Lord's unchanging love"),
      Verse(2, "Here I raise my Ebenezer\nHither by Thy help I'm come\nAnd I hope, by Thy good pleasure\nSafely to arrive at home\nJesus sought me when a stranger\nWandering from the fold of God\nHe, to rescue me from danger\nInterposed His precious blood"),
      Verse(3, "O to grace how great a debtor\nDaily I'm constrained to be!\nLet Thy goodness, like a fetter\nBind my wandering heart to Thee\nProne to wander, Lord, I feel it\nProne to leave the God I love\nHere's my heart, O take and seal it\nSeal it for Thy courts above"),
    ],
  ),
  Song(id: 193, number: 193,
    title: "Come, ye that love the Lord",
    author: "Isaac Watts / Robert Lowry",
    parts: [
      Verse(1, "Come, ye that love the Lord\nAnd let your joys be known\nJoin in a song with sweet accord\nAnd thus surround the throne"),
      Chorus("We're marching to Zion\nBeautiful, beautiful Zion\nWe're marching upward to Zion\nThe beautiful city of God"),
      Verse(2, "Let those refuse to sing\nWho never knew our God\nBut children of the heavenly King\nMust speak their joys abroad"),
      Verse(3, "The hill of Zion yields\nA thousand sacred sweets\nBefore we reach the heavenly fields\nOr walk the golden streets"),
      Verse(4, "There we shall see His face\nAnd never, never sin\nThere, from the rivers of His grace\nDrink endless pleasures in"),
      Verse(5, "Then let our songs abound\nAnd every tear be dry\nWe are marching through Immanuel's grounds\nTo fairer worlds on high"),
    ],
  ),
  Song(id: 194, number: 194,
    title: "Down in the valley with my Savior I would go",
    author: "William Orcutt Cushing",
    parts: [
      Verse(1, "Down in the valley with my Savior I would go\nWhere the flowers are blooming and the sweet waters flow\nEverywhere He leads me I would follow, follow on\nWalking in His footsteps till the crown be won"),
      Chorus("Follow! follow! I would follow Jesus!\nAnywhere, everywhere, I would follow on!\nFollow! follow! I would follow Jesus!\nEverywhere He leads me I would follow on!"),
      Verse(2, "Down in the valley with my Savior I would go\nWhere the storms are sweeping and the dark waters flow\nWith His hand to lead me I will never, never fear\nDanger cannot fright me if my Lord is near"),
      Verse(3, "Down in the valley, or upon the mountain steep\nClose beside my Savior would my soul ever keep\nHe will lead me safely in the path that He has trod\nUp to where they gather on the hills of God"),
    ],
  ),
  Song(id: 195, number: 195,
    title: "Fear not, I am with thee",
    author: "Ludie D. Pickett",
    parts: [
      Verse(1, "\"Fear not, I am with thee\" blessed golden ray\nLike a star of glory lighting up my way\nThrough the clouds of midnight this bright promise shone\n\"I will never leave thee, never will leave thee alone\""),
      Chorus("No...never alone...No never alone\nHe promised never to leave me\nNever to leave me alone"),
      Verse(2, "Roses fade around me, lilies bloom and die\nEarthly sunbeams vanish, radiant still the sky\nJesus, Rose of Sharon, blooming for His own\nJesus, heaven's sunshine, never will leave me alone"),
      Verse(3, "Steps unseen before me, hidden dangers near\nNearer still my Savior whispering \"Be of cheer\"\nJoys like birds of springtime to my heart have flown\nSinging all so sweetly, \"He will not leave me alone\""),
    ],
  ),
  Song(id: 196, number: 196,
    title: "A wonderful Savior is Jesus my Lord",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "A wonderful Savior is Jesus my Lord\nA wonderful Savior to me\nHe hideth my soul in the cleft of the rock\nWhere rivers of pleasure I see"),
      Chorus("He hideth my soul in the cleft of the rock\nThat shadows a dry, thirsty land\nHe hideth my life with the depths of His love\nAnd covers me there with His hand\nAnd covers me there with His hand"),
      Verse(2, "A wonderful Savior is Jesus my Lord\nHe taketh my burden away\nHe holdeth me up, and I shall not be moved\nHe giveth me strength as my day"),
      Verse(3, "With numberless blessings each moment He crowns\nAnd filled with His fullness divine\nI sing in my rapture, oh, glory to God\nFor such a Redeemer as mine!"),
      Verse(4, "When clothed in His brightness, transported I rise\nTo meet Him in clouds of the sky\nHis perfect salvation, His wonderful love\nI'll shout with the millions on high"),
    ],
  ),
  Song(id: 197, number: 197,
    title: "Thou my everlasting Portion",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "Thou my everlasting Portion, more than friend or life to me\nAll along my pilgrim journey, Savior, let me walk with Thee"),
      Chorus("Close to Thee, close to Thee, close to Thee, close to Thee\nAll along my pilgrim journey, Savior, let me walk with Thee"),
      Verse(2, "Not for ease or worldly pleasure, nor for fame my prayer shall be\nGladly will I toil and suffer, only let me walk with Thee"),
      Chorus("Close to Thee, close to Thee, close to Thee, close to Thee\nGladly will I toil and suffer, only let me walk with Thee"),
      Verse(3, "Lead me through the vale of shadows, bear me over life's fitful sea\nThen the gate of life eternal may I enter, Lord, with Thee"),
      Chorus("Close to Thee, close to Thee, close to Thee, close to Thee\nThen the gate of life eternal may I enter, Lord, with Thee"),
    ],
  ),
  Song(id: 198, number: 198,
    title: "Be Thou my Vision",
    author: "Traditional Irish / Mary Byrne / Eleanor Hull",
    parts: [
      Verse(1, "Be Thou my Vision, O Lord of my heart\nNaught be all else to me, save that Thou art\nThou my best Thought, by day or by night\nWaking or sleeping, Thy presence my light"),
      Verse(2, "Be Thou my Wisdom, and Thou my true Word\nI ever with Thee and Thou with me, Lord\nThou my great Father, I Thy true son\nThou in me dwelling, and I with Thee one"),
      Verse(3, "Be Thou my battle Shield, Sword for the fight\nBe Thou my Dignity, Thou my Delight\nThou my soul's Shelter, Thou my high Tower\nRaise Thou me heavenward, O Power of my power"),
      Verse(4, "Riches I heed not, nor man's empty praise\nThou mine Inheritance, now and always\nThou and Thou only, first in my heart\nHigh King of Heaven, my Treasure Thou art"),
      Verse(5, "High King of Heaven, my victory won\nMay I reach Heaven's joys, O bright Heaven's Sun\nHeart of my own heart, whatever befall\nStill be my Vision, O Ruler of all"),
    ],
  ),
  Song(id: 199, number: 199,
    title: "Hark the herald angels sing",
    author: "Charles Wesley",
    parts: [
      Verse(1, "Hark the herald angels sing\nGlory to the newborn King!\nPeace on earth and mercy mild\nGod and sinners reconciled\nJoyful, all ye nations rise\nJoin the triumph of the skies\nWith the angelic host proclaim\nChrist is born in Bethlehem"),
      Chorus("Hark! The herald angels sing\nGlory to the newborn King!"),
      Verse(2, "Christ by highest heav'n adored\nChrist the everlasting Lord!\nLate in time behold Him come\nOffspring of a Virgin's womb\nVeiled in flesh the Godhead see\nHail the incarnate Deity\nPleased as man with man to dwell\nJesus, our Emmanuel"),
      Chorus("Hark! The herald angels sing\nGlory to the newborn King!"),
      Verse(3, "Hail the heav'n-born Prince of Peace!\nHail the Son of Righteousness!\nLight and life to all He brings\nRis'n with healing in His wings\nMild He lays His glory by\nBorn that man no more may die\nBorn to raise the sons of earth\nBorn to give them second birth"),
      Chorus("Hark! The herald angels sing\nGlory to the newborn King!"),
    ],
  ),
  Song(id: 200, number: 200,
    title: "I must tell Jesus",
    author: "Elisha A. Hoffman",
    parts: [
      Verse(1, "I must tell Jesus all of my trials\nI cannot bear these burdens alone\nIn my distress He kindly will help me\nHe ever loves and cares for His own"),
      Chorus("I must tell Jesus! I must tell Jesus!\nI cannot bear my burdens alone\nI must tell Jesus! I must tell Jesus!\nJesus can help me, Jesus alone"),
      Verse(2, "I must tell Jesus all my troubles\nHe is a kind compassionate friend\nIf I but ask Him, He will deliver\nMake of my troubles quickly an end"),
      Verse(3, "Tempted and tired, I need a great Saviour\nOne who can help my burdens to bear\nI must tell Jesus! I must tell Jesus!\nHe all my cares and sorrows will share"),
      Verse(4, "O how the world to evil allures me!\nO how my heart is tempted to sin\nI must tell Jesus, and He will help me\nOver the world the vict'ry to win"),
    ],
  ),
  Song(id: 201, number: 201,
    title: "How lovely is your dwelling place",
    author: "Traditional (Psalm 84)",
    parts: [
      Verse(1, "How lovely is your dwelling place\nOh mighty God\nThere's a hunger deep inside my soul\nOnly in your presence\nAre my heart and flesh restored, how lovely\nHow lovely is your dwelling place"),
      Verse(2, "In your courts there's shelter\nFor the greatest and the small\nThe sparrow has a place to build her nest\nThe pilgrim finds refreshing refreshness\nIn the midst of toil\nAnd each one has the strength to give a praise"),
      Verse(3, "A single day is treasured\nWhen spent in humble praise\nThan a thousand days of living without you\nThe Lord preserves his table on each one who obeys\nAnd blessings on the man whose heart is there"),
    ],
  ),
  Song(id: 202, number: 202,
    title: "Joy to the world, the Lord is come",
    author: "Isaac Watts",
    parts: [
      Verse(1, "Joy to the world, the Lord is come!\nLet earth receive her King\nLet every heart prepare Him room\nAnd Heaven and nature sing\nAnd Heaven, and Heaven, and nature sing"),
      Verse(2, "Joy to the earth, the Savior reigns!\nLet men their songs employ\nWhile fields and floods, rocks, hills and plains\nRepeat the sounding joy\nRepeat, repeat, the sounding joy"),
      Verse(3, "No more let sins and sorrows grow\nNor thorns infest the ground\nHe comes to make His blessings flow\nFar as the curse is found\nFar as, far as, the curse is found"),
      Verse(4, "He rules the world with truth and grace\nAnd makes the nations prove\nThe glories of His righteousness\nAnd wonders of His love\nAnd wonders, wonders, of His love"),
    ],
  ),
  Song(id: 203, number: 203,
    title: "Lead, kindly Light",
    author: "John Henry Newman",
    parts: [
      Verse(1, "Lead, kindly Light, amid th'encircling gloom\nLead thou me on!\nThe night is dark, and I am far from home\nLead thou me on!\nKeep thou my feet; I do not ask to see\nThe distant scene; one step enough for me"),
      Verse(2, "I was not ever thus, nor prayed that thou\nShouldst lead me on\nI loved to choose and see my path; but now\nLead thou me on!\nI loved the garish day, and, spite of fears\nPride ruled my will: remember not past years!"),
      Verse(3, "So long thy power hath blessed me, sure it still\nWill lead me on\nO'er moor and fen, o'er crag and torrent, till\nThe night is gone\nAnd with the morn those angel faces smile\nWhich I have loved long since, and lost awhile!"),
    ],
  ),
  Song(id: 204, number: 204,
    title: "Mine eyes have seen the glory",
    author: "Julia Ward Howe",
    parts: [
      Verse(1, "Mine eyes have seen the glory of the coming of the Lord\nHe is trampling out the vintage where the grapes of wrath are stored\nHe hath loosed the fateful lightning of His terrible swift sword\nHis truth is marching on"),
      Chorus("Glory! Glory! Hallelujah!\nGlory! Glory! Hallelujah!\nGlory! Glory! Hallelujah!\nHis truth is marching on"),
      Verse(2, "I have seen Him in the watch fires of a hundred circling camps\nThey have builded Him an altar in the evening dews and damps\nI can read His righteous sentence by the dim and flaring lamps\nHis day is marching on"),
      Verse(3, "He has sounded forth the trumpet that shall never call retreat\nHe is sifting out the hearts of men before His judgment seat\nOh, be swift, my soul, to answer Him! Be jubilant, my feet\nOur God is marching on"),
      Verse(4, "In the beauty of the lilies Christ was born across the sea\nWith a glory in His bosom that transfigures you and me\nAs He died to make men holy, let us live to make men free\nWhile God is marching on"),
      Verse(5, "He is coming like the glory of the morning on the wave\nHe is wisdom to the mighty, He is honor to the brave\nSo the world shall be His footstool, and the soul of wrong His slave\nOur God is marching on"),
    ],
  ),
  Song(id: 205, number: 205,
    title: "In the sweet by and by",
    author: "Sanford F. Bennett",
    parts: [
      Verse(1, "There's a land that is fairer than day\nAnd by faith we can see it afar\nFor the Father waits over the way\nTo prepare us a dwelling place there"),
      Chorus("In the sweet (in the sweet)\nBy and by (by and by)\nWe shall meet on that beautiful shore\nIn the sweet (in the sweet)\nBy and by (by and by)\nWe shall meet on that beautiful shore"),
      Verse(2, "We shall sing on that beautiful shore\nThe melodious songs of the blest\nAnd our spirits shall sorrow no more\nNot a sigh for the blessing of rest"),
      Verse(3, "To our bountiful Father above\nWe will offer our tribute of praise\nFor the glorious gift of His love\nAnd the blessings that hallow our days"),
    ],
  ),
  Song(id: 206, number: 206,
    title: "Shepherd of Love",
    author: "John W. Peterson",
    parts: [
      Verse(1, "Shepherd of Love, You knew I had lost my way\nShepherd of Love, You cared when I'd gone astray\nYou sought and found me, placed around me\nStrong arms that carried me home\nNo foe can harm me or alarm me, never again will I roam!"),
      Verse(2, "Shepherd of love, contentment at last is mine\nDeep in my heart, there's peace and a joy divine\nThe future's brighter, burden's lighter\nMy cup runs over each day\nYour grace supplied me, now provides me all that I need for the way"),
      Verse(3, "Shepherd of Love, my Savior and Lord and Guide\nShepherd of Love, forever I'll stay by Your side\nYou sought and found me, placed around me\nStrong arms that carried me home\nNo foe can harm me, or alarm me, never again will I roam!"),
    ],
  ),
  Song(id: 207, number: 207,
    title: "He is everything to me",
    author: "Ralph Carmichael",
    parts: [
      Verse(1, "In the stars His handiwork I see\nOn the wind He speaks with majesty\nThough He ruleth over land and sea\nWhat is that to me?"),
      Verse(2, "I will celebrate Nativity\nFor it has a place in history\nSure, He came to set His people free\nWhat is that to me?"),
      Verse(3, "Till by faith I met Him face to face\nAnd I felt the wonder of His grace\nThen I knew that He was more\nThan just a God who didn't care\nThat lived away out there"),
      Verse(4, "Now He walks beside me day by day\nEver watching o'er me lest I stray\nHelping me to find that narrow way\nHe is everything to me"),
    ],
  ),
  Song(id: 208, number: 208,
    title: "I come to the garden alone",
    author: "C. Austin Miles",
    parts: [
      Verse(1, "I come to the garden alone\nWhile the dew is still on the roses\nAnd the voice I hear falling on my ear\nThe Son of God discloses"),
      Chorus("And He walks with me, and He talks with me\nAnd He tells me I am His own\nAnd the joy we share as we tarry there\nNone other has ever known"),
      Verse(2, "He speaks, and the sound of His voice\nIs so sweet the birds hush their singing\nAnd the melody that He gave to me\nWithin my heart is ringing"),
      Verse(3, "I'd stay in the garden with Him\nThough the night around me be falling\nBut He bids me go; through the voice of woe\nHis voice to me is calling"),
    ],
  ),
  Song(id: 209, number: 209,
    title: "I know not why God's wondrous grace",
    author: "Daniel W. Whittle",
    parts: [
      Verse(1, "I know not why God's wondrous grace\nTo me He hath made known\nNor why, unworthy, Christ in love\nRedeemed me for His own"),
      Chorus("But I know Whom I have believed\nAnd am persuaded that He is able\nTo keep that which I've committed\nUnto Him against that day"),
      Verse(2, "I know not how this saving faith\nTo me He did impart\nNor how believing in His Word\nWrought peace within my heart"),
      Verse(3, "I know not how the Spirit moves\nConvincing men of sin\nRevealing Jesus through the Word\nCreating faith in Him"),
      Verse(4, "I know not what of good or ill\nMay be reserved for me\nOf weary ways or golden days\nBefore His face I see"),
      Verse(5, "I know not when my Lord may come\nAt night or noonday fair\nNor if I walk the vale with Him\nOr meet Him in the air"),
    ],
  ),
  Song(id: 210, number: 210,
    title: "O what a wonderful, wonderful day",
    author: "John W. Peterson",
    parts: [
      Verse(1, "O what a wonderful, wonderful day\nDay I will never forget\nAfter I'd wandered in darkness away\nJesus my Saviour I met\nO what tender compassionate friend\nHe met the need of my heart\nShadows dispelling with joy I am telling\nHe made all the darkness depart"),
      Chorus("Heaven came down and glory filled my soul\nWhen at the cross the Saviour made me whole\nMy sins were washed away\nAnd my night was turned to day\nHeaven came down and glory filled my soul"),
      Verse(2, "Born of the Spirit with life from above\nInto God's family divine\nJustified fully through Calvary's love\nO what a standing is mine\nAnd the transaction so quickly was made\nWhen as a sinner I came\nTook off the offer, of grace He did proffer\nHe saved me O praise His dear name"),
      Verse(3, "Now I have a hope that will surely endure\nAfter the passing of time\nI have a future in heaven for sure\nThere in those mansions sublime\nAnd it’s because of that wonderful day\nWhen at the cross I believed\nRiches eternal and blessings supernal\nFrom His precious hand I received"),
    ],
  ),
  Song(id: 211, number: 211,
    title: "I am Thine, O Lord",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "I am Thine, O Lord, I have heard Thy voice\nAnd it told Thy love to me\nBut I long to rise in the arms of faith\nAnd be closer drawn to Thee"),
      Chorus("Draw me nearer, nearer blessed Lord\nTo the cross where Thou hast died\nDraw me nearer, nearer, nearer blessed Lord\nTo Thy precious, wounded side"),
      Verse(2, "Consecrate me now to Thy service, Lord\nBy the power of grace divine\nLet my soul look up with a steadfast hope\nAnd my will be lost in Thine"),
      Verse(3, "O the pure delight of a single hour\nThat before Thy throne I spend\nWhen I kneel in prayer, and with Thee, my God\nI commune as friend with friend!"),
      Verse(4, "There are depths of love that I cannot know\nTill I cross the narrow sea\nThere are heights of joy that I may not reach\nTill I rest in peace with Thee"),
    ],
  ),
  Song(id: 212, number: 212,
    title: "Pull for the shore",
    author: "Philip P. Bliss",
    parts: [
      Verse(1, "Light in the darkness, sailor, day is at hand!\nSee o'er the foaming billows fair Haven's land\nDrear was the voyage, sailor, now almost o'er\nSafe within the lifeboat, sailor, pull for the shore"),
      Chorus("Pull for the shore, sailor, pull for the shore!\nHeed not the rolling waves, but bend to the oar\nSafe in the lifeboat, sailor, cling to self no more!\nLeave the poor old stranded wreck and pull for the shore!"),
      Verse(2, "Trust in the lifeboat, sailor; all else will fail\nStronger the surges dash and fiercer the gale\nHeed not the stormy winds, though loudly they roar\nWatch the 'bright and morning star' and pull for the shore"),
      Verse(3, "Bright gleams the morning, sailor, uplift the eye\nClouds and darkness disappearing, glory is nigh!\nSafe in the lifeboat, sailor, sing evermore\nGlory, glory, hallelujah! Pull for the shore"),
    ],
  ),
  Song(id: 213, number: 213,
    title: "We are His children",
    author: "Graham Kendrick",
    parts: [
      Verse(1, "We are His children\nThe fruit of His suffering\nSaved and redeemed by His blood\nCalled to be holy, a light to the nations\nClothed with His power\nFilled with His love"),
      Verse(2, "Go forth in His name\nProclaiming Jesus reigns\nNow is the time for the church to arise\nAnd proclaim Him Jesus, Saviour\nRedeemer and Lord\nGo forth in His name"),
      Verse(3, "Countless the souls\nThat are stumbling in darkness\nWhy do we sleep in the light?\nJesus commands us to go, make disciples\nThis is our cause, this is our fight"),
      Verse(4, "Listen the wind\nOf the spirit is blowing\nThe end of the age is so near\nPowers in the earth and heavens are shaking\nJesus our Lord soon shall appear!"),
    ],
  ),
  Song(id: 214, number: 214,
    title: "I have found a friend in Jesus",
    author: "Charles W. Fry",
    parts: [
      Verse(1, "I have found a friend in Jesus, He's everything to me\nHe's the fairest of ten thousand to my soul\nThe Lily of the Valley, in Him alone I see\nAll I need to cleanse and make me fully whole\nIn sorrow He's my comfort, in trouble He's my stay\nHe tells me every care on Him to roll\nHe's the Lily of the Valley, the Bright and Morning Star\nHe's the fairest of ten thousand to my soul"),
      Chorus("In sorrow He's my comfort\nIn trouble He's my stay\nHe tells me every care on Him to roll\nHe's the Lily of the Valley\nThe Bright and Morning Star\nHe's the fairest of ten thousand to my soul!"),
      Verse(2, "He all my grief has taken, and all my sorrows borne\nIn temptation He's my strong and mighty tower\nI've all for Him forsaken, and all my idols torn\nFrom my heart and now He keeps me by His power\nThough all the world forsake me, and Satan tempt me sore\nThrough Jesus I shall safely reach the goal\nHe's the Lily of the Valley, the Bright and Morning Star\nHe's the fairest of ten thousand to my soul"),
      Verse(3, "He will never, never leave me, nor yet forsake me here\nWhile I live by faith and do His blessed will\nA wall of fire about me, I've nothing now to fear\nWith His manna He my hungry soul shall fill\nWhen crowned at last in glory to see His blessed face\nWhere the rivers of delight shall ever roll\nHe's the Lily of the Valley, the Bright and Morning Star\nHe's the fairest of ten thousand to my soul"),
    ],
  ),
  Song(id: 215, number: 215,
    title: "More about Jesus",
    author: "Eliza E. Hewitt",
    parts: [
      Verse(1, "More about Jesus would I know\nMore of His grace to others show\nMore of His saving fullness see\nMore of His love Who died for me"),
      Chorus("More, more about Jesus\nMore, more about Jesus\nMore of His saving fullness see\nMore of His love Who died for me"),
      Verse(2, "More about Jesus let me learn\nMore of His holy will discern\nSpirit of God, my teacher be\nShowing the things of Christ to me"),
      Verse(3, "More about Jesus; in His Word\nHolding communion with my Lord\nHearing His voice in every line\nMaking each faithful saying mine"),
      Verse(4, "More about Jesus; on His throne\nRiches in glory all His own\nMore of His kingdom's sure increase\nMore of His coming, Prince of Peace"),
    ],
  ),
  Song(id: 216, number: 216,
    title: "Rescue the perishing",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "Rescue the perishing, care for the dying\nSnatch them in pity from sin and the grave\nWeep o'er the erring one, lift up the fallen\nTell them of Jesus, the mighty to save"),
      Chorus("Rescue the perishing, care for the dying\nJesus is merciful, Jesus will save"),
      Verse(2, "Though they are slighting Him, still He is waiting\nWaiting the penitent child to receive\nPlead with them earnestly, plead with them gently\nHe will forgive if they only believe"),
      Verse(3, "Down in the human heart, crushed by the tempter\nFeelings lie buried that grace can restore\nTouched by a loving heart, wakened by kindness\nChords that were broken will vibrate once more"),
      Verse(4, "Rescue the perishing, duty demands it\nStrength for thy labor the Lord will provide\nBack to the narrow way patiently win them\nTell the poor wand'rer a Savior has died"),
    ],
  ),
  Song(id: 217, number: 217,
    title: "O happy day",
    author: "Philip Doddridge",
    parts: [
      Verse(1, "O happy day, that fixed my choice\nOn Thee, my Savior and my God!\nWell may this glowing heart rejoice\nAnd tell its raptures all abroad"),
      Chorus("Happy day, happy day\nWhen Jesus washed my sins away!\nHe taught me how to watch and pray\nAnd live rejoicing every day\nHappy day, happy day\nWhen Jesus washed my sins away"),
      Verse(2, "O happy bond, that seals my vows\nTo Him Who merits all my love!\nLet cheerful anthems fill His house\nWhile to that sacred shrine I move"),
      Verse(3, "‘Tis done: the great transaction's done!\nI am the Lord's and He is mine\nHe drew me, and I followed on\nCharmed to confess the voice divine"),
      Verse(4, "Now rest, my long divided heart\nFixed on this blissful center, rest\nHere have I found a nobler part\nHere heavenly pleasures fill my breast"),
      Verse(5, "High heaven, that heard the solemn vow\nThat vow renewed shall daily hear\nTill in life's latest hour I bow\nAnd bless in death a bond so dear"),
    ],
  ),
  Song(id: 218, number: 218,
    title: "Jesus, lover of my soul",
    author: "Charles Wesley",
    parts: [
      Verse(1, "Jesus, lover of my soul, let me to Thy bosom fly\nWhile the nearer waters roll, while the tempest still is high\nHide me, O my Savior, hide, till the storm of life is past\nSafe into the haven guide; O receive my soul at last"),
      Verse(2, "Other refuge have I none, hangs my helpless soul on Thee\nLeave, ah! leave me not alone, still support and comfort me\nAll my trust on Thee is stayed, all my help from Thee I bring\nCover my defenseless head with the shadow of Thy wing"),
      Verse(3, "Wilt Thou not regard my call?\nWilt Thou not accept my prayer?\nLo! I sink, I faint, I fall—Lo! on Thee I cast my care\nReach me out Thy gracious hand!\nWhile I of Thy strength receive\nHoping against hope I stand, dying, and behold, I live"),
      Verse(4, "Thou, O Christ, art all I want\nMore than all in Thee I find\nRaise the fallen, cheer the faint\nHeal the sick, and lead the blind\nJust and holy is Thy Name, I am all unrighteousness\nFalse and full of sin I am; Thou art full of truth and grace"),
      Verse(5, "Plenteous grace with Thee is found\nGrace to cover all my sin\nLet the healing streams abound\nMake and keep me pure within\nThou of life the fountain art, freely let me take of Thee\nSpring Thou up within my heart; rise to all eternity"),
    ],
  ),
  Song(id: 219, number: 219,
    title: "Savior, like a shepherd lead us",
    author: "Dorothy A. Thrupp",
    parts: [
      Verse(1, "Savior, like a shepherd lead us, much we need Thy tender care\nIn Thy pleasant pastures feed us, for our use Thy folds prepare\nBlessed Jesus, blessed Jesus! Thou hast bought us, Thine we are"),
      Verse(2, "We are Thine, Thou dost befriend us, be the guardian of our way\nKeep Thy flock, from sin defend us, seek us when we go astray\nBlessed Jesus, blessed Jesus! Hear, O hear us when we pray"),
      Verse(3, "Thou hast promised to receive us, poor and sinful though we be\nThou hast mercy to relieve us, grace to cleanse and power to free\nBlessed Jesus, blessed Jesus! Let us early turn to Thee"),
      Verse(4, "Early let us seek Thy favor, early let us do Thy will\nBlessed Lord and only Savior, with Thy love our bosoms fill\nBlessed Jesus, blessed Jesus! Thou hast loved us, love us still"),
    ],
  ),
  Song(id: 220, number: 220,
    title: "Take time to be holy",
    author: "William D. Longstaff",
    parts: [
      Verse(1, "Take time to be holy, speak oft with thy Lord\nAbide in Him always, and feed on His Word\nMake friends of God's children, help those who are weak\nForgetting in nothing His blessing to seek"),
      Verse(2, "Take time to be holy, the world rushes on\nSpend much time in secret, with Jesus alone\nBy looking to Jesus, like Him thou shalt be\nThy friends in thy conduct His likeness shall see"),
      Verse(3, "Take time to be holy, let Him be thy Guide\nAnd run not before Him, whatever betide\nIn joy or in sorrow, still follow the Lord\nAnd, looking to Jesus, still trust in His Word"),
      Verse(4, "Take time to be holy, be calm in thy soul\nEach thought and each motive beneath His control\nThus led by His Spirit to fountains of love\nThou soon shalt be fitted for service above"),
    ],
  ),
  Song(id: 221, number: 221,
    title: "The Lord's my Shepherd",
    author: "Scottish Psalter",
    parts: [
      Verse(1, "The Lord's my Shepherd, I'll not want\nHe makes me down to lie\nIn pastures green; He leadeth me\nThe quiet waters by"),
      Verse(2, "My soul He doth restore again\nAnd me to walk doth make\nWithin the paths of righteousness\nEven for His own Name's sake"),
      Verse(3, "Yea, though I walk in death's dark vale\nYet will I fear no ill\nFor Thou art with me; and Thy rod\nAnd staff my comfort still"),
      Verse(4, "My table Thou hast furnished\nIn presence of my foes\nMy head Thou dost with oil anoint\nAnd my cup overflows"),
      Verse(5, "Goodness and mercy all my life\nShall surely follow me\nAnd in God's house forevermore\nMy dwelling place shall be"),
    ],
  ),
  Song(id: 222, number: 222,
    title: "There shall be showers of blessing",
    author: "Daniel W. Whittle",
    parts: [
      Verse(1, "There shall be showers of blessing\nThis is the promise of love\nThere shall be seasons refreshing\nSent from the Savior above"),
      Chorus("Showers of blessing\nShowers of blessing we need\nMercy drops round us are falling\nBut for the shower we plead"),
      Verse(2, "There shall be showers of blessing\nPrecious reviving again\nOver the hills and the valleys\nSound of abundance of rain"),
      Verse(3, "There shall be showers of blessing\nSend them upon us, O Lord\nGrant to us now a refreshing\nCome, and now honor Thy Word"),
      Verse(4, "There shall be showers of blessing\nOh, that today they might fall\nNow as to God we're confessing\nNow as on Jesus we call"),
    ],
  ),
  Song(id: 223, number: 223,
    title: "Bringing in the sheaves",
    author: "Knowles Shaw",
    parts: [
      Verse(1, "Sowing in the morning, sowing seeds of kindness\nSowing in the noontide and the dewy eve\nWaiting for the harvest, and the time of reaping\nWe shall come rejoicing, bringing in the sheaves"),
      Chorus("Bringing in the sheaves, bringing in the sheaves\nWe shall come rejoicing, bringing in the sheaves"),
      Verse(2, "Sowing in the sunshine, sowing in the shadows\nFearing neither clouds nor winter's chilling breeze\nBy and by the harvest, and the labor ended\nWe shall come rejoicing, bringing in the sheaves"),
      Verse(3, "Going forth with weeping, sowing for the Master\nThough the loss sustained our spirit often grieves\nWhen our weeping's over, He will bid us welcome\nWe shall come rejoicing, bringing in the sheaves"),
    ],
  ),
  Song(id: 224, number: 224,
    title: "When we all get to Heaven",
    author: "Eliza E. Hewitt",
    parts: [
      Verse(1, "Sing the wondrous love of Jesus\nSing His mercy and His grace\nIn the mansions bright and blessed\nHe'll prepare for us a place"),
      Chorus("When we all get to Heaven\nWhat a day of rejoicing that will be!\nWhen we all see Jesus\nWe'll sing and shout the victory!"),
      Verse(2, "While we walk the pilgrim pathway\nClouds will overspread the sky\nBut when traveling days are over\nNot a shadow, not a sigh"),
      Verse(3, "Let us then be true and faithful\nTrusting, serving every day\nJust one glimpse of Him in glory\nWill the toils of life repay"),
      Verse(4, "Onward to the prize before us!\nSoon His beauty we'll behold\nSoon the pearly gates will open\nWe shall tread the streets of gold"),
    ],
  ),
  Song(id: 225, number: 225,
    title: "It is well with my soul",
    author: "Horatio G. Spafford",
    parts: [
      Verse(1, "When peace, like a river, attendeth my way\nWhen sorrows like sea billows roll\nWhatever my lot, Thou has taught me to say\nIt is well, it is well, with my soul"),
      Chorus("It is well, with my soul\nIt is well, it is well, with my soul"),
      Verse(2, "Though Satan should buffet, though trials should come\nLet this blest assurance control\nThat Christ has regarded my helpless estate\nAnd hath shed His own blood for my soul"),
      Verse(3, "My sin, oh, the bliss of this glorious thought!\nMy sin, not in part but the whole\nIs nailed to the cross, and I bear it no more\nPraise the Lord, praise the Lord, O my soul!"),
      Verse(4, "For me, be it Christ, be it Christ hence to live\nIf Jordan above me shall roll\nNo pang shall be mine, for in death as in life\nThou wilt whisper Thy peace to my soul"),
      Verse(5, "But, Lord, 'tis for Thee, for Thy coming we wait\nThe sky, not the grave, is our goal\nOh trump of the angel! Oh voice of the Lord!\nBlessed hope, blessed rest of my soul!"),
      Verse(6, "And Lord, haste the day when my faith shall be sight\nThe clouds be rolled back as a scroll\nThe trump shall resound, and the Lord shall descend\nEven so, it is well with my soul"),
    ],
  ),
  Song(id: 226, number: 226,
    title: "My hope is built on nothing less",
    author: "Edward Mote",
    parts: [
      Verse(1, "My hope is built on nothing less\nThan Jesus' blood and righteousness\nI dare not trust the sweetest frame\nBut wholly trust in Jesus' Name"),
      Chorus("On Christ the solid Rock I stand\nAll other ground is sinking sand\nAll other ground is sinking sand"),
      Verse(2, "When darkness seems to hide His face\nI rest on His unchanging grace\nIn every high and stormy gale\nMy anchor holds within the veil"),
      Verse(3, "His oath, His covenant, His blood\nSupport me in the whelming flood\nWhen all around my soul gives way\nHe then is all my Hope and Stay"),
      Verse(4, "When He shall come with trumpet sound\nOh may I then in Him be found\nDressed in His righteousness alone\nFaultless to stand before the throne"),
    ],
  ),
  Song(id: 227, number: 227,
    title: "To the work!",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "To the work! To the work! We are servants of God\nLet us follow the path that our Master has trod\nWith the balm of His counsel our strength to renew\nLet us do with our might what our hands find to do"),
      Chorus("Toiling on! Toiling on!\nToiling on! Toiling on!\nLet us hope (and trust), Let us watch (and pray)\nAnd labor till the Master comes"),
      Verse(2, "To the work! To the work! Let the hungry be fed\nTo the fountain of life let the weary be led\nIn the cross and its banner our glory shall be\nWhile we herald the tidings, Salvation is free!"),
      Verse(3, "To the work! To the work! There is labor for all\nFor the kingdom of darkness and error shall fall\nAnd the love of our Father exalted shall be\nIn the loud swelling chorus, Salvation is free!"),
      Verse(4, "To the work! To the work! In the strength of the Lord\nAnd a robe and a crown shall our labor reward\nWhen the home of the faithful our dwelling shall be\nAnd we shout with the ransomed, Salvation is free!"),
    ],
  ),
  Song(id: 228, number: 228,
    title: "Take my life and let it be",
    author: "Frances R. Havergal",
    parts: [
      Verse(1, "Take my life, and let it be consecrated, Lord, to Thee\nTake my moments and my days; let them flow in ceaseless praise\nTake my hands, and let them move at the impulse of Thy love\nTake my feet, and let them be swift and beautiful for Thee"),
      Verse(2, "Take my voice, and let me sing always, only, for my King\nTake my lips, and let them be filled with messages from Thee\nTake my silver and my gold; not a mite would I withhold\nTake my intellect, and use every power as Thou shalt choose"),
      Verse(3, "Take my will, and make it Thine; it shall be no longer mine\nTake my heart, it is Thine own; it shall be Thy royal throne\nTake my love, my Lord, I pour at Thy feet its treasure store\nTake myself, and I will be ever, only, all for Thee"),
    ],
  ),
  Song(id: 229, number: 229,
    title: "I'm not ashamed to own my Lord",
    author: "Isaac Watts / Ralph E. Hudson",
    parts: [
      Verse(1, "I'm not ashamed to own my Lord\nOr to defend His cause\nMaintain the honor of His Word\nThe glory of His cross"),
      Chorus("At the cross! at the cross!\nWhere I first saw the light\nAnd the burden of my heart rolled away\nIt was there by faith I received my sight\nAnd now I'm happy all the day"),
      Verse(2, "Jesus, my God! I know His Name\nHis Name is all my trust\nNor will He put my soul to shame\nNor let my hope be lost"),
      Verse(3, "Firm as His throne His promise stands\nAnd He can well secure\nWhat I've committed to His hands\nTill the decisive hour"),
      Verse(4, "Then will He own my worthless name\nBefore His Father's face\nAnd in the new Jerusalem\nAppoint my soul a place"),
    ],
  ),
  Song(id: 230, number: 230,
    title: "I'm pressing on the upward way",
    author: "Johnson Oatman Jr.",
    parts: [
      Verse(1, "I'm pressing on the upward way\nNew heights I'm gaining every day\nStill praying as I'm onward bound\nLord, plant my feet on higher ground"),
      Chorus("Lord, lift me up and let me stand\nBy faith on heaven's table-land\nA higher plane than I have found\nLord, plant my feet on higher ground"),
      Verse(2, "My heart has no desire to stay\nWhere doubts arise and fears dismay\nThough some may dwell where these abound\nMy prayer, my aim is higher ground"),
      Verse(3, "I want to live above the world\nThough Satan's darts at me are hurled\nFor faith has caught the joyful sound\nThe song of saints on higher ground"),
      Verse(4, "I want to scale the utmost height\nAnd catch a gleam of glory bright\nBut still I'll pray, till heaven I've found\nLord, lead me on to higher ground"),
    ],
  ),
  Song(id: 231, number: 231,
    title: "It's for those tears I died",
    author: "Traditional Gospel",
    parts: [
      Verse(1, "You said you'd come and share all my sorrows\nYou said you'd be there for all my tomorrows\nI came so close to sending you away\nBut just like you promised, you came here to stay\nI just had to pray"),
      Chorus("And Jesus said\nCome to the water, stand by my side\nI know you are thirsty, you won't be denied\nI felt every tear drop, when in darkness you cried\nAnd I strove to remind you\nIt's for those tears I died"),
      Verse(2, "Your goodness so great, I can't understand it\nAnd dear Lord I know now that all this was planned\nI know You're here now and always will be\nYour love loosened my chains, and in You I'm free\nBut Jesus why me?"),
      Verse(3, "Jesus I give You, my heart and my soul\nI know now without God, I'll never be whole\nSavior, You opened all the right doors\nAnd I thank You and praise You from earth's humble shores\nTake me I'm Yours!"),
    ],
  ),
  Song(id: 232, number: 232,
    title: "Like a river glorious",
    author: "Frances R. Havergal",
    parts: [
      Verse(1, "Like a river glorious, is God's perfect peace\nOver all victorious, in its bright increase\nPerfect, yet it floweth, fuller every day\nPerfect, yet it groweth, deeper all the way"),
      Chorus("Stayed upon Jehovah, hearts are fully blest\nFinding, as He promised, perfect peace and rest"),
      Verse(2, "Hidden in the hollow of His blessed hand\nNever foe can follow, never traitor stand\nNot a surge of worry, not a shade of care\nNot a blast of hurry touch the spirit there"),
      Verse(3, "Every joy or trial falleth from above\nTraced upon our dial by the Sun of Love\nWe may trust Him fully all for us to do\nThey who trust Him wholly find Him wholly true"),
    ],
  ),
  Song(id: 233, number: 233,
    title: "It is no secret what God can do",
    author: "Stuart Hamblen",
    parts: [
      Verse(1, "The chimes of time ring out the news\nAnother day is through\nSomeone slipped and fell\nWas that someone you?\nYou may have longed for added strength\nYour courage to renew\nDo not be disheartened\nI have news for you"),
      Chorus("It is no secret what God can do\nWhat He has done for others, He'll do for you\nWith arms wide open, He'll pardon you\nIt is no secret what God can do"),
      Verse(2, "There is no night, for in His light\nYou'll never walk alone\nYou'll always feel at home wherever you may roam\nThere is no power can conquer you, while God is on your side\nTake Him at His promise, don't run away and hide"),
    ],
  ),
  Song(id: 234, number: 234,
    title: "He leadeth me",
    author: "Joseph H. Gilmore",
    parts: [
      Verse(1, "He leadeth me, O blessèd thought!\nO words with heav'nly comfort fraught!\nWhate'er I do, where'er I be\nStill 'tis God's hand that leadeth me"),
      Chorus("He leadeth me, He leadeth me\nBy His own hand He leadeth me\nHis faithful follower I would be\nFor by His hand He leadeth me"),
      Verse(2, "Sometimes mid scenes of deepest gloom\nSometimes where Eden's bowers bloom\nBy waters still, over troubled sea\nStill 'tis His hand that leadeth me"),
      Verse(3, "Lord, I would place my hand in Thine\nNor ever murmur nor repine\nContent, whatever lot I see\nSince 'tis my God that leadeth me"),
      Verse(4, "And when my task on earth is done\nWhen by Thy grace the vict'ry's won\nE'en death's cold wave I will not flee\nSince God through Jordan leadeth me"),
    ],
  ),
  Song(id: 235, number: 235,
    title: "Channels only",
    author: "Mary E. Maxwell",
    parts: [
      Verse(1, "How I praise Thee, precious Savior\nThat Thy love laid hold of me\nThou hast saved and cleansed and filled me\nThat I might Thy channel be"),
      Chorus("Channels only, blessed Master\nBut with all Thy wondrous grace\nFlowing through us, Thou canst use us\nEvery hour in every place"),
      Verse(2, "Just a channel, full of blessing\nTo the thirsty hearts around\nTo tell out Thy full salvation\nAll Thy loving message sound"),
      Verse(3, "Emptied that Thou shouldest fill me\nA clean vessel in Thine hand\nWith no strength but as Thou givest\nGraciously with each command"),
      Verse(4, "Witnessing Thy grace to save me\nSetting free from self and sin\nThou hast bought me to possess me\nIn Thy fulness, Lord, come in"),
      Verse(5, "Jesus, fill now with Thy Spirit\nHearts that full surrender know\nThat the streams of living water\nFrom our inner man may flow"),
    ],
  ),
  Song(id: 236, number: 236,
    title: "Jesus, keep me near the cross",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "Jesus, keep me near the cross\nThere a precious fountain\nFree to all, a healing stream\nFlows from Calvary's mountain"),
      Chorus("In the cross, in the cross\nBe my glory ever\nTill my raptured soul shall find\nRest beyond the river"),
      Verse(2, "Near the cross, a trembling soul\nLove and mercy found me\nThere the bright and morning star\nSheds its beams around me"),
      Verse(3, "Near the cross! O Lamb of God\nBring its scenes before me\nHelp me walk from day to day\nWith its shadows o'er me"),
      Verse(4, "Near the cross I'll watch and wait\nHoping, trusting ever\nTill I reach the golden strand\nJust beyond the river"),
    ],
  ),
  Song(id: 237, number: 237,
    title: "I gave My life for thee",
    author: "Frances R. Havergal",
    parts: [
      Verse(1, "I gave My life for thee\nMy precious blood I shed\nThat thou might'st ransomed be\nAnd quickened from the dead\nI gave My life for thee\nWhat hast thou given for Me?"),
      Verse(2, "I spent long years for thee\nIn weariness and woe\nThat an eternity\nOf joy thou mightest know\nI spent long years for thee\nHast thou spent one for Me?"),
      Verse(3, "My Father's home of light\nMy rainbow-circled throne\nI left for earthly night\nFor wanderings sad and lone\nI left it all for thee\nHast thou left aught for Me?"),
      Verse(4, "I suffered much for thee\nMore than thy tongue can tell\nOf bitter agony\nTo rescue thee from hell\nI suffered much for thee\nWhat canst thou bear for Me?"),
      Verse(5, "And I have brought to thee\nDown from My home above\nSalvation full and free\nMy pardon and My love\nI bring, I bring rich gifts to thee\nWhat hast thou brought to Me?"),
      Verse(6, "Lord, let my life be given\nAnd every moment spent\nFor God, for souls, for heaven\nAnd all earth's ties be rent\nThou gav'st Thyself for me\nNow I give all for Thee"),
    ],
  ),
  Song(id: 238, number: 238,
    title: "Pass me not, O gentle Savior",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "Pass me not, O gentle Savior\nHear my humble cry\nWhile on others Thou art calling\nDo not pass me by"),
      Chorus("Savior, Savior\nHear my humble cry\nWhile on others Thou art calling\nDo not pass me by"),
      Verse(2, "Let me at Thy throne of mercy\nFind a sweet relief\nKneeling there in deep contrition\nHelp my unbelief"),
      Verse(3, "Trusting only in Thy merit\nWould I seek Thy face\nHeal my wounded, broken spirit\nSave me by Thy grace"),
      Verse(4, "Thou the Spring of all my comfort\nMore than life to me\nWhom have I on earth beside Thee?\nWhom in Heav'n but Thee?"),
    ],
  ),
  Song(id: 239, number: 239,
    title: "Nearer, my God, to Thee",
    author: "Sarah F. Adams",
    parts: [
      Verse(1, "Nearer, my God, to Thee, nearer to Thee!\nE'en though it be a cross that raiseth me\nStill all my song shall be, nearer, my God, to Thee"),
      Chorus("Nearer, my God, to Thee\nNearer to Thee!"),
      Verse(2, "Though like the wanderer, the sun gone down\nDarkness be over me, my rest a stone\nYet in my dreams I'd be nearer, my God to Thee"),
      Verse(3, "There let the way appear, steps unto Heav'n\nAll that Thou sendest me, in mercy given\nAngels to beckon me nearer, my God, to Thee"),
      Verse(4, "Then, with my waking thoughts bright with Thy praise\nOut of my stony griefs Bethel I'll raise\nSo by my woes to be nearer, my God, to Thee"),
      Verse(5, "Or, if on joyful wing cleaving the sky\nSun, moon, and stars forgot, upward I'll fly\nStill all my song shall be, nearer, my God, to Thee"),
      Verse(6, "There in my Father's home, safe and at rest\nThere in my Savior's love, perfectly blest\nAge after age to be, nearer my God to Thee"),
    ],
  ),
  Song(id: 240, number: 240,
    title: "O Christ, in Thee my soul hath found",
    author: "Traditional Hymn",
    parts: [
      Verse(1, "O Christ, in Thee my soul hath found\nAnd found in Thee alone\nThe peace, the joy I sought so long\nThe bliss till now unknown"),
      Chorus("Now none but Christ can satisfy\nNone other name for me\nThere's love, and life, and lasting joy\nLord Jesus, found in Thee"),
      Verse(2, "I sighed for rest and happiness\nI yearned for them, not Thee\nBut while I passed my Saviour by\nHis love laid hold of me"),
      Verse(3, "I tried the broken cisterns, Lord\nBut, ah, the waters failed\nE'en as I stooped to drink they fled\nAnd mocked me as I wailed"),
      Verse(4, "The pleasures lost I sadly mourned\nBut never wept for Thee\nTill grace the sightless eyes received\nThy loveliness to see"),
    ],
  ),
  Song(id: 241, number: 241,
    title: "Safe in the arms of Jesus",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "Safe in the arms of Jesus, safe on His gentle breast\nThere by His love o'ershaded, sweetly my soul shall rest\nHark! 'tis the voice of angels, borne in a song to me\nOver the fields of glory, over the jasper sea"),
      Chorus("Safe in the arms of Jesus, safe on His gentle breast\nThere by His love o'ershaded, sweetly my soul shall rest"),
      Verse(2, "Safe in the arms of Jesus, safe from corroding care\nSafe from the world's temptations, sin cannot harm me there\nFree from the blight of sorrow, free from my doubts and fears\nOnly a few more trials, only a few more tears!"),
      Verse(3, "Jesus, my heart's dear Refuge, Jesus has died for me\nFirm on the Rock of Ages, ever my trust shall be\nHere let me wait with patience, wait till the night is over\nWait till I see the morning break on the golden shore"),
    ],
  ),
  Song(id: 242, number: 242,
    title: "Must I go, and empty handed?",
    author: "Charles C. Luther",
    parts: [
      Verse(1, "\"Must I go, and empty handed,\" Thus my dear Redeemer meet?\nNot one day of service give Him, Lay no trophy at His feet?"),
      Chorus("\"Must I go, and empty handed?\" Must I meet my Savior so?\nNot one soul with which to greet Him, Must I empty handed go?"),
      Verse(2, "Not at death I shrink or falter, For my Savior saves me now\nBut to meet Him empty handed, Thought of that now clouds my brow"),
      Verse(3, "O the years in sinning wasted, Could I but recall them now\nI would give them to my Savior, To His will I'd gladly bow"),
      Verse(4, "O ye saints, arouse, be earnest, Up and work while yet 'tis day\nEre the night of death o'ertake thee, Strive for souls while still you may"),
    ],
  ),
  Song(id: 243, number: 243,
    title: "God is good all the time",
    author: "Don Moen",
    parts: [
      Chorus("God is good, all the time\nHe put this song of praise in this heart of mine\nGod is good, all the time\nThrough the darkest night His light will shine\nGod is good, God is good all the time"),
      Verse(1, "If you're walking through the valley\nAnd there are shadows all around\nDo not fear, He will guide you\nHe will keep you safe and sound\nHe has promised to never leave you\nNor forsake you and His Word is true"),
      Verse(2, "We were sinners so unworthy\nStill for us He chose to die\nFilled us with His Holy Spirit\nNow we can stand and testify\nThat His love is everlasting\nAnd His mercies they will never end"),
      Verse(3, "Though I may not understand\nAll the plans You have for me\nMy life is in Your hands\nAnd through the eyes of faith\nI can clearly see"),
    ],
  ),
  Song(id: 244, number: 244,
    title: "When the roll is called up yonder",
    author: "James M. Black",
    parts: [
      Verse(1, "When the trumpet of the Lord shall sound, And time shall be no more\nAnd the morning breaks, eternal, bright and fair\nWhen the saved of earth shall gather Over on the other shore\nAnd the roll is called up yonder, I'll be there"),
      Chorus("When the roll is called up yonder, When the roll is called up yonder\nWhen the roll is called up yonder, I'll be there"),
      Verse(2, "On that bright and cloudless morning when the dead in Christ shall rise\nAnd the glory of His resurrection share\nWhen His chosen ones shall gather to their home beyond the skies\nAnd the roll is called up yonder, I'll be there"),
      Verse(3, "Let us labor for the Master from the dawn till setting sun\nLet us talk of all His wondrous love and care\nThen when all of life is over, and our work on earth is done\nAnd the roll is called up yonder, I'll be there"),
    ],
  ),
  Song(id: 245, number: 245,
    title: "God is here, and that to bless us",
    author: "Lewis Hartsough",
    parts: [
      Verse(1, "God is here, and that to bless us With the Spirit's quick'ning power\nSee, the cloud already bending: Waits to drop the grateful shower"),
      Chorus("Let it come, O Lord, we pray Thee\nLet the shower of blessing fall\nWe are waiting, we are waiting\nOh, revive the hearts of all"),
      Verse(2, "God is here! we feel His presence In this consecrated place\nBut we need the soul refreshing Of His free, unbounded grace"),
      Verse(3, "God is here! oh, then, believing, Bring to Him our one desire\nThat His love may now be kindled, Till its flame each heart inspire"),
      Verse(4, "Savior, grant the prayer we offer, While in simple faith we bow\nFrom the windows of Thy mercy Pour us out a blessing now"),
    ],
  ),
  Song(id: 246, number: 246,
    title: "One day at a time",
    author: "Marijohn Wilkin & Kris Kristofferson",
    parts: [
      Verse(1, "I'm only human—I'm just a man/woman\nHelp me believe in what I believe and all that I am\nShow me the stairway that I have to climb\nLord, for my sake, teach me to take, one day at a time"),
      Chorus("One day at a time, sweet Jesus\nThat's all I'm asking of You\nTeach me today, to do all the things\nThat I have to do\nYesterday's gone, sweet Jesus\nAnd tomorrow may never be mine\nLord, for my sake, teach me to take, one day at a time"),
      Verse(2, "Do you remember, when you walked among men?\nWell, Jesus you know, if you're looking below, It's worse now than then\nThere's cheating and stealing—violence and crime\nSo for my sake—teach me to take one day at a time"),
    ],
  ),
  Song(id: 247, number: 247,
    title: "God will make a way",
    author: "Don Moen",
    parts: [
      Chorus("God will make a way, where there seems to be no way\nHe works in ways we cannot see, He will make a way for me\nHe will be my guide, hold me closely to His side\nWith love and strength for each new day\nHe will make a way, He will make a way"),
      Verse(1, "By a roadway in the wilderness, He'll lead me\nAnd rivers in the desert will I see\nHeaven and earth will fade, but His Word will still remain\nHe will do something new today"),
    ],
  ),
  Song(id: 248, number: 248,
    title: "Beulah Land",
    author: "Edgar Page Stites",
    parts: [
      Verse(1, "I've reached the land of corn and wine\nAnd all its riches freely mine\nHere shines undimmed one blissful day\nFor all my night has passed away"),
      Chorus("O Beulah Land, sweet Beulah Land\nAs on thy highest mount I stand\nI look away across the sea\nWhere mansions are prepared for me\nAnd view the shining glory shore\nMy Heav'n, my home forever more!"),
      Verse(2, "My Savior comes and walks with me\nAnd sweet communion here have we\nHe gently leads me by His hand\nFor this is Heaven's border land"),
      Verse(3, "The zephyrs seem to float to me\nSweet sounds to Heaven's melody\nAs angels with the white robed throng\nJoin in the sweet redemption song"),
    ],
  ),
  Song(id: 249, number: 249,
    title: "Blessed assurance",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "Blessed assurance, Jesus is mine!\nO what a foretaste of glory divine!\nHeir of salvation, purchase of God\nBorn of His Spirit, washed in His blood"),
      Chorus("This is my story, this is my song\nPraising my Savior, all the day long\nThis is my story, this is my song\nPraising my Savior, all the day long"),
      Verse(2, "Perfect submission, perfect delight\nVisions of rapture now burst on my sight\nAngels descending bring from above\nEchoes of mercy, whispers of love"),
      Verse(3, "Perfect submission, all is at rest\nI in my Savior am happy and blest\nWatching and waiting, looking above\nFilled with His goodness, lost in His love"),
    ],
  ),
  Song(id: 250, number: 250,
    title: "This world is not my home",
    author: "Albert E. Brumley",
    parts: [
      Verse(1, "This world is not my home, I'm just passing through\nMy treasures are laid up somewhere beyond the blue\nThe angels beckon me from Heaven’s open door\nAnd I can’t feel at home in this world anymore"),
      Chorus("O Lord You know I have no friend like You\nIf Heaven’s not my home, then Lord what will I do?\nThe angels beckon me from Heaven’s open door\nAnd I can’t feel at home in this world anymore"),
      Verse(2, "They're all expecting me and that's one thing I know\nMy Savior pardoned me and now I onward go\nI know He'll take me through, though I am weak and poor"),
      Verse(3, "Just up in Glory Land we'll live eternally\nThe Saints on every hand are shouting victory\nTheir song of sweetest praise drifts back from Heaven's shore\nAnd I can't feel at home in this world anymore"),
    ],
  ),
  Song(id: 251, number: 251,
    title: "Each step I take",
    author: "W. Elmo Mercer",
    parts: [
      Verse(1, "Each step I take my Savior goes before me\nAnd with His loving hand He leads the way\nAnd with each breath I whisper, \"I adore Thee!\"\nO what joy to walk with Him each day"),
      Chorus("Each step I take I know that He will guide me—\nTo higher ground He ever leads me on\nUntil someday the last step will be taken\nEach step I take just leads me closer home"),
      Verse(2, "I trust in God, no matter come what may\nFor life eternal is in His hand\nHe holds the key that opens up the way\nThat will lead me to the promised land"),
    ],
  ),
  Song(id: 252, number: 252,
    title: "Why me Lord?",
    author: "Kris Kristofferson",
    parts: [
      Verse(1, "Why me Lord? What have I ever done to deserve even one\nOf the pleasures I've known?\nTell me Lord, what did I ever do to deserve loving You\nAnd the kindness You've shown"),
      Chorus("Lord help me Jesus I've wasted it so\nHelp me Jesus, You know what I am\nNow that I know that I've needed You so\nHelp me Jesus my soul's in Your hands"),
      Verse(2, "Try me Lord, if You think there's a way I can ever repay\nAll I've taken from You\nMaybe Lord, I can show someone else what I've been through myself\nOn my way back to You"),
    ],
  ),
  Song(id: 253, number: 253,
    title: "I feel like singing all the time",
    author: "Traditional Gospel",
    parts: [
      Verse(1, "I feel like singing all the time\nMy tears are wiped away\nFor Jesus is a friend of mine\nI'll serve Him every day"),
      Chorus("I'll praise Him, praise Him\nPraise Him all the time\nPraise Him, praise Him\nI'll praise Him all the time"),
      Verse(2, "When on the cross my Lord I saw\nNailed there by sins of mine\nFast fell the burning tears; but now\nI'm singing all the time"),
      Verse(3, "When fierce temptations try my heart\nI sing, Jesus is mine\nAnd so, though tears at times may start\nI'm singing all the time"),
      Verse(4, "The wondrous story of the Lamb\nTell with that voice of thine\nTill others, with the glad new song\nGo singing all the time"),
    ],
  ),
  Song(id: 254, number: 254,
    title: "The Lord's my shepherd I lack nothing",
    author: "Psalm 23 (Contemporary)",
    parts: [
      Verse(1, "The Lord's my shepherd I lack in nothing\nHe makes me lie down in pastures of green\nHe leads me onward by mystery waters\nHe restore my soul and guides me for the sake of His name"),
      Verse(2, "Even if shall journey through the depths of valley land\nI know there is no need to fear\nI am protected by the staff in Your hand\nAnd I am comforted just knowing that You are near"),
      Verse(3, "He will spread a table in the midst of every foe\nHe'll fill my cup and bless me with Your love\nYour tender mercies are with me as I go\nAnd I'll live forever in Your house above"),
    ],
  ),
  Song(id: 255, number: 255,
    title: "Whispering hope",
    author: "Septimus Winner",
    parts: [
      Verse(1, "Soft as the voice of an angel\nBreathing a lesson unheard\nHope with a gentle persuasion\nWhispers her comforting word\nWait till the darkness is over\nWait till the tempest is done\nHope for the sunshine tomorrow\nAfter the shower is gone"),
      Chorus("Whispering hope, oh how welcome thy voice\nMaking my heart in its sorrow rejoice"),
      Verse(2, "If, in the dusk of the twilight\nDim be the region afar\nWill not the deepening darkness\nBrighten the glimmering star?\nThen when the night is upon us\nWhy should the heart sink away?\nWhen the dark midnight is over\nWatch for the breaking of day"),
      Verse(3, "Hope, as an anchor so steadfast\nRends the dark veil for the soul\nWhither the Master has entered\nRobbing the grave of its goal\nCome then, O come, glad fruition\nCome to my sad weary heart\nCome, O Thou blest hope of glory\nNever, O never depart"),
    ],
  ),
  Song(id: 256, number: 256,
