  Song(id: 371, number: 371,
    title: "God is still on the throne",
    author: "Kittie L. Suffield",
    parts: [
      Chorus("God is still on the throne\nAnd He will remember His own\nTho' trials may press us and burdens distress us\nHe never will leave us alone\nGod is still on the throne\nHe never forsaketh His own\nHis promise is true, He will not forget you\nGod is still on the throne"),
    ],
  ),
  Song(id: 372, number: 372,
    title: "Break Thou the bread of life",
    author: "Mary A. Lathbury",
    parts: [
      Verse(1, "Break Thou the bread of life, dear Lord, to me\nAs Thou didst break the loaves beside the sea\nBeyond the sacred page I seek Thee, Lord\nMy spirit pants for Thee, O Living Word!"),
      Verse(2, "Break Thou the bread of life, O Lord, to me\nThat hid within my heart Thy Word may be\nMould Thou each inward thought, from self set free\nAnd let my steps be all controlled by Thee"),
      Verse(3, "Open Thy Word of Truth, that I may see\nThy message written clear and plain for me\nThen in sweet fellowship walking with Thee\nThine image on my life engraved will be"),
      Verse(4, "Bless Thou the truth, dear Lord, to me, to me\nAs Thou didst bless the bread by Galilee\nThen shall all bondage cease, all fetters fall\nAnd I shall find my peace, my all in all"),
    ],
  ),
  Song(id: 373, number: 373,
    title: "Standing on the promises",
    author: "R. Kelso Carter",
    parts: [
      Verse(1, "Standing on the promises of Christ my King\nThrough eternal ages let His praises ring\nGlory in the highest, I will shout and sing\nStanding on the promises of God"),
      Chorus("Standing, standing\nStanding on the promises of Christ my Savior\nStanding, standing\nI'm standing on the promises of God"),
      Verse(2, "Standing on the promises that cannot fail\nWhen the howling storms of doubt and fear assail\nBy the living Word of God I shall prevail\nStanding on the promises of God"),
      Verse(3, "Standing on the promises of Christ the Lord\nBound to Him eternally by love's strong cord\nOvercoming daily with the Spirit's sword\nStanding on the promises of God"),
      Verse(4, "Standing on the promises I cannot fall\nListening every moment to the Spirit's call\nResting in my Savior as my all in all\nStanding on the promises of God"),
    ],
  ),
  Song(id: 374, number: 374,
    title: "Open my eyes, that I may see",
    author: "Clara H. Scott",
    parts: [
      Verse(1, "Open my eyes, that I may see\nGlimpses of truth Thou hast for me\nPlace in my hands the wonderful key\nThat shall unclasp and set me free"),
      Chorus("Silently now I wait for Thee\nReady my God, Thy will to see\nOpen my eyes, illumine me\nSpirit divine!"),
      Verse(2, "Open my ears, that I may hear\nVoices of truth Thou sendest clear\nAnd while the wave notes fall on my ear\nEverything false will disappear"),
      Verse(3, "Open my mouth, and let me bear\nGladly the warm truth everywhere\nOpen my heart and let me prepare\nLove with Thy children thus to share"),
    ],
  ),
  Song(id: 375, number: 375,
    title: "Wonderful words of life",
    author: "Philip P. Bliss",
    parts: [
      Verse(1, "Sing them over again to me, wonderful words of life\nLet me more of their beauty see, wonderful words of life\nWords of life and beauty teach me faith and duty"),
      Chorus("Beautiful words, wonderful words\nWonderful words of life\nBeautiful words, wonderful words\nWonderful words of life"),
      Verse(2, "Christ, the blessed One, gives to all wonderful words of life\nSinner, list to the loving call, wonderful words of life\nAll so freely given, wooing us to heaven"),
      Verse(3, "Sweetly echo the Gospel call, wonderful words of life\nOffer pardon and peace to all, wonderful words of life\nJesus, only Savior, sanctify forever"),
    ],
  ),
  Song(id: 376, number: 376,
    title: "I love to tell the story",
    author: "Katherine Hankey",
    parts: [
      Verse(1, "I love to tell the story of unseen things above\nOf Jesus and His glory, of Jesus and His love\nI love to tell the story, because I know 'tis true\nIt satisfies my longings as nothing else can do"),
      Chorus("I love to tell the story, 'twill be my theme in glory\nTo tell the old, old story of Jesus and His love"),
      Verse(2, "I love to tell the story; more wonderful it seems\nThan all the golden fancies of all our golden dreams\nI love to tell the story, it did so much for me\nAnd that is just the reason I tell it now to thee"),
      Verse(3, "I love to tell the story; 'tis pleasant to repeat\nWhat seems, each time I tell it, more wonderfully sweet\nI love to tell the story, for some have never heard\nThe message of salvation from God's own holy Word"),
      Verse(4, "I love to tell the story, for those who know it best\nSeem hungering and thirsting to hear it like the rest\nAnd when, in scenes of glory, I sing the new, new song\n'Twill be the old, old story that I have loved so long"),
    ],
  ),
  Song(id: 377, number: 377,
    title: "Master, speak! Thy servant heareth",
    author: "Frances Ridley Havergal",
    parts: [
      Verse(1, "Master, speak! Thy servant heareth\nWaiting for Thy gracious word\nLonging for Thy voice that cheereth\nMaster! let it now be heard\nI am listening, Lord, for Thee\nWhat hast Thou to say to me?"),
      Verse(2, "Speak to me by name, O Master\nLet me know it is to me\nSpeak, that I may follow faster\nWith a step more firm and free\nWhere the Shepherd leads the flock\nIn the shadow of the rock"),
      Verse(3, "Master, speak! Though least and lowest\nLet me not unheard depart\nMaster, speak! For O, Thou knowest\nAll the yearning of my heart\nKnowest all its truest need\nSpeak! and make me blest indeed"),
      Verse(4, "Master, speak! and make me ready\nWhen Thy voice is truly heard\nWith obedience glad and steady\nStill to follow every word\nI am listening, Lord, for Thee\nMaster, speak! O, speak to me!"),
    ],
  ),
  Song(id: 378, number: 378,
    title: "Trust and obey",
    author: "John H. Sammis",
    parts: [
      Verse(1, "When we walk with the Lord in the light of His Word\nWhat a glory He sheds on our way\nWhile we do His good will, He abides with us still\nAnd with all who will trust and obey"),
      Chorus("Trust and obey, for there's no other way\nTo be happy in Jesus, but to trust and obey"),
      Verse(2, "Not a shadow can rise, not a cloud in the skies\nBut His smile quickly drives it away\nNot a doubt or a fear, not a sigh or a tear\nCan abide while we trust and obey"),
      Verse(3, "Not a burden we bear, not a sorrow we share\nBut our toil He doth richly repay\nNot a grief or a loss, not a frown or a cross\nBut is blessed if we trust and obey"),
      Verse(4, "But we never can prove the delights of His love\nUntil all on the altar we lay\nFor the favor He shows, for the joy He bestows\nAre for them who will trust and obey"),
      Verse(5, "Then in fellowship sweet we will sit at His feet\nOr we'll walk by His side in the way\nWhat He says we will do, where He sends we will go\nNever fear, only trust and obey"),
    ],
  ),
  Song(id: 379, number: 379,
    title: "Wide, wide as the ocean",
    author: "Traditional Chorus",
    parts: [
      Chorus("Wide, wide as the ocean, high as the heaven above\nDeep, deep as the deepest sea is my Savior's love\nI, though so unworthy, still am a child of His care\nFor His Word teaches me that His love reaches me everywhere"),
    ],
  ),
  Song(id: 380, number: 380,
    title: "God is moving one more time",
