  Song(id: 381, number: 381,
    title: "The law of the Lord",
    author: "Scripture Chorus (Psalm 19)",
    parts: [
      Verse(1, "The law of the Lord is perfect converting the soul\nThe testimony of the Lord is sure making wise the simple"),
