      Verse(2, "The statutes of the Lord are right rejoicing the heart\nThe commandment of the Lord is pure enlightening the eyes"),
      Verse(3, "The fear of the Lord is clean enduring forever\nThe judgements of the Lord are true and righteous altogether"),
    ],
