  Song(id: 382, number: 382,
    title: "God be with you till we meet again",
    author: "Jeremiah E. Rankin",
    parts: [
      Verse(1, "God be with you till we meet again\nBy His counsels guide, uphold you\nWith His sheep securely fold you\nGod be with you till we meet again"),
      Chorus("Till we meet, till we meet\nTill we meet at Jesus' feet\nTill we meet, till we meet\nGod be with you till we meet again"),
      Verse(2, "God be with you till we meet again\nNeath His wings protecting hide you\nDaily manna still provide you\nGod be with you till we meet again"),
      Verse(3, "God be with you till we meet again\nWhen life's perils thick confound you\nPut His arms unfailing round you\nGod be with you till we meet again"),
      Verse(4, "God be with you till we meet again\nKeep love's banner floating o'er you\nStrike death's threatening wave before you\nGod be with you till we meet again"),
    ],
  ),
  Song(id: 383, number: 383,
    title: "Bind us together",
    author: "Bob Gillman",
    parts: [
      Chorus("Bind us together, Lord, bind us together\nWith cords that cannot be broken\nBind us together, Lord, bind us together\nBind us together with love"),
      Verse(1, "There is only one God\nThere is only one King\nThere is only one Body\nThat is why we sing"),
      Verse(2, "Made for the glory of God\nPurchased by His precious Son\nBorn with the right to be clean\nFor Jesus the victory has won"),
      Verse(3, "You are the family of God\nYou are the promise divine\nYou are God's chosen desire\nYou are the glorious new wine"),
    ],
  ),
  Song(id: 384, number: 384,
    title: "I am so glad that Jesus loves me",
    author: "Philip P. Bliss",
    parts: [
      Verse(1, "I am so glad that our Father in heaven\nTells of His love in the Book He has given\nWonderful things in the Bible I see\nThis is the dearest, that Jesus loves me"),
      Chorus("I am so glad that Jesus loves me\nJesus loves me, Jesus loves me\nI am so glad that Jesus loves me\nJesus loves even me"),
      Verse(2, "Though I forget Him and wander away\nKindly He follows wherever I stray\nBack to His dear loving arms would I flee\nWhen I remember that Jesus loves me"),
      Verse(3, "O, if there's only one song I can sing\nWhen in His beauty I see the great King\nThis shall my song in eternity be\nO, what a wonder that Jesus loves me!"),
    ],
  ),
  Song(id: 385, number: 385,
    title: "O come, all ye faithful",
    author: "John Francis Wade",
    parts: [
      Verse(1, "O come, all ye faithful, joyful and triumphant\nO come ye, O come ye, to Bethlehem\nCome and behold Him, born the King of angels"),
      Chorus("O come, let us adore Him\nO come, let us adore Him\nO come, let us adore Him\nChrist the Lord"),
      Verse(2, "Sing, choirs of angels, sing in exultation\nO sing, all ye citizens of heaven above\nGlory to God, all glory in the highest"),
      Verse(3, "Yea, Lord, we greet Thee, born this happy morning\nJesus, to Thee be glory given\nWord of the Father, now in flesh appearing"),
    ],
  ),
  Song(id: 386, number: 386,
    title: "My faith looks up to Thee",
    author: "Ray Palmer",
    parts: [
      Verse(1, "My faith looks up to Thee\nThou Lamb of Calvary, Savior divine\nNow hear me while I pray, take all my guilt away\nO let me from this day be wholly Thine"),
      Verse(2, "May Thy rich grace impart\nStrength to my fainting heart, my zeal inspire\nAs Thou hast died for me, O may my love to Thee\nPure, warm, and changeless be, a living fire"),
      Verse(3, "While life's dark maze I tread\nAnd griefs around me spread, be Thou my Guide\nBid darkness turn to day, wipe sorrow's tears away\nNor let me ever stray from Thee aside"),
      Verse(4, "When ends life's transient dream\nWhen death's cold sullen stream over me roll\nBlest Savior, then in love, fear and distrust remove\nO bear me safe above, a ransomed soul"),
    ],
  ),
  Song(id: 387, number: 387,
    title: "Tell me the story of Jesus",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "Tell me the story of Jesus, write on my heart every word\nTell me the story most precious, sweetest that ever was heard\nTell how the angels in chorus sang as they welcomed His birth\nGlory to God in the highest, peace and good tidings to earth"),
      Chorus("Tell me the story of Jesus, write on my heart every word\nTell me the story most precious, sweetest that ever was heard"),
      Verse(2, "Fasting alone in the desert, tell of the days that are past\nHow for our sins He was tempted, yet was triumphant at last\nTell of the years of His labor, tell of the sorrow He bore\nHe was despised and afflicted, homeless, rejected and poor"),
      Verse(3, "Tell of the cross where they nailed Him, writhing in anguish and pain\nTell of the grave where they laid Him, tell how He liveth again\nLove in that story so tender, clearer than ever I see\nStay, let me weep while you whisper, love paid the ransom for me"),
    ],
  ),
  Song(id: 388, number: 388,
    title: "A new commandment",
    author: "Scripture Chorus (John 13:34–35)",
    parts: [
      Chorus("A new commandment I give unto you\nThat you love one another as I have loved you\nThat you love one another as I have loved you"),
      Verse(1, "By this shall all men know that you are My disciples\nIf you have love one for another\nBy this shall all men know that you are My disciples\nIf you have love one for another"),
    ],
  ),
  Song(id: 389, number: 389,
    title: "For I'm building a people of power",
    author: "Dave Richards",
    parts: [
      Verse(1, "For I'm building a people of power\nAnd I'm making a people of praise\nThat will move through this land by My Spirit\nAnd will glorify My precious name"),
      Chorus("Build Your church, Lord, make us strong, Lord\nJoin our hearts, Lord, through Your Son\nMake us one, Lord, in Your body\nIn the Kingdom of Your Son"),
    ],
  ),
  Song(id: 390, number: 390,
    title: "Because He lives",
    author: "Bill & Gloria Gaither",
    parts: [
      Verse(1, "God sent His Son, they called Him Jesus\nHe came to love, heal, and forgive\nHe lived and died to buy my pardon\nAn empty grave is there to prove my Savior lives"),
      Chorus("Because He lives, I can face tomorrow\nBecause He lives, all fear is gone\nBecause I know He holds the future\nAnd life is worth the living just because He lives"),
      Verse(2, "How sweet to hold a newborn baby\nAnd feel the pride and joy he gives\nBut greater still the calm assurance\nThis child can face uncertain days because He lives"),
      Verse(3, "And then one day I'l cross the river\nI'l fight life's final war with pain\nAnd then as death gives way to victory\nI'l see the lights of glory and I'l know He lives"),
    ],
  ),
  Song(id: 391, number: 391,
    title: "Softly and tenderly Jesus is calling",
    author: "Will L. Thompson",
    parts: [
      Verse(1, "Softly and tenderly Jesus is calling\nCalling for you and for me\nSee, on the portals He's waiting and watching\nWatching for you and for me"),
      Chorus("Come home, come home\nYou who are weary, come home\nEarnestly, tenderly, Jesus is calling\nCalling, O sinner, come home"),
      Verse(2, "Why should we tarry when Jesus is pleading\nPleading for you and for me?\nWhy should we linger and heed not His mercies\nMercies for you and for me?"),
      Verse(3, "Time is now fleeting, the moments are passing\nPassing from you and from me\nShadows are gathering, deathbeds are coming\nComing for you and for me"),
      Verse(4, "O for the wonderful love He has promised\nPromised for you and for me\nThough we have sinned, He has mercy and pardon\nPardon for you and for me"),
    ],
  ),
  Song(id: 392, number: 392,
    title: "Are you washed in the blood?",
    author: "Elisha A. Hoffman",
    parts: [
      Verse(1, "Have you been to Jesus for the cleansing power?\nAre you washed in the blood of the Lamb?\nAre you fully trusting in His grace this hour?\nAre you washed in the blood of the Lamb?"),
      Chorus("Are you washed in the blood\nIn the soul-cleansing blood of the Lamb?\nAre your garments spotless? Are they white as snow?\nAre you washed in the blood of the Lamb?"),
      Verse(2, "Are you walking daily by the Savior's side?\nAre you washed in the blood of the Lamb?\nDo you rest each moment in the Crucified?\nAre you washed in the blood of the Lamb?"),
      Verse(3, "When the Bridegroom cometh will your robes be white?\nAre you washed in the blood of the Lamb?\nWill your soul be ready for the mansions bright\nAnd be washed in the blood of the Lamb?"),
      Verse(4, "Lay aside the garments that are stained with sin\nAnd be washed in the blood of the Lamb\nThere's a fountain flowing for the soul unclean\nO be washed in the blood of the Lamb!"),
    ],
  ),
  Song(id: 393, number: 393,
    title: "Come Thou long expected Jesus",
    author: "Charles Wesley",
    parts: [
      Verse(1, "Come Thou long expected Jesus\nBorn to set Thy people free\nFrom our fears and sins release us\nLet us find our rest in Thee"),
      Verse(2, "Israel's strength and consolation\nHope of all the earth Thou art\nDear desire of every nation\nJoy of every longing heart"),
      Verse(3, "Born Thy people to deliver\nBorn a child and yet a King\nBorn to reign in us forever\nNow Thy gracious kingdom bring"),
      Verse(4, "By Thine own eternal Spirit\nRule in all our hearts alone\nBy Thine all sufficient merit\nRaise us to Thy glorious throne"),
    ],
  ),
  Song(id: 394, number: 394,
    title: "El Shaddai",
    author: "Michael Card & John Thompson",
    parts: [
      Chorus("El Shaddai, El Shaddai\nEl Elyonna Adonai\nAge to age You're still the same\nBy the power of the name\nEl Shaddai, El Shaddai\nErkamkana Adonai\nWe will praise and lift You high\nEl Shaddai"),
      Verse(1, "Through Your love and through the ram\nYou saved the son of Abraham\nThrough the power of Your hand\nYou turned the sea into dry land\nTo the outcast on her knees\nYou were the God who really sees\nAnd by Your might You set Your children free"),
      Verse(2, "Through the years You made it clear\nThat the time of Christ was near\nThough the people couldn't see\nWhat Messiah ought to be\nThough Your Word contained the plan\nThey just could not understand\nYour most awesome work was done\nIn the frailty of Your Son"),
    ],
  ),
  Song(id: 395, number: 395,
    title: "There is a fountain filled with blood",
    author: "William Cowper",
    parts: [
      Verse(1, "There is a fountain filled with blood drawn from Emmanuel's veins\nAnd sinners plunged beneath that flood lose all their guilty stains"),
      Verse(2, "The dying thief rejoiced to see that fountain in his day\nAnd there have I, though vile as he, washed all my sins away"),
      Verse(3, "Dear dying Lamb, Thy precious blood shall never lose its power\nTill all the ransomed church of God be saved, to sin no more"),
      Verse(4, "E'er since, by faith, I saw the stream Thy flowing wounds supply\nRedeeming love has been my theme, and shall be till I die"),
      Verse(5, "Then in a nobler, sweeter song I'l sing Thy power to save\nWhen this poor lisping, stammering tongue lies silent in the grave"),
    ],
  ),
  Song(id: 396, number: 396,
    title: "Go, tell it on the mountain",
    author: "John Wesley Work Jr.",
    parts: [
      Chorus("Go, tell it on the mountain\nOver the hills and everywhere\nGo, tell it on the mountain\nThat Jesus Christ is born"),
      Verse(1, "While shepherds kept their watching\nOver silent flocks by night\nBehold throughout the heavens\nThere shone a holy light"),
      Verse(2, "The shepherds feared and trembled\nWhen lo! above the earth\nRang out the angels chorus\nThat hailed the Savior's birth"),
      Verse(3, "Down in a lowly manger\nThe humble Christ was born\nAnd God sent us salvation\nThat blessed Christmas morn"),
    ],
  ),
  Song(id: 397, number: 397,
    title: "There is power in the blood",
    author: "Lewis E. Jones",
    parts: [
      Verse(1, "Would you be free from the burden of sin?\nThere's power in the blood, power in the blood\nWould you o'er evil a victory win?\nThere's wonderful power in the blood"),
      Chorus("There is power, power, wonder-working power\nIn the blood of the Lamb\nThere is power, power, wonder-working power\nIn the precious blood of the Lamb"),
      Verse(2, "Would you be free from your passion and pride?\nThere's power in the blood, power in the blood\nCome for a cleansing to Calvary's tide\nThere's wonderful power in the blood"),
      Verse(3, "Would you be whiter, much whiter than snow?\nThere's power in the blood, power in the blood\nSin stains are lost in its life-giving flow\nThere's wonderful power in the blood"),
      Verse(4, "Would you do service for Jesus your King?\nThere's power in the blood, power in the blood\nWould you live daily His praises to sing?\nThere's wonderful power in the blood"),
    ],
  ),
  Song(id: 398, number: 398,
    title: "No, not one!",
    author: "Johnson Oatman Jr.",
    parts: [
      Verse(1, "There's not a Friend like the lowly Jesus\nNo, not one! no, not one!\nNone else could heal all our souls' diseases\nNo, not one! no, not one!"),
      Chorus("Jesus knows all about our struggles\nHe will guide 'til the day is done\nThere's not a Friend like the lowly Jesus\nNo, not one! no, not one!"),
      Verse(2, "No friend like Him is so high and holy\nNo, not one! no, not one!\nAnd yet no friend is so meek and lowly\nNo, not one! no, not one!"),
      Verse(3, "There's not an hour that He is not near us\nNo, not one! no, not one!\nNo night so dark, but His love can cheer us\nNo, not one! no, not one!"),
      Verse(4, "Did ever saint find this Friend forsake him?\nNo, not one! no, not one!\nOr sinner find that He would not take him?\nNo, not one! no, not one!"),
    ],
  ),
  Song(id: 399, number: 399,
    title: "Nothing but the blood of Jesus",
    author: "Robert Lowry",
    parts: [
      Verse(1, "What can wash away my sin?\nNothing but the blood of Jesus\nWhat can make me whole again?\nNothing but the blood of Jesus"),
      Chorus("Oh! precious is the flow\nThat makes me white as snow\nNo other fount I know\nNothing but the blood of Jesus"),
      Verse(2, "For my pardon, this I see\nNothing but the blood of Jesus\nFor my cleansing this my plea\nNothing but the blood of Jesus"),
      Verse(3, "Nothing can for sin atone\nNothing but the blood of Jesus\nNaught of good that I have done\nNothing but the blood of Jesus"),
      Verse(4, "This is all my hope and peace\nNothing but the blood of Jesus\nThis is all my righteousness\nNothing but the blood of Jesus"),
      Verse(5, "Now by this I'll overcome\nNothing but the blood of Jesus\nNow by this I'l reach my home\nNothing but the blood of Jesus"),
      Verse(6, "Glory! Glory! This I sing\nNothing but the blood of Jesus\nAll my praise for this I bring\nNothing but the blood of Jesus"),
    ],
  ),
  Song(id: 400, number: 400,
    title: "Jesus saves!",
    author: "Priscilla J. Owens",
    parts: [
      Verse(1, "We have heard the joyful sound: Jesus saves! Jesus saves!\nSpread the tidings all around: Jesus saves! Jesus saves!\nBear the news to every land, climb the mountains, cross the waves\nOnward! 'tis our Lord's command; Jesus saves! Jesus saves!"),
      Verse(2, "Waft it on the rolling tide: Jesus saves! Jesus saves!\nTell to sinners far and wide: Jesus saves! Jesus saves!\nSing, you islands of the sea; echo back, you ocean caves\nEarth shall keep her jubilee: Jesus saves! Jesus saves!"),
      Verse(3, "Sing above the battle strife: Jesus saves! Jesus saves!\nBy His death and endless life Jesus saves! Jesus saves!\nShout it brightly through the gloom, when the heart for mercy craves\nSing in triumph o'er the tomb: Jesus saves! Jesus saves!"),
      Verse(4, "Give the winds a mighty voice: Jesus saves! Jesus saves!\nLet the nations now rejoice: Jesus saves! Jesus saves!\nShout salvation full and free; highest hills and deepest caves\nThis our song of victory: Jesus saves! Jesus saves!"),
    ],
  ),
  Song(id: 401, number: 401,
    title: "Have you any room for Jesus",
    author: "Daniel W. Whittle",
    parts: [
      Verse(1, "Have you any room for Jesus\nHe who bore your load of sin?\nAs He knocks and asks admission\nSinners, will you let Him in?"),
      Chorus("Room for Jesus, King of Glory!\nHasten now His Word obey\nSwing the heart's door widely open\nBid Him enter while you may"),
      Verse(2, "Room for pleasure, room for business\nBut for Christ the Crucified\nNot a place that He can enter\nIn the heart for which He died?"),
      Verse(3, "Have you any room for Jesus\nAs in grace He calls again?\nO today is time accepted\nTomorrow you may call in vain"),
      Verse(4, "Room and time now give to Jesus\nSoon will pass God's day of grace\nSoon thy heart left cold and silent\nAnd thy Savior's pleading cease"),
    ],
  ),
  Song(id: 402, number: 402,
    title: "Just as I am",
    author: "Charlotte Elliott",
    parts: [
      Verse(1, "Just as I am, without one plea\nBut that Thy blood was shed for me\nAnd that Thou bidst me come to Thee\nO Lamb of God, I come, I come"),
      Verse(2, "Just as I am, and waiting not\nTo rid my soul of one dark blot\nTo Thee whose blood can cleanse each spot\nO Lamb of God, I come, I come"),
      Verse(3, "Just as I am, though tossed about\nWith many a conflict, many a doubt\nFightings and fears within, without\nO Lamb of God, I come, I come"),
      Verse(4, "Just as I am, poor, wretched, blind\nSight, riches, healing of the mind\nYea, all I need in Thee to find\nO Lamb of God, I come, I come"),
      Verse(5, "Just as I am, Thou wilt receive\nWilt welcome, pardon, cleanse, relieve\nBecause Thy promise I believe\nO Lamb of God, I come, I come"),
      Verse(6, "Just as I am, Thy love unknown\nHath broken every barrier down\nNow, to be Thine, yea, Thine alone\nO Lamb of God, I come, I come"),
    ],
  ),
  Song(id: 403, number: 403,
    title: "Rock of Ages",
    author: "Augustus M. Toplady",
    parts: [
      Verse(1, "Rock of Ages, cleft for me\nLet me hide myself in Thee\nLet the water and the blood\nFrom Thy wounded side which flowed\nBe of sin the double cure\nSave from wrath and make me pure"),
      Verse(2, "Not the labor of my hands\nCan fulfil Thy law's demands\nCould my zeal no respite know\nCould my tears forever flow\nAll for sin could not atone\nThou must save, and Thou alone"),
      Verse(3, "Nothing in my hand I bring\nSimply to the cross I cling\nNaked, come to Thee for dress\nHelpless, look to Thee for grace\nFoul, I to the fountain fly\nWash me, Savior, or I die"),
      Verse(4, "While I draw this fleeting breath\nWhen mine eyes shall close in death\nWhen I soar to worlds unknown\nSee Thee on Thy judgment throne\nRock of Ages, cleft for me\nLet me hide myself in Thee"),
    ],
  ),
  Song(id: 404, number: 404,
    title: "Love lifted me",
    author: "James Rowe",
    parts: [
      Verse(1, "I was sinking deep in sin, sinking to rise no more\nOverwhelmed by guilt within, mercy I did implore\nThen the Master of the sea heard my despairing cry\nChrist my Savior lifted me, now safe am I"),
      Chorus("Love lifted me! Love lifted me!\nWhen nothing else could help, love lifted me!\nLove lifted me! Love lifted me!\nWhen nothing else could help, love lifted me!"),
      Verse(2, "Souls in danger, look above, Jesus completely saves\nHe will lift you by His love out of the angry waves\nHe's the Master of the sea, billows His will obey\nHe your Savior wants to be, be saved today!"),
      Verse(3, "When the waves of sorrow roll, when I am in distress\nJesus takes my hand in His, ever He loves to bless\nHe will every fear dispel, satisfy every need\nAll who heed His loving call find rest indeed"),
    ],
  ),
  Song(id: 405, number: 405,
    title: "In tenderness He sought me",
    author: "W. Spencer Walton",
    parts: [
      Verse(1, "In tenderness He sought me, weary and sick with sin\nAnd on His shoulders brought me back to His fold again\nWhile angels in His presence sang until the courts of Heaven rang"),
      Chorus("Oh, the love that sought me!\nOh, the blood that bought me!\nOh, the grace that brought me to the fold\nWondrous grace that brought me to the fold"),
      Verse(2, "He washed the bleeding sin wounds, and poured in oil and wine\nHe whispered to assure me, 'I've found thee, thou art Mine'\nI never heard a sweeter voice; it made my aching heart rejoice!"),
      Verse(3, "He pointed to the nail prints, for me His blood was shed\nA mocking crown so thorny was placed upon His head\nI wondered what He saw in me, to suffer such deep agony"),
      Verse(4, "I'm sitting in His presence, the sunshine of His face\nWhile with adoring wonder His blessings I retrace\nIt seems as if eternal days are far too short to sound His praise"),
      Verse(5, "So while the hours are passing, all now is perfect rest\nI'm waiting for the morning, the brightest and the best\nWhen He will call us to His side, to be with Him, His spotless bride"),
    ],
  ),
  Song(id: 406, number: 406,
    title: "The great Physician now is near",
    author: "William Hunter",
    parts: [
      Verse(1, "The great Physician now is near, the sympathizing Jesus\nHe speaks the drooping heart to cheer, oh! hear the voice of Jesus"),
      Chorus("Sweetest note in seraph song\nSweetest Name on mortal tongue\nSweetest carol ever sung\nJesus, blessed Jesus"),
      Verse(2, "Your many sins are all forgiv'n, oh! hear the voice of Jesus\nGo on your way in peace to Heav'n, and wear a crown with Jesus"),
      Verse(3, "The children, too, both great and small, who love the Name of Jesus\nMay now accept the gracious call to work and live for Jesus"),
      Verse(4, "His Name dispels my guilt and fear, no other name but Jesus\nOh! how my soul delights to hear the charming Name of Jesus"),
      Verse(5, "And when to that bright world above we rise to see our Jesus\nWe'll sing around the throne of love His Name, the Name of Jesus"),
    ],
  ),
  Song(id: 407, number: 407,
    title: "Though your sins be as scarlet",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "\"Though your sins be as scarlet, they shall be as white as snow\nThough they be red like crimson, they shall be as wool\"\nThough your sins be as scarlet, they shall be as white as snow"),
      Verse(2, "Hear the voice that entreats you, O return ye unto God\nHe is of great compassion, and of wondrous love\nHear the voice that entreats you, O return ye unto God"),
      Verse(3, "He'll forgive your transgressions, and remember them no more\n\"Look unto Me, ye people,\" saith the Lord your God\nHe'll forgive your transgressions, and remember them no more"),
    ],
  ),
  Song(id: 408, number: 408,
    title: "The Savior is waiting",
    author: "Ralph Carmichael",
    parts: [
      Verse(1, "The Savior is waiting to enter your heart\nWhy don't you let Him come in?\nThere's nothing in this world to keep you apart\nWhat is your answer to Him?"),
      Chorus("Time after time He has waited before\nAnd now He is waiting again\nTo see if you're willing to open the door\nO how He wants to come in"),
      Verse(2, "If you'll take one step toward the Savior, my friend\nYou'll find His arms open wide\nReceive Him and all of your darkness will end\nWithin your heart He'll abide"),
    ],
  ),
  Song(id: 409, number: 409,
    title: "Tell me the stories of Jesus",
    author: "William H. Parker",
    parts: [
      Verse(1, "Tell me the stories of Jesus I love to hear\nThings I would ask Him to tell me if He were here\nScenes by the wayside, tales of the sea\nStories of Jesus, tell them to me"),
      Verse(2, "First let me hear how the children stood round His knee\nAnd I shall fancy His blessing resting on me\nWords full of kindness, deeds full of grace\nAll in the love light of Jesus' face"),
      Verse(3, "Tell me, in accents of wonder, how rolled the sea\nTossing the boat in a tempest on Galilee\nAnd how the Maker, ready and kind\nChided the billows, and hushed the wind"),
      Verse(4, "Into the city I'd follow the children's band\nWaving a branch of the palm tree high in my hand\nOne of His heralds, yes, I would sing\nLoudest hosannas, 'Jesus is King!'"),
      Verse(5, "Show me that scene in the garden, of bitter pain\nShow me the cross where my Savior for me was slain\nSad ones or bright ones, so that they be\nStories of Jesus, tell them to me"),
    ],
  ),
  Song(id: 410, number: 410,
    title: "Shine, Jesus, shine",
    author: "Graham Kendrick",
    parts: [
      Verse(1, "Lord, the light of Your love is shining\nIn the midst of the darkness shining\nJesus, Light of the World, shine upon us\nSet us free by the truth You now bring us\nShine on me, shine on me"),
      Chorus("Shine, Jesus, shine\nFill this land with the Father's glory\nBlaze, Spirit, blaze\nSet our hearts on fire\nFlow, river, flow\nFlood the nations with grace and mercy\nSend forth Your Word\nLord, and let there be light"),
      Verse(2, "Lord, I come to Your awesome presence\nFrom the shadows into Your radiance\nBy the blood I may enter Your brightness\nSearch me, try me, consume all my darkness\nShine on me, shine on me"),
      Verse(3, "As we gaze on Your kingly brightness\nSo our faces display Your likeness\nEver changing from glory to glory\nMirrored here, may our lives tell Your story\nShine on me, shine on me"),
    ],
  ),
  Song(id: 411, number: 411,
    title: "We've a story to tell to the nations",
    author: "H. Ernest Nichol",
    parts: [
      Verse(1, "We've a story to tell to the nations\nThat shall turn their hearts to the right\nA story of truth and sweetness\nA story of peace and light\nA story of peace and light"),
      Chorus("For the darkness shall turn to dawning\nAnd the dawning to noon day bright\nAnd Christ's great kingdom shall come on earth\nThe kingdom of love and light"),
      Verse(2, "We've a song to be sung to the nations\nThat shall lift their hearts to the Lord\nA song that shall conquer evil\nAnd shatter the spear and sword\nAnd shatter the spear and sword"),
      Verse(3, "We've a message to give to the nations\nThat the Lord who reigneth above\nHath sent us His Son to save us\nAnd show us that God is love\nAnd show us that God is love"),
      Verse(4, "We've a Savior to show to the nations\nWho the path of sorrow hath trod\nThat all of the world's great peoples\nMight come to the truth of God\nMight come to the truth of God"),
    ],
  ),
  Song(id: 412, number: 412,
    title: "Jesus is tenderly calling you home",
    author: "Fanny J. Crosby",
    parts: [
      Verse(1, "Jesus is tenderly calling thee home\nCalling today, calling today\nWhy from the sunshine of love wilt thou roam\nFarther and farther away?"),
      Chorus("Calling today, calling today\nJesus is calling, is tenderly calling today"),
      Verse(2, "Jesus is calling the weary to rest\nCalling today, calling today\nBring Him thy burden and thou shalt be blest\nHe will not turn thee away"),
      Verse(3, "Jesus is waiting; O come to Him now\nWaiting today, waiting today\nCome with thy sins; at His feet lowly bow\nCome, and no longer delay"),
      Verse(4, "Jesus is pleading; O list to His voice\nHear Him today, hear Him today\nThey who believe on His name shall rejoice\nQuickly arise and away"),
    ],
  ),
  Song(id: 413, number: 413,
    title: "We'll walk the land",
    author: "Graham Kendrick",
    parts: [
      Verse(1, "We'll walk the land with hearts on fire\nAnd every step will be a prayer\nHope is rising, new day dawning\nSound of singing fills the air"),
      Verse(2, "Two thousand years and still the flame\nIs burning bright across the land\nHearts are waiting, longing, aching\nFor awakening once again"),
      Chorus("Let the flame burn brighter in the heart of the darkness\nTurning night to glorious day\nLet the song grow louder as our love grows stronger\nLet it shine, let it shine, let it shine"),
      Verse(3, "We'll walk for truth, speak out for love\nIn Jesus' name we shall be strong\nTo lift the fallen, to save the children\nTo till the nation with Your song"),
    ],
  ),
  Song(id: 414, number: 414,
    title: "Rolled away",
    author: "Traditional Chorus",
    parts: [
      Chorus("Rolled away, rolled away, rolled away\nEvery burden on my heart rolled away\nRolled away, rolled away, rolled away\nEvery burden on my heart rolled away\nAll my sin had to go, 'Neath the crimson flow\nRolled away, rolled away, rolled away\nEvery burden on my heart rolled away"),
    ],
  ),
  Song(id: 415, number: 415,
    title: "Let's talk about Jesus",
    author: "Traditional Chorus",
    parts: [
      Chorus("Let's talk about Jesus, the King of kings is He\nThe Lord of Lords supreme, through all eternity\nThe great I Am, the Way, the Truth, the Life, the Door\nLet's talk about Jesus more and more"),
    ],
  ),
  Song(id: 416, number: 416,
    title: "Jesus loves the little children (extended)",
    author: "C. Herbert Woolston",
    parts: [
      Verse(1, "Jesus calls the children dear, 'Come to Me and never fear'\nFor I love the little children of the world\nI will take you by the hand, lead you to the better land\nFor I love the little children of the world"),
      Chorus("Jesus loves the little children\nAll the children of the world\nRed and yellow, black and white\nAll are precious in His sight\nJesus loves the little children of the world"),
      Verse(2, "Jesus is the Shepherd true, and He'll always stand by you\nFor He loves the little children of the world\nHe's a Savior great and strong, and He'll shield you from the wrong\nFor He loves the little children of the world"),
      Verse(3, "I am coming, Lord, to Thee, and Your soldier I will be\nFor You love the little children of the world\nAnd Your cross I'll always bear, and for You I'll do and dare\nFor You love the little children of the world"),
    ],
  ),
  Song(id: 417, number: 417,
    title: "The wise man built his house",
    author: "Traditional Children's Song",
    parts: [
      Verse(1, "The wise man built his house upon a rock (x3)\nAnd the rain came tumbling down\nThe rain came down and the floods came up (x3)\nBut the house on the rock stood firm"),
      Verse(2, "The foolish man built his house upon the sand (x3)\nAnd the rain came tumbling down\nThe rain came down and the floods came up (x3)\nAnd the house on the sand fell flat"),
      Verse(3, "So build your life on the Lord Jesus Christ (x3)\nAnd the blessing will come down\nThe blessings come down as your prayers go up (x3)\nSo build your life on the Lord"),
    ],
  ),
  Song(id: 418, number: 418,
    title: "Over the sea",
    author: "Traditional Chorus",
    parts: [
      Chorus("Over the sea, over the sea\nJesus my Savior pilot me\nOver the sea, over the sea\nOver the boundless sea\nOver and over like a mighty sea\nComes the love of Jesus flooding over me"),
    ],
  ),
  Song(id: 419, number: 419,
    title: "Pass it on",
    author: "Kurt Kaiser",
    parts: [
      Verse(1, "It only takes a spark to get a fire going\nAnd soon all those around can warm up in its glowing\nThat's how it is with God's love once you've experienced it\nYou spread His love to everyone, you want to pass it on"),
      Verse(2, "What a wondrous time is spring when all the trees are budding\nThe birds beginning to sing, the flowers start their blooming\nThat's how it is with God's love, once you've experienced it\nYou want to sing, it's fresh like spring, you want to pass it on"),
      Verse(3, "I wish for you my friend this happiness that I've found\nYou can depend on Him, it matters not where you're bound\nI'll shout it from the mountain top, I want my world to know\nThe Lord of love has come to me, I want to pass it on"),
    ],
  ),
  Song(id: 420, number: 420,
    title: "Happiness is the Lord",
    author: "Ira Stanphill",
    parts: [
      Verse(1, "Happiness is to know the Savior\nLiving a life within His favor\nHaving a change in my behavior\nHappiness is the Lord"),
      Verse(2, "Happiness is a new creation\nJesus and me in close relation\nHaving a part in His salvation\nHappiness is the Lord"),
      Verse(3, "Happiness is to be forgiven\nLiving a life that's worth the living\nTaking a trip that leads to Heaven\nHappiness is the Lord"),
      Chorus("Happiness is the Lord\nHappiness is the Lord\nHappiness is the Lord!"),
    ],
  ),
  Song(id: 421, number: 421,
    title: "He's got the whole world in His hands",
    author: "Traditional Spiritual",
    parts: [
      Verse(1, "He's got the whole world in His hands (x3)\nHe's got the whole world in His hands"),
      Verse(2, "He's got my brothers and my sisters in His hands (x3)\nHe's got the whole world in His hands"),
      Verse(3, "He's got the sun and the rain in His hands\nHe's got the moon and the stars in His hands\nHe's got the wind and the clouds in His hands\nHe's got the whole world in His hands"),
      Verse(4, "He's got the rivers and the mountains in His hands\nHe's got the oceans and the seas in His hands\nHe's got you and me brothers in His hands\nHe's got the whole world in His hands"),
      Verse(5, "He's got everybody here in His hands\nHe's got everybody there in His hands\nHe's got everybody here in His hands\nHe's got the whole world in His hands"),
    ],
  ),
  Song(id: 422, number: 422,
    title: "I have decided to follow Jesus",
    author: "Indian Folk Hymn",
    parts: [
      Verse(1, "I have decided to follow Jesus (x3)\nNo turning back, no turning back"),
      Verse(2, "Though I may wander, I still will follow (x3)\nNo turning back, no turning back"),
      Verse(3, "Though none go with me, still I will follow (x3)\nNo turning back, no turning back"),
      Verse(4, "The world behind me, the cross before me (x3)\nNo turning back, no turning back"),
      Verse(5, "Will you decide now to follow Jesus (x3)\nNo turning back, no turning back"),
    ],
  ),
  Song(id: 423, number: 423,
    title: "Freely, freely",
    author: "Carol Owens",
    parts: [
      Verse(1, "God forgave my sins in Jesus' name\nI've been born again in Jesus' name\nAnd in Jesus' name I come to you\nTo share His love as He told me to"),
      Chorus("He said, freely, freely you have received\nFreely, freely give\nGo in My name and because you believe\nOthers will know that I live"),
      Verse(2, "All power is given in Jesus' name\nOn earth and heaven in Jesus' name\nAnd in Jesus' name I come to you\nTo share His power as He told me to"),
    ],
  ),
  Song(id: 424, number: 424,
    title: "Everybody ought to know",
    author: "Traditional Chorus",
    parts: [
      Chorus("Everybody ought to know (x2)\nEverybody ought to know who Jesus is\nHe's the lily of the valley\nHe's the bright and morning star\nHe's the fairest of ten thousand\nEverybody ought to know"),
      Verse(1, "Everybody ought to tell (x3)\nWho Jesus is\nOn the cross He died for sinners\nAnd His blood makes white as snow\nLoving, living, coming Savior\nHe's the One you ought to tell"),
    ],
  ),
  Song(id: 425, number: 425,
    title: "Jesus lives",
    author: "Traditional Chorus",
    parts: [
      Verse(1, "Jesus lives, Jesus lives\nJesus lives within my heart\nHe is my helper in times of trouble\nJesus lives forever"),
      Verse(2, "Zinda hai Yesu zinda hai\nMere dil mein Yesu zinda hai\nMusibet mein mera sahara\nYesu sada zinda hai"),
      Verse(3, "Jeevinchu chunnadu Yesu Prabhu\nNaa hrudayamulo nun nadu\nKastamulalo na sahayudai\nNityamu Jeevinchunu"),
      Verse(4, "Jeevikirar Yesu jeevikirar\nYen vulathil Yesu jeevikirar\nTun battil yendan tonay Avaray\nYen dren drum jeevikirar"),
    ],
  ),
  Song(id: 426, number: 426,
    title: "O how I love Jesus",
    author: "Frederick Whitfield",
    parts: [
      Verse(1, "There is a Name I love to hear, I love to sing its worth\nIt sounds like music in my ear, the sweetest Name on earth"),
      Chorus("O how I love Jesus\nO how I love Jesus\nO how I love Jesus\nBecause He first loved me"),
      Verse(2, "It tells me of a Savior's love, who died to set me free\nIt tells me of His precious blood, the sinner's perfect plea"),
      Verse(3, "Jesus, the Name I love so well, the Name I love to hear\nNo saint on earth its worth can tell, no heart conceive how dear"),
    ],
  ),
  Song(id: 427, number: 427,
    title: "I'd rather have Jesus",
    author: "Rhea F. Miller",
    parts: [
      Verse(1, "I'd rather have Jesus than silver or gold\nI'd rather be His than have riches untold\nI'd rather have Jesus than houses or land\nYes I'd rather be led by His nail-pierced hands"),
      Chorus("Than to be the king of a vast domain\nAnd be held in sin's dread sway\nI'd rather have Jesus than anything\nThis world affords today"),
      Verse(2, "I'd rather have Jesus than worldly applause\nI'd rather be faithful to His dear cause\nI'd rather have Jesus than world-wide fame\nI'd rather be true to His holy name"),
    ],
  ),
  Song(id: 428, number: 428,
    title: "Days of Elijah",
    author: "Robin Mark",
    parts: [
      Verse(1, "These are the days of Elijah, declaring the word of the Lord\nAnd these are the days of Your servant Moses, righteousness being restored\nAnd though these are days of great trial, of famine and darkness and sword\nStill, we are the voice in the desert crying 'Prepare ye the way of the Lord!'"),
      Chorus("Behold He comes riding on the clouds\nShining like the sun at the trumpet call\nLift your voice, it's the year of jubilee\nAnd out of Zion's hill salvation comes"),
      Verse(2, "These are the days of Ezekiel, the dry bones becoming as flesh\nAnd these are the days of Your servant David, rebuilding a temple of praise\nThese are the days of the harvest, the fields are as white in Your world\nAnd we are the labourers in Your vineyard, declaring the word of the Lord"),
      Chorus("There's no God like Jehovah\nThere's no God like Jehovah"),
    ],
  ),
  Song(id: 429, number: 429,
    title: "Across the bridge",
    author: "Traditional Gospel",
    parts: [
      Verse(1, "I have lived a life of sin, in this world I'm living in\nI have done forbidden things I shouldn't do\nAsked a beggar along the way if he could tell me where to stay\nWhere I could find real happiness and love that's true"),
      Chorus("Across the bridge there's no more sorrow\nAcross the bridge there's no more pain\nThe sun will shine across the river\nAnd you'll never be unhappy again"),
      Verse(2, "Follow the footsteps of the King, till you hear the voices ring\nThey'll be singing out the glory of the Land\nThe river Jordan will be new, and the sound of trumpet you will hear\nAnd you'll behold the most precious place never known to man"),
    ],
  ),
  Song(id: 450, number: 435,
    title: "Think About His Love",
    author: "Don Moen",
    language: Language.english,
    parts: [
      Verse(1, "Think about His love, think about His goodness\nThink about His grace that's brought us through\nFor as high as the heavens are above the earth\nSo great is the measure of our Father's love"),
      Chorus("Great is the measure of our Father's love\nGreat is the measure of our Father's love"),
      Verse(2, "How could I forget His love? How could I forget His mercy?\nHe has been so faithful, faithful to me\nFor as high as the heavens are above the earth\nSo great is the measure of our Father's love"),
    ],
  ),
  Song(id: 451, number: 436,
    title: "Be Magnified",
    author: "Don Moen",
    language: Language.english,
    parts: [
      Verse(1, "I have made You too small in my eyes\nO Lord, forgive me\nAnd I have believed in a lie\nThat You were unable to help me\nBut now, O Lord, I see my wrong\nHeal my heart and show Yourself strong\nAnd in my eyes, be magnified\nO Lord, be magnified"),
      Chorus("Be magnified, O Lord\nYou are highly exalted\nAnd there is nothing You can't do\nO Lord, my eyes are on You\nBe magnified, O Lord, be magnified"),
      Verse(2, "I have leaned on my own understanding\nLord, forgive me\nAnd I have settled for many things\nThat have not come from You\nBut now, O Lord, I see my wrong\nHeal my heart and show Yourself strong\nAnd in my eyes, be magnified\nO Lord, be magnified"),
    ],
  ),
  Song(id: 452, number: 437,
    title: "I Will Sing",
    author: "Don Moen",
    language: Language.english,
    parts: [
      Verse(1, "Lord, You seem so far away\nA million miles or more, it feels today\nAnd though I haven't lost my faith\nI must confess right now that it's hard to pray\nBut I don't need a heavy load\nAnd I don't need this rocky road\nAll I need is to bring a little bit of laughter to my soul\nIf I could only see Your face and touch Your nail-scarred hands\nI'd be free from this place"),
      Chorus("I will sing, I will pray\nLord, I will worship You with all I am\nI will sing, I will pray\nLord, I will worship You with all I am"),
      Verse(2, "Lord, take this heart of mine\nAnd make it all Your own, for all of time\nAnd though I'm weak and often fail\nYour grace is always there to prevail\nAnd I don't need a heavy load\nAnd I don't need this rocky road\nAll I need is to bring a little bit of laughter to my soul\nIf I could only see Your face and touch Your nail-scarred hands\nI'd be free from this place"),
    ],
  ),
  Song(id: 453, number: 438,
    title: "Celebrate Jesus",
    author: "Don Moen",
    language: Language.english,
    parts: [
      Chorus("Celebrate Jesus, celebrate!\nCelebrate Jesus, celebrate!\nCelebrate Jesus, celebrate!\nCelebrate Jesus, celebrate!"),
      Verse(1, "He is risen, He is risen\nAnd He lives forevermore\nHe is risen, He is risen\nCome on and celebrate the resurrection of our Lord"),
    ],
  ),
  Song(id: 454, number: 439,
    title: "He Never Sleeps",
    author: "Don Moen",
    language: Language.english,
    parts: [
      Verse(1, "When you've prayed every prayer that you know how to pray\nAnd your stretched to the limit and your faith is starting to sway\nJust remember that God is always there\nHe's the only one who really cares\nAnd He never sleeps, He never slumbers\nHe's the only one who really cares"),
      Chorus("He never sleeps, He never slumbers\nHe watches over you both day and night\nHe never sleeps, He never slumbers\nHe's the only one who really cares"),
      Verse(2, "When the road that you're on seems to have no end\nAnd you're looking for a hand to hold or just a friend\nJust remember that God is always there\nHe's the only one who really cares\nAnd He never sleeps, He never slumbers\nHe's the only one who really cares"),
    ],
  ),
  Song(id: 455, number: 440,
    title: "Agnus Dei",
    author: "Michael W. Smith",
    language: Language.english,
    parts: [
      Verse(1, "Alleluia, Alleluia\nFor the Lord God Almighty reigns\nAlleluia, Alleluia\nFor the Lord God Almighty reigns\nAlleluia"),
      Chorus("Holy, Holy\nAre You Lord God Almighty\nWorthy is the Lamb\nWorthy is the Lamb\nYou are Holy, Holy\nAre You Lord God Almighty\nWorthy is the Lamb\nWorthy is the Lamb\nAmen"),
    ],
  ),
  Song(id: 456, number: 441,
    title: "Great Is The Lord",
    author: "Michael W. Smith",
    language: Language.english,
    parts: [
      Verse(1, "Great is the Lord, He is holy and just\nBy His power He raises us up\nGreat is the Lord, He is faithful and true\nBy His mercy He makes us new"),
      Chorus("Great is the Lord, and worthy of glory\nGreat is the Lord, and worthy of praise\nGreat is the Lord, now lift up your voice\nNow lift up your voice\nGreat is the Lord, Great is the Lord"),
      Verse(2, "Great is the Lord, He is holy and just\nBy His power He raises us up\nGreat is the Lord, He is faithful and true\nBy His mercy He makes us new"),
    ],
  ),
  Song(id: 457, number: 442,
    title: "Ancient Words",
    author: "Lynn DeShazo",
    language: Language.english,
    parts: [
      Verse(1, "Holy words long preserved\nFor our walk in this world\nThey resound with God's own heart\nOh, let the Ancient words impart\nWords of Life, words of Hope\nGive us strength, help us cope\nIn this world, where e'er we roam\nAncient words will guide us Home"),
      Chorus("Ancient words ever true\nChanging me, and changing you\nWe have come with open hearts\nOh let the ancient words impart"),
      Verse(2, "Holy words of our Faith\nHanded down to this age\nCame to us through sacrifice\nOh heed the faithful words of Christ\nHoly words long preserved\nFor our walk in this world\nThey resound with God's own heart\nOh let the Ancient words impart"),
    ],
  ),
  Song(id: 458, number: 443,
    title: "The Heart of Worship",
    author: "Matt Redman",
    language: Language.english,
    parts: [
      Verse(1, "When the music fades, all is stripped away\nAnd I simply come\nLonging just to bring something that's of worth\nThat will bless Your heart"),
      Chorus("I'll bring You more than a song, for a song in itself\nIs not what You have required\nYou search much deeper within through the way things appear\nYou're looking into my heart\nI'm coming back to the heart of worship\nAnd it's all about You, it's all about You, Jesus\nI'm sorry, Lord, for the thing I've made it\nWhen it's all about You, it's all about You, Jesus"),
      Verse(2, "King of endless worth, no one could express\nHow much You deserve\nThough I'm weak and poor, all I have is Yours\nEvery single breath"),
    ],
  ),
  Song(id: 459, number: 444,
    title: "Breathe",
    author: "Marie Barnett",
    language: Language.english,
    parts: [
      Verse(1, "This is the air I breathe\nThis is the air I breathe\nYour holy presence living in me\nThis is my daily bread\nThis is my daily bread\nYour very word spoken to me"),
      Chorus("And I, I'm desperate for You\nAnd I, I'm lost without You"),
    ],
  ),
  Song(id: 460, number: 445,
    title: "Mighty to Save",
    author: "Reuben Morgan & Ben Fielding / Hillsong",
    language: Language.english,
    parts: [
      Verse(1, "Everyone needs compassion, love that's never failing\nLet mercy fall on me\nEveryone needs forgiveness, the kindness of a Savior\nThe hope of nations"),
      Chorus("Savior, He can move the mountains\nMy God is mighty to save, He is mighty to save\nForever, Author of salvation\nHe rose and conquered the grave, Jesus conquered the grave"),
      Verse(2, "So take me as You find me, all my fears and failures\nFill my life again\nI give my life to follow, everything I believe in\nNow I surrender"),
      Verse(3, "Shine your light and let the whole world see\nWe're singing for the glory of the risen King, Jesus\nShine your light and let the whole world see\nWe're singing for the glory of the risen King"),
    ],
  ),
  Song(id: 461, number: 446,
    title: "Cornerstone",
    author: "Edward Mote, Eric Liljero, Jonas Myrin, Reuben Morgan / Hillsong",
    language: Language.english,
    parts: [
      Verse(1, "My hope is built on nothing less, than Jesus' blood and righteousness\nI dare not trust the sweetest frame, but wholly trust in Jesus' name"),
      Chorus("Christ alone, Cornerstone\nWeak made strong in the Savior's love\nThrough the storm, He is Lord, Lord of all"),
      Verse(2, "When darkness seems to hide His face, I rest on His unchanging grace\nIn every high and stormy gale, my anchor holds within the veil\nMy anchor holds within the veil"),
      Verse(3, "When He shall come with trumpet sound, oh may I then in Him be found\nDressed in His righteousness alone, faultless to stand before the throne"),
    ],
  ),
  Song(id: 462, number: 447,
    title: "Still",
    author: "Reuben Morgan / Hillsong",
    language: Language.english,
    parts: [
      Verse(1, "Hide me now, under Your wings\nCover me, within Your mighty hand"),
      Chorus("When the oceans rise and thunders roar\nI will soar with You above the storm\nFather You are King over the flood\nI will be still and know You are God"),
      Verse(2, "Find rest my soul, in Christ alone\nKnow His power, in quietness and trust"),
    ],
  ),
  Song(id: 463, number: 448,
    title: "Hosanna",
    author: "Brooke Ligertwood / Hillsong",
    language: Language.english,
    parts: [
      Verse(1, "I see the King of glory, coming on the clouds with fire\nThe whole earth shakes, the whole earth shakes\nI see His love and mercy, washing over all our sin\nThe people sing, the people sing"),
      Chorus("Hosanna, hosanna\nHosanna in the highest\nHosanna, hosanna\nHosanna in the highest"),
      Verse(2, "I see a generation, rising up to take their place\nWith selfless faith, with selfless faith\nI see a near revival, stirring as we pray and seek\nWe're on our knees, we're on our knees"),
      Verse(3, "Heal my heart and make it clean\nOpen up my eyes to the things unseen\nShow me how to love like You have loved me\nBreak my heart for what breaks Yours\nEverything I am for Your Kingdom's cause\nAs I walk from earth into eternity"),
    ],
  ),
  Song(id: 464, number: 449,
    title: "Oceans (Where Feet May Fail)",
    author: "Joel Houston, Matt Crocker, Salomon Ligthelm / Hillsong",
    language: Language.english,
    parts: [
      Verse(1, "You call me out upon the waters, the great unknown where feet may fail\nAnd there I find You in the mystery, in oceans deep my faith will stand"),
      Chorus("And I will call upon Your name, and keep my eyes above the waves\nWhen oceans rise, my soul will rest in Your embrace\nFor I am Yours and You are mine"),
      Verse(2, "Your grace abounds in deepest waters, Your sovereign hand will be my guide\nWhere feet may fail and fear surrounds me, You've never failed and You won't start now"),
      Verse(3, "Spirit lead me where my trust is without borders\nLet me walk upon the waters, wherever You would call me\nTake me deeper than my feet could ever wander\nAnd my faith will be made stronger, in the presence of my Savior"),
    ],
  ),
