  Song(id: 441, number: 2,
    title: "Ruchi Chuchi Yerigithini",
    author: "Unknown",
    language: Language.telugu,
    parts: [
      Chorus("Ruchi chuchi yerigithini\nYehovah utthamudaniyu\nRuchi chuchi yerigithini\nYehovah uthamudaniyu\nRakshaku nashrayinchi\nNe dhanyudanythini\nRakshaku nashrayinchi\nNe dhanyudanythini\nRuchi chuchi yerigithini\nYehovah utthamudaniyu"),
      Verse(1, "Goppa devudavu neeve\nStuthulaaku paathrudavu neeve\nGoppa devudavu neeve\nStuthulaaku paathrudavu neeve\nThaappaka araadhinthunn\nDaayaludavu neeve\nThaappaka araadhinthunn\nDaayaludavu neeve"),
      Chorus("Ruchi chuchi yerigithini\nYehovah utthamudaniyu"),
      Verse(2, "Mahonnathudavagu deva\nPrabhavamugalavada\nMahonnathudavagu deva\nPrabhavamugalavada\nManasaara pogadedhanu nee\nAshaarya kaaryamulan\nManasaara pogadedhanu\nNee ashaarya kaaryamulan"),
      Chorus("Ruchi chuchi yerigithini\nYehova utthamudaniyu"),
      Verse(3, "Manchii thanamugala deva\nAthistrestudavu andhariloo\nManchii thanamugala deva\nAthistrestudavu aandhariloo\nMudahamaara padedha ninnu\nAthi sundarudavaniyu\nMudahamaara padedha ninnu\nAthi sundarudavaniyu"),
      Chorus("Ruchi chuchi yerigithini\nYehova utthamudaniyu\nRakshaku nashraiinchii\nNe dhanyudanythini\nRakshaku nashraiinchii\nNe dhanyudanythini\nRuchi chuchi yerigithini\nYehova utthamudaniyu\nRuchi chuchi yerigithini\nYehova utthamudaniyu"),
    ],
  ),
  Song(id: 442, number: 3,
