  Song(id: 511, number: 5,
    title: "Lekkinchaleni Stotramul",
    author: "Unknown",
    language: Language.telugu,
    parts: [
      Chorus("Lekkinchaleni stotramul Deva yellapudu ne paadedan |2|\nInta varaku naa bratukulo nivu chesina mellakai |2|"),
      Verse(1, "Aakaasha mahaakshamu – vaatiyandunna sarvambunu\nBhumilo kanabadunavanni – Prabhuva ninne keerthinchun |2|"),
