  Song(id: 512, number: 6,
    title: "Geetham Geetham Jaya Jaya Geetham",
    author: "Unknown",
    language: Language.telugu,
    parts: [
      Chorus("Geetham Geetham Jaya Jaya Geetham\nCheyyi Thatti Paadedamu |2|\nYesu Raaju Lechenu Hallelooyaa\nJaya Maarbhatinchedhamu |2|"),
      Verse(1, "Choodu Samaadhini Moosina Raayi\nDoralimpabadenu\nAndu Vesina Mudra Kaavali Nilchenu\nDaiva Suthuni Mundu"),
