  Song(id: 513, number: 7,
    title: "Sthuthiyu Mahima",
    author: "Unknown",
    language: Language.telugu,
    parts: [
      Chorus("Sthuthiyu Mahima Ghantha Neeke\nYugayugamula Varaku\nEntho Nammadagina Deva |2|"),
      Verse(1, "Maa Devudavai Maakichchithivi\nEntho Goppa Shubha Dinamu |2|\nMemandaramu Utsaahinchi Santhoshinchedamu |2|\nKoniyaadedamu Maruvabadani Melula Chesenani |2|"),
      Verse(2, "Neevokkadave Goppa Devudavu\nGhanakaaryamulu Cheyuduvu |2|\nNeedu Krupaye Nirantharamu Nilachiyundunugaa |2|\nNinnu Memu Aanandamutho Aaradhinchedamu |2|"),
