  Song(id: 431, number: 1,
    title: "Gao Hallelujah",
    author: "Yeshua Ministries",
    language: Language.hindi,
    parts: [
      Verse(1, "Yeshu ne hame Chudaya hai Paapon key Jaal se\nYeshu ne hame Bachaya hai Shaitan ki Chal se\nYeshu ne hame Chudaya hai Paapon key Jaal se\nYeshu ne hame Bachaya hai Shaitan ki Chal se"),
      Chorus("To Gao Hallelujah - ( 4 )"),
      Verse(2, "Hum ne shanti payi hai,\nYeshu ke naam se\nHum ne payi hai shama,\nMukti shrapon se\nHum ne shanti payi hai,\nYeshu ke naam se\nHum ne payi hai shama,\nMukti shrapon se"),
      Chorus("To Gao Hallelujah - ( 4 )"),
      Verse(3, "Ab hum na darenge,\nYeshu jo saat hai\nShaitan se hum ladenge,\nYeshu ke naam se\nAb hum na darenge,\nYeshu jo saat hai\nShaitan se hum ladenge,\nYeshu ke naam se"),
      Chorus("To Gao Hallelujah - ( 4 )"),
      Verse(4, "Shalom Shanti aur Salaam\nHum laye hai apke naam\nShalom Shanti aur Salaam\nYe hai Yeshu ka Paigaam\nShalom Shanti aur Salaam\nHum laye hai apke naam\nShalom Shanti aur Salaam\nYe hai Yeshu ka Paigaam"),
      Chorus("To Gao Hallelujah - ( 4 )"),
    ],
  ),
  Song(id: 433, number: 2,
    title: "Dhanyawad Ke Saath",
    author: "Unknown",
    language: Language.hindi,
    parts: [
      Chorus("Dhanyawad ke saath stuti gaoonga\nHey yeeshu mere Khuda\nUpkaar tere hain beshumaar\nKoti koti stuti dhanyawad"),
      Verse(1, "Yogyata se badke diya hai\nApni daya se tune mujhe\nMangne se zyaada mila mujhe\nAabhaari hun prabhu mai"),
      Verse(2, "Tu hai sacha zinda khuda\nTujh par hi bharosa mera\nSeva poori karke paoon inaam\nPrabhu aisa do vardaan"),
    ],
  ),
  Song(id: 434, number: 3,
    title: "Ishwar Pita Ne Sare Jagat Se",
    author: "Unknown",
    language: Language.hindi,
    parts: [
      Chorus("Ishwar pita ne sare Jagat se,\nYaisi Mohabbat Kiya\nPapon se humko mukti dilane\nYeeshu masih ko diya…2"),
      Verse(1, "Sare jahan me ek ajab sa, \nChaya tha andhiyara\nRahen nahi thi manzil nahi thi,\nInsan tha besahara…2"),
      Verse(2, "Satya vahi hai, rasta vahi hai,\nSabki sharan hai vahi\nAavo thake or bechain logo,\nAaram dega avahi…2"),
      Verse(3, "Layega jo bhi iman usa par, \nBarbad hoga nahi\nJivan milega usko sada ka, \nDil me rahega masih…2"),
    ],
  ),
  Song(id: 514, number: 4,
    title: "Prabhu Tera Naam Hai Mahan",
