  Song(id: 436, number: 2,
    title: "Yesuvae Um Naamamae",
    author: "Pas. D. Bennet Christopher",
    language: Language.tamil,
    parts: [
      Chorus("(Yesuvae um naamamae \nUyaranum Halleluyah \nYesuvae um naamamae \nPeruganum Halleluyah)\n\nUnga naamam uyaranum \nIndru menmai adaiyanum \nPaaduvaen Paaduvom Halleluyah \n\nHaleluyah - 4\nYahweh Halel Haleluyah - 2"),
      Verse(1, "Perunkaatrum adangi pogum \nEkkadalum vali thirakkum \nUnga naamam uyarthum podhu \nKanmalaiyum karaindhu pogum - (Yesuae)"),
      Verse(2, "Singathin gebiyilum \nTheechulai naduvilum \nUnga naamam uyarthum podhu \nSaedhangal anugidaadhu - (Yesuvae)"),
      Verse(3, "Siraichaalai adaippadhillai \nSangiligal nirandharam illai \nUnga naamam uyarthum podhu\nAsthibaaram nilaippadhillai - (Yesuvae)"),
    ],
