  Song(id: 437, number: 3,
    title: "Aathaaram Neer Thaan Aiyaa",
    author: "Rev. Arulappan Devadoss",
    language: Language.tamil,
    parts: [
      Chorus("Aathaaram Neer Thaan Aiyaa, Enthuraiyae,\nAathaaram Neer Thaan Aiyaa\nSoothaam Ulakil Naan Theethaal Mayangaiyil"),
      Verse(1, "Maathaa Pithaavenaith Theethaay Mathikkaiyil\nMattrokku Pattethaiyaa, Eliyan Mael,\nMattrokku Pattethaiyaa, Eliyanukku"),
      Verse(2, "Naam Naam Thunnaiyena Nayanthurai Sonnavar\nNattattil Vittaraiyaa; Thaniyanai\nNattattil Vittaraiyaa; Thaniyanukku"),
      Verse(3, "Sothanai Yadarnthu Vaethanai Thodarnthu\nThukkam Mikuvaelaiyil, En Sukirthamae,\nThukkam Mikuvaelaiyil Un Thaasanukku"),
      Verse(4, "Kattar Perumaiyae Mattror Arumaiyae,\nVatta Kirupai Nathiyae, Enpathiyae,\nVatta Kirupai Nathiyae; Enpathiyae"),
    ],
  ),
  Song(id: 438, number: 4,
    title: "En ullam enguthae",
    author: "Vijay Ebenezer",
    language: Language.tamil,
    parts: [
      Verse(1, "En ullam enguthae um anbir kagavae\nEndrendrum yenguthae um vaasam vendiyae\nendrendrum paaramal\nengendrum paaramal\nepoldhum nenjil umae thudhipaen\nKaatrorum kaatraghi\nummai thodhuven\nanandha poovaaghi umm khaalil kidapaen"),
      Chorus("Inbangal tharuveer pasathay poliveer\nepoldhul nenjil ummae thudhipaen\nUm anbai paarkilum verondrum illaiyae (oh)\nEn yesuvayae\nUm anbai paarkilum verondrum illaiyae (oh)\noru naalum maravenae enn neisar nee thaanae(oh)\nEndrendrumae naan ummai maravaen"),
      Verse(2, "oo....oo...\num satham ketudhan en nenjum koolirum\nullaadum yenangal en kanil theriyum\nsirpangal sirikum , sindhanae sirakum\nUm moogham paarthal bhoomi nillaikhum\nadhigalai nerathil en kangal thavikum\num moogham parhadhal en kanghal koolirum"),
    ],
  ),
  Song(id: 439, number: 5,
    title: "Saruva Lokaathipaa Namaskaaram!",
    author: "Vedanayagam Sastriyar",
    language: Language.tamil,
    parts: [
      Verse(1, "Saruva lokaathipaa, namaskaaram!\nSaruva sirushtikanae, namaskaaram!\nTharai, kadal, uyir, vaan sakalamum pataiththa\nThayaapara pithaavae, namaskaaram."),
      Verse(2, "Thiru avathaaraa, namaskaaram!\nJekath thiratchakanae, namaskaaram!\nTharanniyin manudar uyir atainthongath\nTharuvinil maanntooy namaskaaram."),
      Verse(3, "Parisuththa aavi, namaskaaram!\nParama sarkuruvae, namaskaaram!\nAroopiyaay atiyaar akaththinil vasikkum\nAriyasiththae sathaa namaskaaram."),
      Verse(4, "Muththolilonae, namaskaaram!\nMoontilontonae namaskaaram!\nKarththaathi karththaa, karunnaasamuththiraa,\nNithya thiriyaekaa, namaskaaram."),
    ],
  ),
  Song(id: 440, number: 6,
    title: "Dasare Itharaniyai Anbai",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Dasare Itharaniyai Anbai\n\nThaasarae iththaranniyai anpaay\nYesuvukkuch sonthamaakkuvom\n\nNaesamaay Yesuvaik kooraுvom\nAvaraik kaannpippom\nMaairul neekkuvom\nVelichcham veesuvom"),
      Verse(1, "Varuththappattu paaranj sumanthorai\nVarunthiyanpaay alaiththiduvom\nUriththaay Yesu paava paaraththai\nNamathu thukkaththai namathu thunpaththai sumanthu theerththaarae"),
      Verse(2, "Pasiyurrorkku piniyaalikatku\nPatchamaaka uthavi seyvom\nUsitha nanmaikal nirainthu thamai maranthu Yesu kaninthu thirinthanarae"),
      Verse(3, "Nerukkappattu odukkappattaோrai\nNeesarai naam uyarththiduvom\nPorukka vonna kashtaththukkul\nNishtooraththukkul padukulikkul vilunthanarae"),
      Verse(4, "Inthuthaesa maathu siromannikalai\nVinthai yolikkul varavalaippom\nSunthara kunangalatainthu ariviluyarnthu\nNirppanthangal theernthu siranthiladangida"),
      Verse(5, "Maarkkam thappi nadapporai saththiya\nValikkul vanthida serththiduvom\nOokkamaay jepiththiduvom naam\nMuyantiduvom naam jeyiththiduvom"),
    ],
  ),
  Song(id: 465, number: 7,
    title: "Then Inimaiyilum",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Then Inimaiyilum Yesuvin Naamam\nDhivya Madhuramaamae – Adhaith\nThediyae Naadi Odiyae Varuvaai\nDhinamum Nee Manamae"),
      Verse(1, "Kaasini Thenilae Nesamathaagak\nKastaththai Uththariththae – Paavak\nKasadadhai Aruththu Saabaththai Tholaiththaar\nKandunar Nee manamae – Then"),
      Verse(2, "Paaviyai Meetkkath Thaaviyae Uyiraith\nThaamae Eendhavaraam – Pinnum\nNemiyaam Karunai Nilaivaramudae\nNidham Thuthi En Manamae – Then"),
      Verse(3, "Kaalaiyil Panipol Maayamaai Yaavum (ulagam)\nUbaamayaai Neengividum – Endrum\nKartharin Paadham Nitchayam Nambu\nKaruththaai Nee Manamae – Then"),
      Verse(4, "Thunbaththil Inbam Thollaiyil Nalla\nThunaivaraam Nesaridam – Neeyum\nAnbadhaai Serndhaal\nAnaiththu Kaappaar Aasaikol Nee Manamae – Then"),
      Verse(5, "Boologaththaarum Melogaththaarum\nPugazhndhu Pottrum Naamam – Adhaip\nPoondu Kondaal than Ponnagar Vaazhvil\nPuguvaai Nee Manamae – Then"),
    ],
  ),
  Song(id: 466, number: 8,
    title: "Lesana Kariyam",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Lesana Kariyam\nLaesaana kaariyam umakku athu laesaana kaariyam ( 2 )\n\nPelan ullavan pelan attavan\nPelan ullavan pelan illaathavan\nYaaraay irunthaalum uthavikal seyvathu\nLaesaana kaariyam umakku athu laesaana kaariyam"),
      Verse(1, "Mannnnai pisainthu manithanai pataippathu laesaana kaariyam ( 2 )\nMannnnaana manuvukku mannaavai alippathu laesaana kaariyam ( 2 )\nUmakku athu laesaana kaariyam\nPelan ullavan pelan attavan\nPelan ullavan pelan illaathavan\nYaaraay irunthaalum uthavikal seyvathu\nLaesaana kaariyam umakku athu laesaana kaariyam"),
      Verse(2, "Uyir atta sadalaththai uyir pera seyvathu laesaana kaariyam ( 2 )\nTheeraatha Nnoykalai vaarththaiyaal theerppathum laesaana kaariyam ( 2 )\nUmakku athu laesaana kaariyam\nPelan ullavan pelan attavan\nPelan ullavan pelan illaathavan\nYaaraay irunthaalum uthavikal seyvathu\nLaesaana kaariyam umakku athu laesaana kaariyam"),
      Verse(3, "Idariya meenavanai seesanaay maattruvathu laesaana kaariyam ( 2 )\nItaiyanai komakanaay ariyanai aettruvathum laesaana kaariyam ( 2 )\nUmakku athu laesaana kaariyam\nPelan ullavan pelan attavan\nPelan ullavan pelan illaathavan\nYaaraay irunthaalum uthavikal seyvathu\nLaesaana kaariyam umakku athu laesaana kaariyam\nYesuvukku laesaana kaariyam\nEn Yesuvukku laesaana kaariyam ( 2 )"),
    ],
  ),
  Song(id: 467, number: 9,
    title: "Ennil Adanga Sthothiram",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Ennil Adanga Sthoththiram – Thaevaa\nEntentum Naan Paaduvaen\nInnaal Varai En Vaalvilae\nNeer Seytha Nanmaikkae"),
      Verse(1, "Vaanaathi Vaanangal Yaavum\nAthin Geelulla Aakaayamum\nPoomiyil Kaannkinta Yaavum\nKarththaa Ummaip Pottumae"),
      Verse(2, "Kaattinil Vaalkinta Yaavum\nKadum Kaattum Pani Thooralum\nNaattinil Vaalkinta Yaavum\nNaathaa Ummai Pottumae"),
      Verse(3, "Neerinil Vaalkinta Yaavum – In\nNilaththin Jeeva Raasiyum\nPaarinil Parakkinta Yaavum\nParanae Ummaip Pottumae"),
      Verse(4, "Vaala Vayathullaanorum – Mikum\nVayathaal Muthirnthorkalum\nPaalakar Tham Vaayinaalum\nPaati Ummaip Pottuvaarae"),
    ],
  ),
  Song(id: 468, number: 10,
    title: "Devapitha Yenthan Maipanallo",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Devapitha yenthan maipanallo\nSirumaiyi thalchi adaikilanae\nAavalai yenai paipulmael\nAvar maithavar neet arulukinrar"),
      Verse(2, "Athumam thananai kulirapanne\nAdiyen kalkalai neethiyanum\nNeerthiyam pathaiyil avar nimitham\nNithamum sugamai nadatukinrar"),
      Verse(3, "Sa nizhal pallathirankidinum\nSatrum theengu kandanjeenae\nVanabaran yennodirupar\nValai thadiyum kolumae thetrum\nPagaivar kethirae oru panthi"),
      Verse(4, "Paangai yenakenyerpaduthi\nSuga thailam kondaen thalaiyae\nSugamai abesakam seikuvar\nDevapitha yenthan maipanallo"),
    ],
  ),
  Song(id: 469, number: 11,
    title: "Yesuvin Naamam",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Yesuvin naamam inithaana namaam\nInnaiyillaa naamam inpa naamam-engal"),
      Verse(1, "Paavaththai pokkum payamathai neekkum\nParama santhosham paktharukkalikkum"),
      Verse(2, "Parimala thailamaam Yesuvin naamam\nPaar engum vaasanai veesidum naamam"),
      Verse(3, "Vaanilum poovilum maelaana naamam\nVaanaathi vaanavar Yesuvin naamam"),
      Verse(4, "Naettrum intrum entrum maaridaa naamam\nNampinorai entum kaividaa namaam"),
      Verse(5, "Mulangaal yaavum mudangidum naamam\nMoontil ontaka jolippavar naamam"),
      Verse(6, "Saaththaanin senaiyai jeyiththitta naamam\nSaapap pisaasai thuraththidum naamam"),
    ],
  ),
  Song(id: 470, number: 12,
    title: "Sthothiram Seivenae",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Sthothiram Seyvene – Ratchakanai (4)\nPaaththiramaaka Immaathram Karunai Vaiththa (2)\nPaarththibanai Yutha Koththiranai Endrum (…Sthothiram Seyvene)"),
      Verse(1, "Annai Marisuthanai\nPulmeethu Amizhnthu Kazhuthavanai (3)\nMunnanai Meethuttra Sinna Kumaaranai (2)\nMunnurai Noorpadi Innilath thuttronai (…Sthothiram Seyvene)"),
      Verse(2, "Kanthai Pothinthavanai\nVaanorkalum Vanthadi Pannipavanai (3)\nManthaiyarkaanantha Maatchiyaliththonai (2)\nVaana Paran Ennum Njaana Kunavaanai (…Sthothiram Seyvene)"),
      Verse(3, "Sempon nuruvaanaith\nThesikarkal Thedum Kuruvaanai (3)\nAmpara meviya Umbar Kanaththodu (2)\nAnbu Pera Nindru Paim pon Malar Thuvi (…Sthothiram Seyvene)"),
    ],
  ),
  Song(id: 471, number: 13,
    title: "Ellam Yesuve",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Ellaam Yesuvai Enakkellaa Maesuvai\nThollaimiku Mivvulakil Tholar Yaesuvai"),
      Verse(1, "Aayanum Sakaayanum Naeyanum Upaayanum\nNaayanum Enakkanpaana Njaanamana Vaalanum"),
      Verse(2, "Thanthaithaay Inamjanam Panthulor Sinaekithar\nSanthoda Sakalayoka Sampoorana Paakyamum"),
      Verse(3, "Kavalaiyil Aaruthalum Kangulilen Jothiyum\nKashdannoyp Padukkaiyilae Kaikannda Avilthamum"),
      Verse(4, "Pothakap Pithaavumen Pokkinil Varaththinil\nAatharavu Seythidung Koottaliyumen Tholanum"),
      Verse(5, "Anniyum Aaparanamum Aasthiyum Sampaathyamum\nPinnaiyaaliyum Meetparumen Piriya Maththiyasthanum"),
      Verse(6, "Aana Jeeva Appamum Aavalumena Kaavalum\nNjaanageethamum Sathurum Naattamum Konndaattamum"),
    ],
  ),
  Song(id: 472, number: 14,
    title: "Aathumame En Muzhu Ullame",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Aathumame En Muzhu Ullame\nUn Aandavarai Thozhuthethu\nInnaal Varai Anbu Vaithaatharitha\nUn Aandavarai Thozhuthethu } – 2"),
      Verse(1, "Potridum Vaanor Poothalaththulor\nSaatutharkariya Thanmaiyulla\nPotridum Vaanor Poothalaththulor\nSaatutharkariya Thanmaiyulla – Aathumame"),
      Verse(2, "Thalaimurai Thalaimurai Thaangum Vinodha\nUlaga Mun Thondri Ozhiyaatha\nThalaimurai Thalaimurai Thaangum Vinodha\nUlaga Mun Thondri Ozhiyaatha – Aathumame"),
      Verse(3, "Dhinam Dhinam Ulagil Nee Sei Palavaana\nVinai Poruththarulum Melaana\nDhinam Dhinam Ulagil Nee Sei Palavaana\nVinai Poruththarulum Melaana – Aathumame"),
      Verse(4, "Vaathai Noi Thunbam Maatri Aanantha\nOtharum Thayaisei Thuyir Thantha\nVaathai Noi Thunbam Maatri Aanantha\nOtharum Thayaisei Thuyir Thantha – Aathumame"),
      Verse(5, "Uttrunakkirangi Urimai Paaraatum\nMutrum Kirubaiyinaal Mudi Sootum\nUttrunakkirangi Urimai Paaraatum\nMutrum Kirubaiyinaal Mudi Sootum – Aathumame"),
    ],
  ),
  Song(id: 473, number: 15,
    title: "Magilvom Magilvom",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Magilvom magilvom thinam akamakilvom\nYesu iraajan nam sonthamaayinaar\nInthap paarthalaththin sonthakkaarar avar\nEnthan ullaththin sonthamaanaar"),
      Chorus("Aa aananthamae paramaananthamae\nIthu maaperum paakkiyamae – intha"),
      Verse(2, "Sinnanjiru vayathil ennaik kuriththu vittar\nThooram poyinum kanndukkonndaar\nThamathu jeevanai enakkum aliththu\nJeevan pettrukkol enturaiththaar"),
      Verse(3, "Enthach soolnilaiyum avar anpinintu\nEnnaip pirikkaathu kaaththukkolvaar\nEnnai nampi avar thantha poruppathanai\nAvar varum varaik kaaththuk kolvaen"),
      Verse(4, "Avar varum naalinil ennaik karam asaiththu\nAnpaayk kooppittuch serththukkolvaar\nAvar samookamathil angae avarudanae\nAtippaatiyae makilnthiduvaen"),
    ],
  ),
  Song(id: 474, number: 16,
    title: "Seer Yesu Nathanukku",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Seer Yesu Naathanukku Jeyamangalam Aathi\nThiriyeka Naathanukku Subamangalam\n\nPaaraetru Neethanukku Parama Porpaathanukku\nNaeraetru Pothanukku Niththiya Sangithanukku"),
      Verse(1, "Aathi Saru Vaesanukku Yesanukku Mangalam\nAkila Pirakaasanukku Nesanukku Mangalam\nNeethiparan Paalanukku Nithiya Kunnaalanukku\nOthum Anukoolanukku Uyar Manuvaelanukku"),
      Verse(2, "Maanaabi Maananukku Vaananukku Mangalam\nValar Kalai Kiyaananukku Njaananukku Mangalam\nKaanaan Nal Thaeyanukku Kanni Mariseyanukku\nKonaar Sakaayanukku Kootru Petha Leyanukku"),
      Verse(3, "Pathu Latchanathanukuch Suthanukku Mangalam\nParama Pathanukku Nithanukku Mangalam\nSathiya Visthaaranukuch Saruvaathi Kaaranukku\nPaththar Upakaaranukku Parama Kumaaranuku"),
    ],
  ),
  Song(id: 475, number: 17,
    title: "Yennaku Yaar Undu",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Yennaku Yaar Undu Kalangina Nerathil\nUm Karam Ennai Nadaththiyathae -2"),
      Chorus("Udaitheer Uruvaakineer\nShitchitheer Seerpaduthineer\nPudamittir Puthithaakkineer\nPiritheer Piriyaathiruntheer"),
      Verse(1, "Pallathin Naduvil Naan Nadanthaen\nAtchathin Utchathai Paarththaen\nOliyillaa Irulil Naan Nadanthaen\nYesuvillaa Vaalvai Naan Veruththaen -2"),
      Verse(2, "Maranathin Vilimbil Naan Irunthaen\nPaathaala Kuliyil Naan Kidanthaen\nPaavathin Paarathai Sumanthaen\nYesuvillaa Vaalvai Naan Veruthaen -2"),
    ],
  ),
  Song(id: 476, number: 18,
    title: "Sthothiram Yesu Nadha",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Sthothiram yesu Natha\nUnmakendrum sthothiram yesu natha\nSthothiram Seikindrom Ninadiyaar\nThiru namathinantharavil!"),
      Verse(2, "Vanathudhar Sennaigal\nManogarae Geethangalal yepothum\nOvindri Paadi Thuthika Maaperium\nManavane Ummaku!"),
      Verse(3, "Ithanaai Magathuvamulla\nPathavip Velaigal yengaluku\nYethanai Mathayavu ninkirubai\nYethanai Acharium!"),
      Verse(4, "Nin Uthiramathinaal\nThiranthanin Jeeva puthu Valiyam\nNinadiyarku Pithavin Sannathai\nSeiravumae Santhatham!"),
      Verse(5, "Indarai Dhinamathilum\nOrumithuKuda Um Naamathinaal\nthanthani kirubaikaga Umakendrum\nSthothiram Sthothirame!"),
      Verse(6, "Neerella Engaluku\nParallogill Yarundu Jeevanatha\nNeraeandri igathil veroru\nThetamillai parane"),
    ],
  ),
  Song(id: 477, number: 19,
    title: "Kartharai Nambiye Jeevippom",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Kartharai Nambiye Jeevippom\nKavalai Kastangal Theerndhidum ]-2\nKaividaa Kaathidum Paramanin\nKarangalai Naam Patri Kolvom ]-2"),
      Verse(1, "Jeeva Dhevan Pin Selluvom\nJeeva Oli Dhanai Kandadaivom\nManadhin Kaarirul Neengidave\nMaa Samaadhaanam Thangum ]-2"),
      Verse(2, "Unmai Vazhi Nadandhidum\nUthamanukkenrum Karthar Thunai\nKangal Avar Meedhu Vaithiduvaar\nKaruthaai Kaathiduvaar]-2"),
      Verse(3, "Ullamadhin Baarangalai\nOokkamaai Kartharidam Solluvom\nIkkatu Nerathil Koopiduvom\nYesu Vandhaadharippaar]-2"),
      Verse(4, "Anbu Mihum Annalivar\nArumai Yesuvai Nerunguvom\nThammandai Vandhorai Thallidaare\nThaangi Anaithiduvaar]-2"),
      Verse(5, "Needhimanin Sirasin Mel \nNithiya Aaseer Vaadhirangume\nKirubai Nanmaihal Thodarume\nKetpadhu Kidaikkume ]-2"),
    ],
  ),
  Song(id: 478, number: 20,
    title: "Santhosam Ponguthey",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Santhosham ponguthae – (2)\nSanthosham ennil ponguthae\nAlleluya\nYesu ennai iratchiththaar\nMuttrum ennai maattinaar\nSanthosham pongip ponguthae"),
      Verse(1, "Vali thappi naan thirinthaen – paava\nPaliyathai sumanthalainthaen\nAvar anpuk kuralaeAlaiththathu ennaiyae\nAntha inpa naalil\nEnthan paavam neengitte (2)"),
      Verse(2, "Saththuru sothiththida thaeva\nUththaravudan varuvaan\nAanaal Yesu kaividaar\nThaanaay  vanthu iratchippaar\nIntha nalla Yesu enthan\nSonthamaanaarae (2)"),
      Verse(3, "Paavaththil jeevippavar\nPaathaalaththil alinthiduvaar\nNaano paralokaththil\nNaalum paadal paadiduvaen\nEnnil vaalum Yesuvodu\nEntum vaaluvaen (2)"),
    ],
  ),
  Song(id: 479, number: 21,
    title: "Ummai Pola Yarundu",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Ummai Pola Yaarundu\nNanmai Seiya Neerundu\nUmmai Thaane Nampuven\nEn Theva"),
      Verse(1, "Ummai Thaan Enthen Vaalvil\nAathaaramaai Ninaithu Ullen\nNeer Illa Enthen Vaalkai\nVeenaai Thaane Poguthaiya – Ummai Pola"),
      Verse(2, "Elshadaai Aarathipen\nElohim Aarathipen\nAdonaai Aarathipen\nYeshuva Aarathipen – Ummai Pola"),
      Verse(3, "Kalangi Nintra Ennai Kandu\nKaneerai Thudaithavare\nKaalamellaam Kanmani Pola\nKaram Pidithu Kaathavare – Ummai Pola"),
      Verse(4, "Maranathin Paathaithanil\nManam Thalarnthu Nintra Ennai\nMaruthuvaraai Neere Vanthu\nMaruvaalvu Thantheeraiya – Ummai Pola"),
    ],
  ),
  Song(id: 480, number: 22,
    title: "Enakkai Jeevan Vittavare",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Enakkaay jeevan vittavarae\nEnnotirukka elunthavarae\nEnnai entum vali nadaththuvaarae\nEnnaich santhikka vanthiduvaarae"),
      Chorus("Yesu pothumae Yesu pothumae\nEntha naalilumae ennilaiyilumae\nEnthan vaalvinilae Yesu pothumae"),
      Verse(2, "Pisaasin sothanai perukittalum\nSornthu pokaamal mun sellavae\nUlakamum maamisamum mayakkittalum\nMayangidaamal mun sellavae – Yesu"),
      Verse(3, "Pullulla idangalil maeyththiduvaar\nAmarntha thannnneeranntai nadaththiduvaar\nAaththumaavaith thinam thaettiduvaar\nMaranap pallaththaakkil kaaththiduvaar – Yesu"),
      Verse(4, "Manithar ennaik kaivittalum\nMaamisam aluki naarittalum\nAisuvariyam yaavum alinthittalum\nAakaathavan entu thallivittalum – Yesu"),
    ],
  ),
  Song(id: 481, number: 23,
    title: "Enthan Jeba Velai Umai Thedi Vanthen",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Enthan jebavaelai umaith theadi vandhaen\nDhaevaa padhil thaarumae\nEndhan koattai endhan thancham neerae\nUmmai naan naadi vandhaen"),
      Verse(1, "Soaraadhu jebiththida jeba aavi varam thaarumae\nThadaiyaavum agatridumae thayai kaettu umpaadham vandhaen – Endhan"),
      Verse(2, "Ummoadu ennaalum uravaada arul seiyumae\nkarththaavea um vaarththaiyai kaettida kaaththiruppaenae – Endhan"),
      Verse(3, "Nambikkai illaamal azhigindra maandhargalai\nMeetidum en yaesuvae poaraadi jebikkindraen naadhaa – Endhan"),
      Verse(4, "Naalellaam paadhaththil karththaavae kaaththiruppaen\nKanneerin jebam kaelumae karunaiyin piravaagam neerae – Endhan"),
    ],
  ),
  Song(id: 482, number: 24,
    title: "Ennalume Thuthipai",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Ennalume Thuthipai En\nAthumaavae Nee\nEnnaalumae Thudhippaai\nInnaal Varaiyilae Unnadhanaar Seidha\nEnnillaa Nanmaigal Yaavum Maravaadhu"),
      Verse(1, "Paavangal Ethanaiyo\nNinaiyaa Dhirundhaarun\nPaavangal Ethanaiyoa\nPaazhaana Noayai Agatri Gunamaakki\nPaarinil Vaitha Magaa Thayavai Enni"),
      Verse(2, "Ethanaiyoa Kirubai\nUnnuyirkku Seidhaarae\nEthanaiyoa Kirubai\nNithamunai Mudi Suttinadhumandri\nNithiyamaai Un Jeevanai Meettadhaal"),
      Verse(3, "Nanmaiyaalun Vaayai\nNiraithaarea Poorthiyaai\nNanmaiyaalun Vaayai\nUn Vayadhu Kazhugaippoal Balangondu\nOangu Ilamaipoal Aagave Seidhadhaal"),
      Verse(4, "Boomikkum Vaanathukkum\nUlla Dhuram Poalavae\nBoomikkum Vaanathukkum\nSaami Bayamullavar Mael Avar Arul\nSaalavum Thangumae Sathiyamae Idhu"),
      Verse(5, "Mannippu Maatchmaiyaam\nMaadhaevan Arulum\nMannippu Maatchimaiyaam\nEnnuvaayoa Kizhakku Maerkin Thooramae\nMannil Unpaavam Agandrathooramae"),
      Verse(6, "Thandhaithan Pillaikadku\nThayavoadirangaanoa\nThandhaithan Pillaikadku\nEndha Vaelaiyum Avaroadu Thanginaal\nSondham Paaraattiyae Thukki Sumappaarae"),
    ],
  ),
  Song(id: 483, number: 25,
    title: "Siluvai Naadhar Yesuvin",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Siluvai Naadhar Yaesuvin\nPaeroli Veesidum Thooya Kangal\nEnnai Noakki Paarkkindrana\nTham Kaayangalai Paarkkindrana"),
      Verse(1, "En Kaiyaal Paavangal Seidhittaal\nTham Kaiyin Kaayangal Paarkkindraarae\nTheeya Vazhiyil En Kaalgal SendraalTham Kaalin Kaayangal Paarkkindraarae – Siluvai Naadhar"),
      Verse(2, "Theettulla Ennam En Idhayam Kondaal\nEetti Paaindha Nenjai Noakkukindraar\nVeenperumai Ennil Idampetraal\nMulmudi Paarththida Aengukindraar – Siluvai Naadhar"),
      Verse(3, "Avar Rattham En Paavam Kazhuvidum\nAvar Kanneer Ennai Merugaetridum\nKalangarai Vilakkaaga Oli Veesuvaen\nKalanguvoarai Avar Mandhai Saerpaen – Siluvai Naadhar"),
      Verse(4, "Thirundhidaa Paavikkaai Azhukindraar\nVarundhidaa Pillaikkaai Kalangukindraar\nTham Kanneer Kaayaththil Vizhundhida\nKanneerum Ratthamum Sindhukindraar – Siluvai Naadhar"),
    ],
  ),
  Song(id: 484, number: 26,
    title: "Balipeedathil Ennai Parane",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Balippeedaththil ennai paranae\nPadaikkiraenae indha vaelai\nAdiyaenai thirusiththam poala\nAandu nadaththidumae"),
      Chorus("Kalvaariyin anbinaiyae\nKandu viraindhoadi vandhaen\nKazhuvum um thiruraththathaalae\nKarai neenga iridhayaththai"),
      Verse(2, "Neerandri ennaalae paaril\nAedhum naan seidhida iyalaen\nSaerpeerae vazhuvaadhu ennai\nKaaththumakkaai niruththi – Kalvaariyin"),
      Verse(3, "Aaviyoadaathmaa sareeram\nAnbarae umakkendrum eendhaen\nAalayamaakiyae ippoa\nAasirvadhiththarulum – Kalvaariyin"),
      Verse(4, "Suyamennil saambalaai maara\nSuththaaviyae anal moottum\nJeyam petru maamisam saaga\nDhaeva arul seiguveer – Kalvaariyin"),
      Verse(5, "Ponnaiyum porulaiyum virumbaen\nMannin vaazhvaiyum naan veruthaen\nMannavan Yaesuvin saayal\nInnilaththae kandadhaal – Kalvaariyin"),
    ],
  ),
  Song(id: 485, number: 27,
    title: "Um Azhagaana Kangal",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Um Azhagaana Kangal ennai kandathaalae\nMudinthathentu ninaiththa naan uyir vaazhkintaen"),
      Verse(1, "Yaarum ariyaatha ennai\nNantraai arinthu thaedi vantha nalla naesarae"),
      Verse(2, "Thooki eriyappatta ennai Vaendumentu solli\nSaerththu konda nalla naesarae"),
      Verse(3, "Ontumillatha ennai um Kaarunyaththaalae\nUyarththi vaiththa nalla naesarae"),
    ],
  ),
  Song(id: 486, number: 28,
    title: "Neer Illatha Naalellam",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Neer Illatha Naalellam Naalaguma\nNee illatha vaalvuellam vaalva aguma"),
      Verse(1, "Uyirin uttrae nee aavai\nUnmaiyin valiye nee aavai\nUravin pirape nee aavai\nUlathil magilve nee aavai"),
      Verse(2, "Yenathu aatralum nee aavai\nYenathu valimaiyum nee aavai\nYenathu aranum nee aavai\nYenathu kottaiyum nee aavai"),
      Verse(3, "Yenathu ninaivum nee aavai\nYenathu mozhiyum nee aavai\nYenathu meetpum nee aavai\nYenathu uyirupum nee aavai"),
    ],
  ),
  Song(id: 487, number: 29,
    title: "Nandriyodu Naan Thuthi",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Nandriyodu Naan Thuthi Paaduven\nEndhan Yesu Rajane\nEnakkaai Neer Seidhitta Nanmaikkaai\nEndrum Nandri Kooruven Naan – 2"),
      Verse(1, "Ennadangaa Nanmaigal Yaavaiyum\nEnakkaliththidum Nadhane – 2\nNinaikkaadha Nanmaigal Azhippavare\nUmakkendrume Thuthiye – 2 (…Nandriyodu Naan)"),
      Verse(2, "Sathya Deivaththin Yegamaindhane\nVisuvaasippen Ummaiye – 2\nVarum Kaalam Muzhuvadhum Um Kirubai\nVarangal Pozhindhidume – 2 (…Nandriyodu Naan)"),
      Verse(3, "Muzhang kaalgal Yaavum Mudangume\nUndhan Divya Prasannaththinaal – 2\nMuttrum Mudiyaa Ennaiyum Kaappavare\nUmakkendrume Thuthiye – 2 (…Nandriyodu Naan)"),
      Verse(4, "Kalangaadhe Thigaiyaadhe Endravare\nEnnai Kaaththu Nadaththiduveer – 2\nKanmani Pol Ennaiyum Kaapavare\nKarai Serththida Vandhiduveer – 2 (…Nandriyodu Naan)"),
    ],
  ),
  Song(id: 488, number: 30,
    title: "Sarva Srishtikkum Yejamaan Neere",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Sarva Srishtikkum Yejamaan Neere\nSarva sirushtikkum ejamaanan neerae\nSarva sirushtiyai kaappavar neerae\nEngal ithayaththil ummaip paeாttiduvaeாm\nEntentum panneenthu theாluvaeாm"),
      Chorus("Aa-aa-aa al lae loo yaa\nAa-aa-aa al lae loo yaa\nAa-aa-aa al lae loo yaa\nAa-aa-aa al lae loo yaa\nAa-aa-aa aa- maen"),
      Verse(2, "Vaanam poomi olinthu paonaalum\nUm vaarththai entum maaraa\nIlvaalikkai alinthu marainthupaeாm\nVisuvaasi entum nilaiyppaan"),
      Verse(3, "Karththar karaththin kiriyaikal naangal\nKirupai engal mael oottaุveerae\nAavi aaththumaa sareeram um seாnthamae\nAthai saaththaan theாdaamal kaappeerae"),
      Verse(4, "Ellaa manitharkkum aanndavar neerae\nEllaa aaseervaathaththirkum ootte\nEngal ithayaiththai ummidam pataikkinteாm\nAengukinteாm um aaseerperavae "),
      Verse(5, "Sabaiyin asthipaaramum neerae\nSabaiyin thalaiyaanavar neerae\nSabaiyai paeாshiththu paathukaaththentum\nPaarththuk keாlla varupavar neerae"),
    ],
  ),
  Song(id: 489, number: 31,
    title: "Pavangal Pokave Sabangal Neekave",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Pavangal Pokave Sabangal Neekave\nBoologam Vandhaaraiyaa Manidharai Meetkavae\nParalogam Thirakavae Siluvaiyai Sumandaaraiyaa\nKanneerai Thudaithaaraiyaa Sandhosham Thandhaaraiyaa-2"),
      Chorus("Endhan Yesuvae… (4)"),
      Verse(2, "Thangathai Kaetkavillai Vairathai Kaetkavillai\nUllathai Kaetaaraiyaa Aasthiyai Kaetkavillai\nAndhasthai Kaetkavillai Ullathai Kaetaaraiyaa\nNaan Thaedi Pogavilla Ennai Thaedi Vandaaraiyaa -2\nEndhan Yesuvae… (4)"),
      Verse(3, "Thaai Unnai Marandaalum Thandhai Unnai Marandaalum\nAvar Unnai Marakkamattaar Nanbar Unnai Marandaalum\nUttraar Unnai Marandaalum Avar Unnai Marakkamattaar\nKaram Pidithu Nadathiduvaar Kan Malai Mael Niruthiduvaar-2\nEndhan Yesuvae… (4)"),
    ],
  ),
  Song(id: 490, number: 32,
    title: "Yesu Azhaikiraar",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Yesu Azhaikiraar – 2\nAavalaai Unnai Tham Karangal Neetiye\nYesu Azhaikiraar – 2"),
      Verse(1, "Yeththumba Nerathilum\nAaruthal Unakkalippaar – 2\nEndrunarnthu Neeyum Yesuvai Nokkinaal\nYellai Illaa Inbam Pettriduvai – 2 (Yesu Azhaikiraar)"),
      Verse(2, "Kaneerellam Thudaipaar\nKanmanipol Kaappaar – 2\nKaarmegam Pondra Kashtangal Vandhaalum\nKanivode Unnai Kaathidave – 2 (Yesu Azhaikiraar)"),
      Verse(3, "Sorvadaiyum Neraththil\nAaruthal Unakkalippaar – 2\nAvar Un Velichcham Ratchippumaanathaal\nThaamathamindri Nee Vanthiduvaay – 2 (Yesu Azhaikiraar)"),
      Verse(4, "Sagala Vyathiyaium\nKunamaakka Vallavaraam – 2\nYaarayirunthaalum Pethangal Indriye\nKirubaiyaai Anbai Alithidave – 2 (Yesu Azhaikiraar)"),
    ],
  ),
  Song(id: 491, number: 33,
    title: "Sornthu Pogathe Maname",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Sornthu pokaathae manamae\nSornthu pokaathae\nKanndunnai alaiththa Dhevan kaividuvaaro"),
      Verse(1, "Vaakkaliththa thaevanai nee\nPaatik konndaadu\nOokkamaana aavi unnai\nThaanga mantadu"),
      Verse(2, "Thunpangal thollaikal unnai\nSoolnthu konndaalum\nAnpar unnai thaettrum naeram\nAananthamallo"),
      Verse(3, "Sothanaikalai sakippon\nPaakkiyavaanallo\nJeeva kireedam soodum \nnaeram enna paerinpam"),
    ],
  ),
  Song(id: 492, number: 34,
    title: "Kakkum Valla Meetpar",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Thollai kashtangal suzhthidum\nThunbam thukam varum\nInbathil thunbam nerthidum\nIrulaai thondrum yengum\nSothanai varum velayil\nSor kekum seviyile\nParathil irundhu jayam varum\nParan yennai kakka valoar"),
      Chorus("Kakum valla meetpar undu yenaku\nUndu yenaku, undu yenaku\nKakum valla meetpar undu yenaku\nkaathiduvaar yendrume"),
      Verse(2, "Ayam irundhathu oru kaalathil\nAavi kuraivalthaal\nMeetpar uriya belathaal\nSathuruvai vendraen\nYen bayam yaavum neengitru\nYesu kai thoonkinaaru\nMootrum yen ullam maaritru\nYesu yennai kakka valoar!"),
      Verse(3, "Yena vanthaalum nambuvaen\nYen Yesar meetparai\nYaar kai vittalum pin seluvaen\nYenathu yesuvai\nAgala aala uyiramaai\nYevolavu anbu kurundhaaru\nYena thunbangal vaanthalum\nAvar yenai kai vidamaataar"),
    ],
  ),
  Song(id: 493, number: 35,
    title: "Devane Naan Umathandaiyil",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Devane Naan Umathandaiyil – Innum Nerungich\nServathae En Aaval Poomiyil\nMaavaliya Koramaaka Van Siluvai Meethinil Naan\nKovae, Thonga Naeritinum\nAavalaay Ummanntai Servaen"),
      Verse(1, "Yaakkopaippol, Pokum Paathaiyil – Poluthu Pattu\nIraavil Irul Vanthu Mootida\nThookkaththaal Naan Kallil Saaynthu Thoonginaalum En Kanaavil\nNnokkiyummai Kittich Servaen, Vaakkadangaa Nalla Naathaa! – Devane"),
      Verse(2, "Paraththukkaerum Patikal Polavae – En Paathai Thontap\nPannnum Aiyaa, Entan Thaevanae,\nKirupaiyaaka Neer Enakkuth Tharuvathellaam Umathanntai\nArumaiyaay Ennaiyalaiththu Anpin Thoothanaakach Seyyum – Devane"),
      Verse(3, "Niththiraiyinintu Viliththuk – Kaalai Elunthu\nKarththaavae, Naan Ummaip Pottuvaen\nIththaraiyil Unthan Veedaay Enthuyark Kal Naattuvaenae\nEntan Thunpaththin Valiyaay Innum Ummaik Kittich Servaen – Devane"),
      Verse(4, "Aananthamaam Settai Viriththup – Paravasamaay\nAakaayaththil Aerip Poyinum\nVaana Manndalang Kadanthu Paranthu Maelae Sentitinum\nMakilvutru Kaalaththilum Naan Maruviyummaik Kittich Servaen – Devane"),
    ],
  ),
  Song(id: 494, number: 36,
    title: "Kaalamo Selluthe",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Kaalamoa Selludhae Vaalibam Maraiyudhae\nEnnamellaam Veenaagum Kalvi Ellaam Mannaagum\nMagimaiyil Yaesuvai Tharisikuum Naerathil\nAndha Naal Nalla Naal Baakya Naal"),
      Verse(2, "Karunaiyin Azhaipinaal Marana Naeram Varugaiyil\nSutrathaar Soozhndhida Patrulloar Kadharida\nMagimaiyil Yaesuvai Tharisikuum Naerathil\nAndha Naal Nalla Naal Baakya Naal"),
      Verse(3, "Thunbamellaam Maraindhupoam Innal Ellaam Maaripoam\nViyaadhi Ellaam Neengipoam Naayagan Nam Yaesuvaal\nMagimaiyil Yaesuvai Tharisikuum Naerathil\nAndha Naal Nalla Naal Baakya Naal"),
      Verse(4, "Vaazhkaiyai Yaesuvaal Naatkalai Pooripaai\nOattathai Mudikka Kaathukol Visuvaasathai\nMagimaiyil Yaesuvai Tharisikuum Naerathil\nAndha Naal Nalla Naal Baakya Naal"),
    ],
  ),
  Song(id: 495, number: 37,
    title: "Enna En Aanandham",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Enna en aanandham! enna en aanandham!\nSolla koodaadhae\nMannan kiristhu en paavaththaiyellaam\nManniththu vittaarae"),
      Verse(1, "Kooduvoam aaduvoam paaduvoam ondraai\nMagizh kondaaduvoam\nNaadiyae nammai thaediyae vandha\nNaadhanai sthoaththarippoam"),
      Verse(2, "Paavangal saabangal koabangal ellaam\nParikariththaarae\nDhaevaathi dhaevan en ullaththil vandhu\nThangiyae vittaarae"),
      Verse(3, "Atchayan patchamaai ratchippai engalukku\nArulinadhaalae\nNichchayam swaamiyai patriya saatchi\nPagara vaendiyadae"),
      Verse(4, "Vennangi ponmudi vaaththiyam mael veettil\nJeya kodiyudanae\nMannulagil vanthu vinnulagam sendra\nMannanai sthoaththarippoam"),
    ],
  ),
  Song(id: 496, number: 38,
    title: "Sathai Nishkalamai",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Sathai Nishkalamai, oru samiyamamadhai\nSithai Anandamai, Thigazhgindra thiruthavame"),
      Verse(1, "Emma vikurigi, uyireendru pirandadarkor\nKymar undukolo, karayayinai kiyidayan\nSumma ratchanai sei, solsudandaram yadumillai\nAmman unnai allal, yenakarthunai yar udavi"),
      Verse(2, "Thaye, Thandhai tamar, Gurusambathu natpevayum\nNeeye em peruman, Kathi Veriyillai Ninnayangan\nAeye, endrigazhum, ulagodenakennurimai\nAaye, unnai allal enkarthunai arudhavi…….."),
      Verse(3, "Thiraiser Vembavamam, Kadal Muzhgiye Theeyeremai\nKaraiserthuykavendre, puniyayinai kanniliyan….\nParaser patradalil, ennai patriya patruvidai\nArase Unnai Allal, Enakarthunai Arudavi"),
    ],
  ),
  Song(id: 497, number: 39,
    title: "Anukraka Varthaiyode",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Anukraga vaarthaiyoadae -ippoadhu\nAdiyaarai anuppumaiyaa!\nManamadhil dhayavurum magathuvaparanae !\nVandhanam umakkaamen"),
      Verse(2, "Ninthiru naamamadhil kaetta\nNirmalamaam mozhigal\nSandhatham emathagam miga palanalithidac\nSaami ninnarul purivaai"),
      Verse(3, "Sthoathiram pugazh magimai\nKeerthi thudhiganam dhinamumakkae\nPaathiramae adhisoabitha paranae!\nPaadhasaran aamen!"),
    ],
  ),
  Song(id: 498, number: 40,
    title: "Thuthi Ganam Magimaiyumakke",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Thuthi Kanam Makimaiyumakkae\nOh Ellaamumae O Ellaamumae\nThuthi Kanam Makimaiyumakkae\nOh Neerae Raajaavae"),
      Chorus("Sthoththiram Sthoththiram\nSthoththiram Mika Sthoththiram\nSthoththiram Sthoththiram\nOh Neerae Raajaavae"),
      Verse(2, "Thuthi Kanam Makimaiyumakkae\nOh Ellaamumae O Ellaamumae\nThuthi Kanam Makimaiyumakkae\nOh Neerae Raajaavae"),
    ],
  ),
  Song(id: 499, number: 41,
    title: "Thuthithu Paadida",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Thuthiththu paadida paaththiramae\nThungavan Yesuvin naamamathae\nThuthigalin maththiyil vaasam seyyum\nThooyanai neyamaayai sthoththirippomae"),
      Chorus("aa! arputhamae avar nadaththuthalae\naananthamae paramaananthamae\nnanriyaal ullamae miga pongiduthae\nnaam allaelooyaa thuthi saatriduvom"),
      Verse(2, "Kadantha naatkalil kanmanipol\nKaruththudan nammai kaaththaarae\nKarththaraiyae nambi jeeviththida\nKirubaiyum eenthathaal sthoththirippomae"),
      Verse(3, "Akkini oodaay nadanthaalum\nAaziyin thannnneerai kadanthaalum\nSothanaiyo migha peruginaalum\nJeyam namak geenthathaal sthoththiripomae"),
      Verse(4, "Intha vanaanthira yaaththiraiyil\nInbaraam Yesu nammodiruppaar\nPoghaiyilum nam varughaiyilum\nPukalidam aanathaal sthoththarippomae"),
      Verse(5, "Vaanjaikal theerththida vanthiduvaar\nVaarum endre naam azaiththiduvom\nvaanaththilae ondru sernthidum naal\nVirainthu nerungida sthoththarippomae"),
    ],
  ),
  Song(id: 500, number: 42,
    title: "Enthan Navil Pudhu Pattu",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Endhan naavil pudhuppaattu\nEndhan yaesu tharugindraar (2)\n\nAanandham kolluvaen avarai naan\nPaaduvaen uyirulla naal varaiyil allealooyaa (2)"),
      Verse(1, "Paavairul ennai vandhu soozhndhukolgaiyil\nDhaevanavar dheebamaai ennaiththaettinaar – Aanandham"),
      Verse(2, "Vaadhai noayum vandhapoadhu vaendal kaettittaar\nPaadhai kaatti thunbamellaam neekki meettittaar – Aanandham"),
      Verse(3, "Saetril veezhndha ennaiyavar thookkiyeduththaar\nNaatramellaam jeevaraththam kondu maatrinaar – Aanandham"),
      Verse(4, "Thandhai thaayum nanbaruttraar yaavumaaginaar\nNindhai thaangi engumavar maenmai solluvaen – Aanandham"),
      Verse(5, "Ivvulagappaadu ennai enna seidhidum\nAvvulaga vaazhvai kaana kaaththirukkiraen – Aanandham"),
    ],
  ),
  Song(id: 501, number: 43,
    title: "Unnathamanavarin Uyar Maraivil",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Unnadhamaanavarin Uyar Maraivilirukkiravan\nSarva Vallavarin Nizhalil Thanguvaan\nIdhu Parama Silakkiyamae\n\nAvar Setaiyin Keezh\nAdaikkalam Pugavae\nTham Siragugalaal Mooduvaar"),
      Verse(1, "Dhaevan En Adaikkalamae\nEn Koataiyum Aranumavar\nAvar Sathiyam Parisaiyum Kaedagamaam\nEn Nambikkaiyum Avarae"),
      Verse(2, "Iravin Bayangarathirkkum\nPagalil Parakkum Ambukkum – Irulil\nNadamaadum Kollai Noaikkum\nNaan Bayappadavae Maataen"),
      Verse(3, "Aayiram Padhinaayiram Paergal\nUnpakkam Vizhundhaalum – Adhu\nOru Kaalathum Unnai Anugidaadhae\nUn Dhaevan Un Thaabaramae"),
      Verse(4, "Dhaevan Un Adaikkalamae\nOru Pollaappum Unnai Saerumoa\nOru Vaadhaiyum Un Koodaarathaiyae\nAnugaamalae Kaathiduvaar"),
      Verse(5, "Un Vazhigalilellaam\nUnnai Thoodhargal kKaathiduvaar\nUn Paadham Kallil Idaraadhapadi\nThangal Karangalil Aendhiduvaar"),
      Verse(6, "Singathin Maelum Nadandhu\nValu Sarbathaiyum Midhippaai\nAvar Naamathai Nee Mutrum Nambinadhaal\nUnnai Viduvithu Kaathiduvaar"),
      Verse(7, "Aabathilum Avarai Naan\nNoakki Kooppidum Vaelaiyilum\nEnnai Thapuvithae Mutrum Ratchippaarae\nEn Aathuma Naesaravar"),
    ],
  ),
  Song(id: 502, number: 44,
    title: "Thanthen Yennai Yesuve",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Thanthaen ennai Yesuvae\nIntha naeramae umakkae\n\nUnthanukkae ooliyanjaெyyath\nThanthaen ennaith thaangiyarulum"),
      Verse(1, "Jeevakaalam muluthum\nThaevapanni seythiduvaen\nPoovil kadum por purikaiyil\nKaavum unthan karaththinil vaiththu"),
      Verse(2, "Ulakor ennai nerukkip\nPalamaay yuththam seythitinum\nNalamaaych sarvu aayutham poonndu\nNaanilaththinil naathaa velluvaen"),
      Verse(3, "Kashdam nashdam vanthaalum\nThushdar kootich soolnthittalum\nAshdathikkum aalum thaevanae\nAtiyaen ummil amarachcheythidum"),
      Verse(4, "Unthanj siththamae seyvaen\nEntan siththam oliththiduvaen\nEntha idam enakkuk kaattinum\nYesuvae angae itho pokiraேn"),
      Verse(5, "Ontumillai naan aiyaa\nUmmaalanti ontum seyyaen\nAntu seesharkkaliththa aaviyaal\nInte atiyaenai nirappum"),
    ],
  ),
  Song(id: 503, number: 45,
    title: "Theeya Manathai Matra Varum",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Theeya manathai maatta vaarum, thooya aaviyae – kana\nNaeya aaviyae"),
      Verse(1, "Maaya paasath thalunthi vaati maalunj saavithaal – mika maayum\nPaavi naan – theeya"),
      Verse(2, "Theemai seyya naaduthentan thirukku nenjamae – marul\nTheerkkum, thanjamae – theeya"),
      Verse(3, "Paraththai Nnokka manam attenae, pathatithaan, aiyaa – oru\nPaavi naan aiyaa – theeya"),
      Verse(4, "Aekkaththoden meetpaith thaeti iranthu kenjavae – thinam\nIthayam anjavae – theeya"),
      Verse(5, "Puthiya sinthai, puthiya aasai puthuppiththaakkavae – athaip\nPukalnthu kaakkavae – theeya"),
      Verse(6, "Kristhu meethu naattang konndu geetham paadavae – avar\nKirupai thaedavae – theeya"),
      Verse(7, "Thaeva vasanap paalinmeethu thaettam thontavae – miku\nThelivu vaenndavae – theeya"),
      Verse(8, "Jepaththin thaakam akaththil oori jepiththup pottavae – mika\nSirappaay aettavae – theeya"),
    ],
  ),
  Song(id: 504, number: 46,
    title: "Aaviyai Arulume Swamy",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Aaviyai arulumae, suvaamee, enak\nKaayur koduththa vaanaththinarase"),
      Verse(1, "Narkani thaetivarung kaalanga lallavo?\nNaanoru kaniyatta paalmara mallavo?\nMurkani mukangaannaa vempayi rallavo?\nMulunenjam vilaivatta uvarnila mallavo? — aaviyai"),
      Verse(2, "Paavikku aaviyin kaniyenunj sinaekam,\nParama santhosham, neetiya saantham,\nThaeva samaathaanam, narkunam, thayavu,\nThida visuvaasam sirithenumillai — aaviyai"),
      Verse(3, "Theepaththuk kennnaiyaich seekkiram oottrum;\nThiri yaviyaamalae theenntiyae yaettrum,\nPaava asoosangal vilakkiyae maattrum,\nParisuththaavaran thanthen kuraikalaith theerum — aaviyai"),
    ],
  ),
  Song(id: 505, number: 47,
    title: "Amen Alleluia",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Amen Alleluia\nAmen Alleluya! Makaththuvath thamparaaparaa,\nAmen Alleluya! Jeyam! Jeyam! Anantha sthoththiraa\n\nThollai anaathi thanthaar vanthaar iran\nThuyirth thelunthaarae unnathamae! – Amen"),
      Verse(1, "Vettikonndaarp pariththu – kodumvae\nThaalaththaich sangariththu – muriththu\nPathraasanak Kristhu – mariththu\nPaadupattuththariththu mutiththaar – Amen"),
      Verse(2, "Saavin koor otinthu – matinthu\nThaduppuch suvar itinthu – vilunthu\nJeevanae vitinthu – thaevaalayath\nThirai iranndaayk kilinthu olinthathu – Amen"),
      Verse(3, "Vaetham niraivaetti – mey thotti\nMeettuk karaiyaetti – poy maatti\nPaavikalaith thaetti – konndaatti\nPathraasanath thaetti vaalviththaar – Amen"),
    ],
  ),
  Song(id: 506, number: 48,
    title: "Nandriyal Thuthi Paadu",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Nandriyaal thudhipaadu Nam Yaesuvai\nNaavaalae endrum paadu (2)\nVallavar nallavar poadhumaanavar\nVaarthaiyil unmaiyullavar (2)"),
      Verse(1, "Erigoa madhilum Munnae vandhaalum\nYaesu undhan munnae Selgiraar (2)\nKalangidaadhae thigaithidaadhae\nThudhiyinaal idindhu vizhum (2)"),
      Verse(2, "Sengadal nammai Soozhndhu kondaalum\nSiluvaiyin nizhal undu (2)\nPaadiduvoam thudhithiduvoam\nPaadhaigal kidaithu vidum (2)"),
      Verse(3, "Goaliyaath nammai Edhirthu vandhaalum\nKonjamum bayam vaendaam (2)\nYaesu ennum naamam undu\nIndrae jeyithiduvoam (2)"),
      Verse(4, "Dhunmaarkathirku aedhuvaana Very kollaamal\nDheiva bayathoadu endrumae (2)\nAaviyinaal endrum niraindhae\nSangeedha keerthanam paadu (2)"),
      Verse(5, "Sareeram aathumaa aaviyinaalum Soarndhu poagum\nVaelaiyil Ellaam (2)\nThudhi sathathaal ullam niraindhaal\nThooyarin belan kidaikum (2)"),
    ],
  ),
  Song(id: 507, number: 49,
    title: "Nenjae Nee Kalangaathae",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Nenjae Nee Kalangaathae; – Seeyon Malaiyin\nIratchakanai Maravaathae; – Naan En Seyvaenentu.\nVanjar Pakai Seythaalum, Vaaraa Vinai Peythaalum – Nenjae"),
      Verse(1, "Vinaimel Vinai Vandhalum\nPensathi Pilai Mithuru Sathruvaanalum\nManaiyodu Kolai Ponalum, Vaanam\nIdindhu Vizndhalum – Nenjae"),
      Verse(2, "Pattayam, Panjam Vanthaalum, – Athikamaana\nPaadu Nnovu Mikunthaalum,\nMattilaa Varumaip Pattalum,\nManushar Ellaam Kaivittalum – Nenjae"),
      Verse(3, "Sinnaththanam Ennnninaalum – Nee Nanmai Seyyath\nTheemai Pirar Pannnninaalum\nPinnapaethakam Sonnaalum,\nVanthannaappinaalum – Nenjae"),
      Verse(4, "Kallan Entu Pitiththaalum, – Vilangu Pottuk\nKaavalil Vaith Thatiththaalum,\nVellam Puranndu Thalai Meethil\nAlaimothinaalum – Nenjae"),
    ],
  ),
  Song(id: 508, number: 50,
    title: "Deivanbin Vellame",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Verse(1, "Deivanpin Vellamae,\nThiruvarul Thottamae\nMeym Manathaananthamae\nSeyya Ninsempaatham Sevikka Iv Vaelai\nAyyaa Nin Ati Panninthaen"),
      Verse(2, "Sontham Unathallaal Sora Vali Sella\nEnthaay Thunnivaeno Yaan\nPunthikkamalamaam Poomaalai Korththu Nin\nPorpatham Pitiththuk Kolvaen"),
      Verse(3, "Paavach Settil Palavaelai Palamintith\nThaevae Thavaritinum\nKoovi Viliththun Than Maarpodannaith Thanpaay\nYaavum Poruththa Naathaa"),
      Verse(4, "Moorkkunam Kopam Lokam Sittinpamum\nMoka Aekkam Yaavum\nThaakkidath Thadumaarith Thayangidum Vaelaiyil\nThookkith Tharkaaththarulvaay"),
      Verse(5, "Aasai Paasam Pattu Aavalaay Ninthirup\nPoosaip Peedam Pataippaen\nMosa Valithanai Muttu Makattiyen.\nNaesanae Ninaith Tholuvaen"),
      Verse(6, "Maranamo Jeevano Marumaiyo Poomiyo\nMakimaiyo Varungaalamo\nPira Sirushtiyo Uyarnthatho Thaalnthatho\nPiriththidumo Theyvanpai"),
    ],
  ),
  Song(id: 509, number: 51,
    title: "Hosannaa Paaduvom",
    author: "Unknown",
    language: Language.tamil,
    parts: [
      Chorus("Hosannaa Paaduvom, Yesuvin Thaasarae,\nUnnathathilae Thaaveethu Mainthanuku Hosannaa!"),
      Verse(1, "Munnum Pinnum Saalaem Nagar Sinnapaalar Paatinaar\nAndru Pola Intrum Naamum Anbaai Thuthi Paaduvom"),
      Verse(2, "Sinna Mari Meethil Yeri Anbar Pavani Ponaar\nInnum En Akathil Avar Endrum Arasaaluvaar"),
      Verse(3, "Paavamathai Pokkavum Ippaaviyai Kaithookkavum\nPaasamulla Aesaiyaa Pavaniyaaka Pokiraar"),
      Verse(4, "Paalarkalin Geetham Kaettu Paasamaaka Makilnthaar\nJaalar Veennaiyodu Paatith Thaalaimuthi Seikuvom"),
      Verse(5, "Kurutholai Njaayitil Nam Kurupaatham Pannivom\nKooti Arul Pettu Naamum Thiriyaekarai Pottuvom"),
    ],
  ),
  // Malayalam Songs
  Song(
    id: 435,
    number: 1,
    title: "Swargastha Thathan",
    author: "Unknown",
    language: Language.malayalam,
    parts: [
      Chorus("Swargastha thathan sarva lokathe\nIthramel snehichuvo\nPapathil ninnum namme rakshippan\nYeshuvine nalki thaan"),
      Verse(1, "Bhulokam akave papandhakarathin\nKeezhil akappettirunnu\nVazhiyariyathe lakshyamillathe\nUlakil alanju marthyan"),
      Verse(2, "Kaividukilla areyum nadhan\nThannil vishvaasam arpichaal,\nHrithil vasikkum yeshu ennallum,\nNithyamaam jeevan nalkum"),
      Verse(3, "Yeshu thaan vazhiyum sathyavum jeevanum,\nAlambavum thaan evarkkum,\nKsheenithano nee? chare ananjal\nVishraamam nalkum naadhan"),
    ],
