  Song(id: 443, number: 430,
    title: "A Mighty Fortress Is Our God",
    author: "Martin Luther",
    language: Language.english,
    parts: [
      Verse(1, "A mighty fortress is our God, a bulwark never failing;\nOur helper He, amid the flood of mortal ills prevailing.\nFor still our ancient foe doth seek to work us woe;\nHis craft and power are great, and armed with cruel hate,\nOn earth is not his equal."),
      Verse(2, "Did we in our own strength confide, our striving would be losing,\nWere not the right Man on our side, the Man of God’s own choosing.\nDost ask who that may be? Christ Jesus, it is He;\nLord Sabaoth, His name, from age to age the same,\nAnd He must win the battle."),
      Verse(3, "And though this world, with devils filled, should threaten to undo us,\nWe will not fear, for God hath willed His truth to triumph through us.\nThe Prince of Darkness grim, we tremble not for him;\nHis rage we can endure, for lo, his doom is sure;\nOne little word shall fell him."),
      Verse(4, "That word above all earthly powers, no thanks to them, abideth;\nThe Spirit and the gifts are ours, through Him who with us sideth.\nLet goods and kindred go, this mortal life also;\nThe body they may kill: God’s truth abideth still;\nHis kingdom is forever."),
    ],
  ),
  Song(id: 444, number: 431,
    title: "In Christ Alone",
    author: "Keith Getty & Stuart Townend",
    language: Language.english,
    parts: [
      Verse(1, "In Christ alone my hope is found; He is my light, my strength, my song;\nThis cornerstone, this solid ground, firm through the fiercest drought and storm.\nWhat heights of love, what depths of peace, when fears are stilled, when strivings cease!\nMy comforter, my all in all—here in the love of Christ I stand."),
      Verse(2, "In Christ alone, Who took on flesh, fullness of God in helpless babe!\nThis gift of love and righteousness, scorned by the ones He came to save.\nTill on that cross as Jesus died, the wrath of God was satisfied;\nFor ev'ry sin on Him was laid—here in the death of Christ I live."),
      Verse(3, "There in the ground His body lay, Light of the world by darkness slain;\nThen bursting forth in glorious day, up from the grave He rose again!\nAnd as He stands in victory, sin's curse has lost its grip on me;\nFor I am His and He is mine—bought with the precious blood of Christ."),
      Verse(4, "No guilt in life, no fear in death—this is the pow'r of Christ in me;\nFrom life's first cry to final breath, Jesus commands my destiny.\nNo pow'r of hell, no scheme of man, can ever pluck me from His hand;\nTill He returns or calls me home—here in the pow'r of Christ I'll stand."),
    ],
  ),
  Song(id: 445, number: 432,
    title: "How Deep The Father's Love For Us",
    author: "Stuart Townend",
    language: Language.english,
    parts: [
      Verse(1, "How deep the Father's love for us, how vast beyond all measure,\nThat He should give His only Son to make a wretch His treasure.\nHow great the pain of searing loss; the Father turns His face away,\nAs wounds which mar the Chosen One bring many sons to glory."),
      Verse(2, "Behold the Man upon a cross, my sin upon His shoulders;\nAshamed, I hear my mocking voice call out among the scoffers.\nIt was my sin that held Him there until it was accomplished;\nHis dying breath has brought me life—I know that it is finished."),
      Verse(3, "I will not boast in anything: no gifts, no pow'r, no wisdom;\nBut I will boast in Jesus Christ, His death and resurrection.\nWhy should I gain from His reward? I cannot give an answer.\nBut this I know with all my heart: His wounds have paid my ransom."),
    ],
  ),
  Song(id: 446, number: 433,
    title: "Before The Throne of God Above",
    author: "Charitie Lees Smith",
    language: Language.english,
    parts: [
      Verse(1, "Before the throne of God above, I have a strong and perfect plea:\nA great High Priest whose name is Love, who ever lives and pleads for me.\nMy name is graven on His hands, my name is written on His heart;\nI know that while in heav'n He stands no tongue can bid me thence depart,\nNo tongue can bid me thence depart."),
      Verse(2, "When Satan tempts me to despair, and tells me of the guilt within,\nUpward I look and see Him there who made an end of all my sin.\nBecause the sinless Savior died, my sinful soul is counted free;\nFor God the Just is satisfied to look on Him and pardon me,\nTo look on Him and pardon me."),
      Verse(3, "Behold Him there! The risen Lamb, my perfect, spotless Righteousness;\nThe great unchangeable I AM, the King of glory and of grace!\nOne with Himself I cannot die, my soul is purchased by His blood;\nMy life is hid with Christ on high, with Christ my Savior and my God,\nWith Christ my Savior and my God."),
    ],
  ),
  Song(id: 447, number: 434,
    title: "Jesus Paid It All",
    author: "Elvina Hall",
    language: Language.english,
    parts: [
      Verse(1, "I hear the Savior say, \"Thy strength indeed is small;\nChild of weakness, watch and pray, find in Me thine all in all.\""),
      Chorus("Jesus paid it all, all to Him I owe;\nSin had left a crimson stain, He washed it white as snow."),
      Verse(2, "Lord, now indeed I find Thy pow'r, and Thine alone,\nCan change the leper's spots and melt the heart of stone."),
      Verse(3, "For nothing good have I whereby Thy grace to claim;\nI'll wash my garments white in the blood of Calv'ry's Lamb."),
      Verse(4, "And when, before the throne, I stand in Him complete,\n\"Jesus died my soul to save,\" my lips shall still repeat."),
    ],
  ),
];
